dictionary["A short alarm sound with each undercut alert."] = "每次被压价提醒时播放简短警报。"
dictionary["A sidebar like EllesmereUI's: Global settings first (the same for every character: the auction house cut, safety margin, price source and what counts as a flip or a deal), then Profiles, then a page per part of the addon, with tabs across the top for its parts."] = "侧栏结构类似 EllesmereUI：先是所有角色共用的全局设置（手续费、安全余量、价格来源和机会判断标准），再是配置方案，随后按功能分组；每组顶部可切换子标签。"
dictionary["A sound when an auction sells"] = "拍卖售出提示音"
dictionary["A strip on the Dashboard until this character knows riding (then epic riding): what it costs (from the riding trainer once you've seen one, else about 100g and 1,000g), your gold toward it and about how many days at your pace. Off everywhere in Settings, Global settings, Modules; Hide here on one character, /fl fund to show it again."] = "总览中的骑术储蓄目标会在学会骑术前显示，之后显示高级骑术。费用优先采用实际访问的训练师数据，否则估算为约 100 金和 1000 金，并显示当前资金及按现有速度需要的天数。可在全局模块设置中关闭所有角色的显示；当前角色可使用隐藏按钮或 /fl fund 恢复。"
dictionary["A strip under the tiles: the riding this character doesn't know yet (then epic riding), what it costs, how much gold you have toward it and about how many days at your pace. It goes away once learned. Hide here (on the strip) hides it on one character; /fl fund shows it again."] = "显示该角色下一阶段骑术的费用、当前金币及按现有赚钱速度估算的天数。学会后隐藏。条上的隐藏按钮仅影响当前角色；/fl fund 可恢复显示。"
dictionary["A useful early weapon can sell above what it costs to make."] = "实用的初期武器有机会以高于制造成本的价格售出。"
dictionary["A vendor pays"] = "商店收购价"
dictionary["About %s to buy the rest%s. "] = "购买剩余物品约需 %s%s。"
dictionary["Accent color"] = "强调色"
dictionary["Activity"] = "交易活动"
dictionary["Add"] = "添加"
dictionary["Add cheapest fill to a shopping list"] = "将最低填箱方案加入购物清单"
dictionary["Add items above, or Import a shared list."] = "在上方添加物品，或导入分享的清单。"
dictionary["Add items above: shift-click, drag, or type a name (\"Soldier's Armor of the Monkey\" for one version)."] = "在上方按 Shift 点击、拖入或输入物品名称。需要特定属性版本时，请输入包含该属性的完整名称。"
dictionary["Add materials to shopping list"] = "将材料加入购物清单"
dictionary["Add to shopping list"] = "加入购物清单"
dictionary["Added %d %s for %s to the shopping list \"%s\". Set the crate's Want there to fill more than one; tick Buy from this list in the Buy queue to buy what you're short (/fl lists). The list goes when you fill the last crate.%s"] = "已添加%d个%s（用于%s）到购物清单“%s”。要填多个箱子，请在清单中修改箱子的需求量；勾选“从此清单购买”即可在购买队列补齐材料（/fl lists）。最后一个箱子填满后会移除此清单。%s"
dictionary["Added %s to %s."] = "已将 %s 添加到 %s。"
dictionary["Added %s to %s. Check Want and Up to on the list."] = "已将 %s 添加到 %s，请检查清单中的所需数量和价格上限。"
dictionary["Added %s to shopping list \"%s\" (/fl lists)."] = "已将 %s 加入购物清单“%s”（/fl lists）。"
dictionary["Addons can't see a character being deleted or renamed, so it stays here (and on the Characters tab, in Have and in recipes) until you remove it. Remove forgets its level, professions, recipes, bags and bank; prices and gold history stay. One of yours comes back when you log in on it."] = "插件无法得知角色已删除或改名，因此会保留其记录，直到手动移除。移除会清除其等级、专业、配方、背包和银行记录，保留价格和金币历史。自己的角色下次登录时会重新出现。"
dictionary["Adds items and Up to prices; typed prices stay."] = "添加物品及最高买入价，保留手动输入的价格。"
dictionary["Adds one of each you can disenchant. Right-click a row to add only it."] = "每种可分解物品添加 1 件。右键点击某行可只添加该物品。"
dictionary["Ads"] = "广告"
dictionary["Advanced"] = "高级"
dictionary["After an update, chat lists what's new in that version, once. The What's new button (bottom right of Help and the Dashboard) or /fl new shows it as a card."] = "更新后首次登录时，聊天中会列出本版本变化。帮助或总览右下方的更新内容按钮，以及 /fl new，可再次显示。"
dictionary["Alchemist"] = "炼金师"
dictionary["Alchemy"] = "炼金术"
dictionary["Alerts"] = "提醒"
dictionary["All"] = "全部"
dictionary["All %d characters"] = "全部 %d 个角色"
dictionary["All %s characters"] = "所有%s角色"
dictionary["All characters: "] = "所有角色："
dictionary["All characters|r"] = "所有角色|r"
dictionary["All characters|r "] = "所有角色|r "
dictionary["All of it %s, recommended %s.\n"] = "全部费用%s，建议学习费用%s。\n"
dictionary["All realms"] = "所有服务器"
dictionary["All time"] = "全部时间"
dictionary["All versions"] = "全部版本"
dictionary["All, Materials, Gear or Other, and a search box for names."] = "可选择全部、材料、装备或其他，并按名称搜索。"
dictionary["All: every transaction in one list (auction and vendor sales and purchases, repairs, mail, loot, quests...), money in green and out in red. Sales, Purchases, Resale (profit on items bought and sold) and Other show one kind each. Filter by time, character or a word; click a heading to sort; hover a row for the details."] = "全部交易统一列出，包括拍卖和商店买卖、修理、邮件、拾取、任务等。收入绿色，支出红色。可按交易类型、时间、角色或关键词筛选，点击表头排序，悬停查看详情。"
dictionary["Allows for one 8-hour listing that doesn't sell (its deposit is lost): %s."] = "已预留一次8小时挂单未售出造成的保管费损失：%s。"
dictionary["Allows for one listing that doesn't sell (its deposit is lost)."] = "已计入一次流拍所损失的押金。"
dictionary["Almost free to make; people pay to skip the vendor."] = "制造成本很低，玩家可能付费以免去找商店的时间。"
dictionary["Also"] = "其他内容"
dictionary["Also in this version"] = "本版本其他内容"
dictionary["Also print each request in chat."] = "在聊天中也输出每条需求。"
dictionary["Alt-click"] = "Alt 点击"
dictionary["Alt-click (or the click below) an item in your bags, a link in chat or a listing on the auction house: a window with its price graph (up to a year), how many are listed, what you have and have posted, your last 7 days with it, and, if one of your characters can craft it, what that costs and the profit. Price lookup and /fl price <item> open it too."] = "Alt 点击（或下方选定组合键）背包物品、聊天链接或拍卖挂单，即可查看价格图（最长一年）、挂单量、已有和已上架数量、最近七天记录；若角色能制作，还显示成本和利润。也可使用价格查询和 /fl price <item> 打开。"
dictionary["Alt-click an item in your bags, a link in chat or a listing on the auction house (search results, a gear listing, or the item's picture on its buy page; gear with random stats opens on the version you clicked) for its own window. To look up any item, even one you don't have: Price lookup at the top of this window, or /fl price, then type part of its name in the box at the top right. The window shows the usual price, which way it's heading, the cheapest now and how many are listed, how many you have and have posted; a graph of the cheapest and typical price each day for 2 weeks, 3 months or a year (each scan saves a day, and with sync on your other account's scans count too, with days you missed while offline, up to 14, sent over when the two connect; days are kept 90 days, then as weekly averages for a year), with how many were listed as bars and dashed lines for the vendor price or disenchant value and the cost to craft; hover it for each day. Gear with random stats can show one version (of the Eagle). Beside it: your last 7 days with the item and what it's worth to you. If a recipe makes it: the materials at today's prices, what crafting one costs against what it sells for after the cut and one unsold listing (as Worth to you counts it), and the profit; click a material for its own graph. Choose how many crafts and a list to add the materials to a shopping list. Search on the auction house shows it there while the auction house is open. Settings, Tooltips, General turns the click off or changes it to Ctrl-click or Ctrl+Alt-click (if another addon, such as a disenchanting one, uses Alt-click). Ctrl-click then no longer opens the dressing room; with Ctrl+Alt-click, Ctrl-click still does."] = "Alt 点击背包物品、聊天链接或拍卖挂单，可打开该物品的价格窗口；随机属性装备会打开所点变体。窗口顶部“价格查询”或 /fl price 可按名称查询尚未拥有的物品。窗口显示常见价格、趋势、最低价、挂单量、已有和已上架数量；价格图可查看两周、三个月或一年，包含每日最低价与典型价、挂单量柱状图、商店收购价、分解价值和制作成本参考线，悬停可看单日详情。逐日记录保存 90 天，之后按周均价保存一年。双账号同步可补充对方扫描及离线期间最多 14 天的数据。随机装备可单独显示变体。侧栏显示最近七天记录和物品价值。若有已知配方，还会显示现价材料成本、扣除手续费和一次未售出保证金后的收入及利润；点击材料可看其价格图，并可选择制作数量加入购物清单。拍卖行打开时可直接搜索。可在“设置→物品提示→通用”关闭快捷点击或改用 Ctrl、Ctrl+Alt 点击；Ctrl 点击会替代试衣间，Ctrl+Alt 点击则保留原 Ctrl 试衣功能。"
dictionary["Always: the old rank falls behind as you level."] = "每个等级都应升级，旧等级会随着角色升级而落后。"
dictionary["Amount"] = "金额"
dictionary["An hour"] = "每小时"
dictionary["An icon for each step. Hover an icon to read that step."] = "每个图标代表一步，悬停图标可查看说明。"
dictionary["An item is done once its Want has been bought, and stays done, so the queue doesn't keep buying it. Click this to start the list over (next raid): the bought counts go back to 0 and the queue buys every Want again. Check Have first if you still have some."] = "某物品买齐所需数量后会保持完成状态，避免持续购买。点击此按钮可重置整张清单用于下次准备，已购数量归零后重新购买。若仍有存货，请先检查持有数量。"
dictionary["Another addon ran a full scan; Forever Ledger read it too: %d listings across %d items in %ds."] = "已读取其他插件的全扫结果：%d条挂单，涉及%d种物品，读取用时%d秒。"
dictionary["Any %s+ %s trainer, e.g. %s%s"] = "任意%s以上的%s训练师，例如%s%s"
dictionary["Any item's price graph and numbers: type its name. "] = "输入任意物品名称，查看价格图表和数据。"
dictionary["Any price"] = "任意价格"
dictionary["Any town"] = "任意城镇"
dictionary["Any town with customers"] = "有买家的任意城镇"
dictionary["Any type"] = "全部类型"
dictionary["Appearance"] = "外观"
dictionary["Apprentice"] = "初级"
dictionary["Armor"] = "护甲"
dictionary["Armor tested in Forever"] = "已在无限服测试的护甲"
dictionary["Artisan"] = "大师级"
dictionary["At the auction house, click Buy queue: a panel beside it lists things selling for less than a vendor pays, with Watch flips to keep scanning while you're there. Click Buy to buy the next one, or scroll down over its top strip."] = "在拍卖行打开购买队列，侧栏会列出低于商店收购价的物品。可开启监测继续扫描，点击购买或在顶部条向下滚动以购买下一件。"
dictionary["At the auction house, click Full scan (allowed about every 15 minutes)."] = "在拍卖行点击“全扫”（约每 15 分钟可用一次）。"
dictionary["At the auction house, click Full scan. It reads every listing in a few seconds; the game allows one about every 15 minutes. Prices and flips work from the first scan; deals and sell speed get sharper as a few days of scans build up."] = "在拍卖行点击全扫，几秒内读取全部挂单。游戏约每 15 分钟允许一次。价格和卖店套利从第一次扫描即可使用；低价转售和销售速度会随着扫描数据积累而更准确。"
dictionary["Auction"] = "拍卖"
dictionary["Auction and vendor prices"] = "拍卖价格与商店价格"
dictionary["Auction and vendor prices in tooltips"] = "物品提示中的拍卖和商店价格"
dictionary["Auction deposits back"] = "退还的拍卖保管费"
dictionary["Auction house"] = "拍卖行"
