dictionary["Auction house:"] = "拍卖行："
dictionary["Auction house: %s after the %d%% cut"] = "拍卖收入：%s，已扣除 %d%% 手续费"
dictionary["Auction price"] = "拍卖价格"
dictionary["Auction price ("] = "拍卖价格（"
