dictionary["Auction sale"] = "拍卖出售"
dictionary["Auction sales"] = "拍卖出售"
dictionary["Auction sales a day"] = "每日拍卖出售"
dictionary["Auction, cheapest"] = "拍卖最低价"
dictionary["Auction, cheapest: the lowest price listed at your last scan, how many were listed, and (in gray) how long ago. Under it, when different: the average of the 20 cheapest, about what you'd pay buying a few. Values in Forever Ledger use that average, so one odd cheap listing doesn't sway them. With your own prices over 12 hours old, Auctionator's or TSM's price is used if you have them, and named."] = "“拍卖最低价”显示上次扫描的最低挂单价、数量和报价时间；若不同，还显示最便宜 20 件的均价，估算批量买入成本。插件估值采用此均价，避免单条异常低价影响结果。自有报价超过 12 小时后，若装有 Auctionator 或 TSM，会使用其价格并标明来源。"
dictionary["Auctions"] = "我的拍卖"
dictionary["Auto"] = "自动"
dictionary["Auto uses TSM's history where it has a price, otherwise your own scans."] = "有价格记录时使用 TSM 历史数据，否则使用自己的扫描。"
dictionary["Auto uses your own scans while they're fresh, then other auction addons."] = "优先使用未过期的自有扫描，再使用其他拍卖插件的数据。"
dictionary["Automatic"] = "自动"
dictionary["Avg buy"] = "平均买入价"
dictionary["Avg sell"] = "平均卖出价"
dictionary["Bag price per slot"] = "背包每格价格"
dictionary["Bags"] = "背包"
dictionary["Bags and bank"] = "背包与银行"
dictionary["Bags not saved yet: log in on it once."] = "尚未保存背包数据：请先登录该角色一次。"
dictionary["Bags worth"] = "背包估值"
dictionary["Bank"] = "银行"
dictionary["Bank and alts as of their last visit. Click to search the auction house."] = "银行和其他角色数据以上次读取为准，点击可在拍卖行搜索。"
dictionary["Bank worth"] = "银行估值"
dictionary["Based on"] = "依据"
dictionary["Below"] = "低于"
dictionary["Below level 20: ways to make gold while leveling, best first, each priced from your scans (skinning, mining, herbs, cloth, bags, wands for casters, disenchanting and more). Lines for a profession you don't have are dimmed (tick Only my professions to hide them; other classes' lines never show), and (Classic) means not yet confirmed in Forever. Hover a line for what to do and why; click to search the auction house. Part of Leveling help: Settings, Global settings, Modules."] = "20 级以下角色会看到按扫描价格计算、从优到劣排列的升级赚钱方式，包括剥皮、采矿、草药、布料、背包、法杖及分解等。未学专业的行会变灰，可勾选仅我的专业隐藏；其他职业项目不显示。“经典旧世”表示尚未在无限服确认。悬停查看方法和理由，点击搜索拍卖行。可在“全局设置→模块→升级赚钱建议”中关闭。"
dictionary["Below usual price by"] = "比常见价格至少低"
dictionary["Beside the auction house (Buy queue button, Disenchant finder tab): green armor and weapons in the item levels you pick (the Item levels dropdown, with Select all and Deselect all), with what each is worth to disenchant, on average, if you sell the materials. Hover a row to see each material's price and how that adds up. Hover a level in that list for the odds and what a bad and a good roll would bring (Settings, Auction house can hide the rolls). Pick a regular shopping list or New list, then Add to shopping list for one of every shown row your Enchanting can disenchant; right-click a row to add only it. Up to uses the disenchant value less the safety margin, refreshed when added again, on Buy again or by right-clicking Up to. Type a lower price for a bigger margin; typed prices stay yours. New lists start with buying off. Any stat version of each item will do."] = "在拍卖行旁“购买队列→分解筛选”中，选择装等范围查看绿装武器和护甲，显示分解材料转售的平均价值。可全选或取消全选装等。悬停物品看材料价格和合计，悬停装等看概率及较差、较好结果，可在设置中隐藏范围。选择清单后加入，会为你附魔技能可分解的每行各添加一件；右键可只加一件。价格上限为分解价值扣安全余量，再次添加、再次购买或右键上限可刷新。手动更低价会保留。新清单默认关闭购买。任意随机属性变体都可。"
dictionary["Besides the average, what a band's greens are worth on a bad roll and a good one (the least and the most a disenchant can give)."] = "除平均值外，还显示该装等绿装在较差或较好分解结果下的价值（分解产出最少和最多的情况）。"
dictionary["Best and biggest"] = "最高收益与最大交易"
dictionary["Best loot"] = "最高价值拾取"
dictionary["Best of auction and vendor"] = "拍卖与商店价值取高"
dictionary["Best way"] = "最佳用途"
dictionary["Best way: "] = "最佳用途："
dictionary["Better by"] = "优势"
dictionary["Between full scans, the likeliest to turn into flips: items priced near what a vendor pays, weighed by how many get posted and bought each day (Linen Cloth before a rare item), with crafted items counting extra since crafters post them in bulk. Gear is left out."] = "全扫间隔期间，复查最可能出现卖店套利的物品：接近商店收购价、日常上架和买入数量较大的物品。制成品因常被批量上架而获得额外权重，装备不包含在内。"
dictionary["Big message on screen"] = "屏幕大字提示"
dictionary["Biggest purchase"] = "最大购买交易"
dictionary["Biggest sale"] = "最大出售交易"
dictionary["Blacksmith"] = "锻造师"
dictionary["Blacksmithing"] = "锻造"
dictionary["Blizzard nerfed most vendor shuffles, so this tab may often be empty."] = "暴雪削弱了多数卖店加工套利，因此此页可能经常为空。"
dictionary["Booty Bay"] = "藏宝海湾"
dictionary["Booty Bay (15% cut)"] = "藏宝海湾（15% 手续费）"
dictionary["Booty Bay against your auction house, each after its own cut (15% there): items worth 10% more to sell there, or cheaper to buy there. Hover for the numbers."] = "比较藏宝海湾与你的拍卖行，分别扣除手续费（中立为 15%）。列出在当地卖价至少高 10% 或买价更低的物品，悬停可查看数字。"
dictionary["Booty Bay compares the neutral auction house (Booty Bay, Gadgetzan, Everlook) with yours, each after its own cut: 15% there. Its prices come from opening it and scanning there, and are kept apart from yours everywhere else."] = "比较中立拍卖行（藏宝海湾、加基森、永望镇）与你的拍卖行，分别扣除手续费，中立为 15%。需到当地打开拍卖行扫描，价格独立保存。"
dictionary["Booty Bay prices from "] = "藏宝海湾价格时间："
dictionary["Booty Bay, Gadgetzan and Everlook keep their own prices and take a 15% cut (your faction's takes 5%), which values, sell protection and the Auctions tab count while you're there. The Auctions tab lists what you have up there apart from your faction's."] = "藏宝海湾、加基森和永望镇使用单独价格库，手续费为 15%（阵营拍卖行为 5%）。在对应拍卖行内，估值、上架保护和拍卖页均按相应费率处理，并分别列出你在中立和阵营拍卖行的挂单。"
dictionary["Booty Bay, when it pays clearly more"] = "藏宝海湾收益明显更高时显示"
dictionary["Bought"] = "已买入"
dictionary["Bought "] = "买入"
dictionary["Bought %d %s for %s."] = "已购买 %d 个 %s，花费 %s。"
dictionary["Bought %d for %s%s"] = "已购买 %d 个，花费 %s%s"
dictionary["Bought for this list"] = "此清单已购"
dictionary["Bought for this list, then in brackets what you own: 3 (20) is 3 bought, 20 owned."] = "此清单已购数量，括号内为持有数量：3 (20) 表示已购 3 个，持有 20 个。"
