dictionary["Cheapest way to fill each Waylaid Crate at your last scan's prices, best Favor per gold first. After your first turn-in (a one-time quest), every crate pays 5s and 10 Merchant's Favor; Net cost takes the 5s off, and shows green if a crate somehow pays for itself. You have %s Merchant's Favor on this character.%s Click a crate for every bundle."] = "按上次扫描价格计算各补给箱的最低填箱成本，优先显示每金币可获得青睐更多的方案。首次交付任务后，每个箱子奖励5银和10点商人的青睐；净成本已扣除5银，如果奖励足以覆盖成本则显示绿色。当前角色持有%s点商人的青睐。%s点击箱子可查看全部材料组合。"
