dictionary["Checks the auction house for everything on the list at once. Each item shows when it was checked (checking... and in line while it runs), how many are listed and the cheapest. Click an item to look at it on the auction house."] = "一次检查清单中的全部物品。每件物品显示查询时间、当前挂单量及最低价。点击物品可在拍卖行中查看。"
dictionary["Checks the auction house for everything on your lists ticked \"Buy from this list in the Buy queue\" (and the materials you're short of), one item at a time. What's at or under your price shows up here."] = "逐项检查已勾选“加入购买队列”的清单物品及短缺材料。价格不超过上限的挂单会出现在这里。"
