dictionary["Clear the types you set on %d recipes? They go back to automatic. This can't be undone."] = "要清除%d个配方的自定义类型吗？这些配方会恢复自动分类，此操作无法撤销。"
dictionary["Click Buy (or tick Scroll to buy and scroll here)."] = "点击“购买”，或勾选“滚轮购买”后在此滚动。"
dictionary["Click Buy queue on the auction house: a panel beside it lines up vendor flips and your shopping lists. Click a section to buy from it; it finds the next one by itself, and a click on Buy (or, with Scroll to buy ticked, a tick of the mouse wheel down over its top strip) buys it. Stacks of materials take a second tick to confirm the final price. Bottom right: what you bought this visit, what it cost and the profit if you vendored it (hover for the numbers). /fl queue."] = "点击拍卖行的购买队列按钮，在侧栏查看卖店套利和购物清单。选择分区后会自动查询下一件，点击购买或启用滚轮购买后在顶部条向下滚动以确认。堆叠材料需要再确认一次最终报价。右下方汇总本次买入物品、成本和卖商店后的预计利润，悬停可看明细。也可使用 /fl queue 打开。"
