dictionary["Deals tab, Booty Bay (top right): the neutral auction house against yours, each after its own cut (15% there, 5% here) and one unsold listing. Sells for more there: items worth at least 10% more sold at Booty Bay. Cheaper there: buy at Booty Bay, sell here. Its prices come from scanning there and are kept apart from yours; a tooltip line for big differences is in Settings, Tooltips."] = "低价机会页右上方的藏宝海湾视图比较中立与阵营拍卖行，分别扣除 15% 和 5% 手续费，以及一次未售出保证金。“那里卖得更高”列出在藏宝海湾卖出价值至少高 10% 的物品；“那里更便宜”列出适合在那里买入、回本阵营出售的物品。中立价格来自当地扫描，单独保存。明显价差的物品提示可在设置中开启。"
dictionary["Deals tab: profit after the auction house cut, reselling at the usual price or under the next listing. \"off\" for no minimum."] = "低价机会页：按常见价格或略低于下一档挂单转售、扣除手续费后的利润。输入“off”取消最低要求。"
