dictionary["Doing something else while you wait for a chime? /fl quiet turns the game's sound off and plays Forever Ledger's chimes at full volume, even with the game in the background, plus a chime when you win an auction. It stays on for that character, through reloads and logins, until you type /fl quiet again. Quiet mode while the flip watch runs (Settings, Auction house, Alerts) does it by itself, and /fl pair offers to turn that on. Your sound settings come back afterward."] = "/fl quiet 会关闭游戏声音，以全音量播放 Forever Ledger 提示音，游戏在后台时也生效，购买成功也有提示。对当前角色持续生效，重载和重登后保留，直到再次输入命令。也可在“设置→拍卖行→提醒”中设置为监测时自动启用；/fl pair 也会提示此选项。关闭后恢复声音设置。"
