dictionary["Every recipe of your professions, who knows it, where to get it, the skill needed, and profit per craft. Right-click a recipe to set its type yourself. Click a column heading to sort."] = "列出你的专业配方、掌握它的角色、获取方式、所需技能和每次制作利润。右键可手动设置类型，点击表头可排序。"
dictionary["Everything"] = "全部内容"
dictionary["Everything Forever Ledger records is kept in its saved file on your computer. Nothing is sent to the author or anyone else."] = "插件记录的全部数据保存在本机保存文件中，不会发送给作者或其他人。"
dictionary["Everything in the list above, each at its Each price. Search and the Bags / Bank buttons change it."] = "按各物品的单件价值汇总上方列表。搜索条件及背包、银行按钮会影响结果。"
dictionary["Everything this many crafts need, added to what the list already wants. Up to starts at your usual price plus the list's allowance; prices you typed stay. What you already have isn't taken off: check Want on the list."] = "把指定制作次数所需的材料追加到清单。价格上限初始为通常价格加清单溢价，手动价格保持不变。已有材料不会扣除，请检查清单中的所需数量。"
dictionary["Expenses"] = "支出"
dictionary["Expert"] = "高级"
dictionary["Export"] = "导出"
dictionary["Export / import"] = "导出 / 导入"
dictionary["Export / import on the Characters tab, to copy everything across by hand (and Prices as text)."] = "角色页的“导出 / 导入”可手动复制全部数据，也可将价格导出为文本。"
dictionary["Export / import profile"] = "导出 / 导入配置"
dictionary["Export and import"] = "导出与导入"
dictionary["Export copies this character's profile as text, with only the parts you tick. Import makes a new profile from someone's text. Only settings travel: never Global settings, gold or any of your data."] = "导出可把当前配置中勾选的部分复制为文字；导入会用他人的文字创建新配置。仅传递设置，不包含全局设置、金币或其他数据。"
dictionary["Extra chat lines for testing."] = "在聊天中显示额外测试信息。"
dictionary["Extra materials from kills you were making anyway, with almost no start-up cost."] = "从任务击杀中额外获得材料，几乎不需要前期投入。"
dictionary["FL Bronze"] = "FL 青铜"
dictionary["FL Clean"] = "FL 简洁"
dictionary["FL Clean: flat and quiet. FL Bronze: a bronze edge, gold titles, sections as cards, switches. FL Gilded: a bronze frame and gold serif titles. Looks based on WoW Forever's and Blizzard's own windows are coming."] = "简洁：扁平、低干扰；青铜：铜色边缘、金色标题、卡片分区和开关；鎏金：铜色边框与金色衬线标题。未来将提供参考无限服和游戏原有窗口的主题。"
dictionary["FL Gilded"] = "FL 鎏金"
dictionary["FLIP"] = "套利"
dictionary["Fast"] = "快"
dictionary["Fast, Steady, Slow, Rare or No sales seen, once there are 3 hours of scans to judge by (and, in the first day, at least 3 sales)."] = "累计可比较的扫描达到三小时后，显示“快、稳定、慢、少见、未观察到成交”。首日还需要至少三次观察到的成交。"
dictionary["Fill cost"] = "填箱成本"
dictionary["Fills the price box with 1 copper under the cheapest listing from your last scan. You still click Post."] = "按上次扫描最低价减 1 铜填入价格框，仍需自行点击上架。"
dictionary["Fills the price box with the usual price from your scans this month. You still click Post."] = "按本月扫描记录的通常价格填入价格框，仍需自行点击上架。"
dictionary["Filter"] = "筛选"
dictionary["Find deals"] = "寻找低价机会"
