dictionary["Flip or shuffle, Crafts that sell, Enchant service, Not for sale, Not profitable."] = "套利或加工套利、适合出售的制品、附魔服务、不出售、无利润。"
dictionary["Flip watch"] = "套利监控"
dictionary["Flip watch back on (it was on when you left). Stop it in the Buy queue panel."] = "套利观察已恢复（上次离开时仍在运行）。可在购买队列面板停止。"
dictionary["Flip watch on: a full scan every 15 minutes, and items near vendor price re-checked in between. "] = "套利观察已开启：每15分钟全扫一次，期间复查接近商店收购价的物品。"
