dictionary["Flip watch."] = "持续监测套利。"
dictionary["Flip watch: nothing close to vendor price; waiting for the next full scan."] = "套利观察：暂无价格接近商店收购价的物品，等待下次全扫。"
dictionary["Flip watch: re-checking"] = "套利观察：正在复查"
dictionary["Flips and deals"] = "套利与低价机会"
dictionary["For %s, your tree."] = "适用于你当前的%s天赋。"
dictionary["For %s. Spend talent points and this gets clearer."] = "适用于%s。分配天赋点后可提供更明确的建议。"
dictionary["For %s; you level as %s."] = "适用于%s；你当前使用%s升级。"
dictionary["For example 10c or 1s. \"off\" for no minimum. A flip needs both this and the share above."] = "例如 10c（10 铜）或 1s（1 银）。输入“off”取消最低金额要求。套利机会须同时满足金额和上述比例条件。"
dictionary["For items added by hand. Each list starts at 10%; choose 0, 5, 10, 25 or another percentage. Applied when you switch buying on or click Buy again. Typed prices and shuffle caps stay as they are."] = "适用于手动添加的物品，每张清单默认允许高于通常价格 10%。可设为 0、5、10、25 或其他百分比；启用购买或点击“重新购买”时生效。手动设置的价格和加工套利上限保持不变。"
dictionary["For lists where you just need the items, like raid prep: prices are ignored and the Buy queue buys the cheapest ones until it has bought the number you want (1 if no number is set). It never pays more than 3 times an item's usual price, so a joke listing can't slip in. Type any in one item's price for just that item."] = "适用于必须买齐物品的清单，例如团队副本准备。忽略通常价格限制，购买队列会从最低价开始买到所需数量，未设置数量则买 1 个。单价仍不超过通常价格的 3 倍，以免误买异常高价挂单。单个物品的价格也可输入 any。"
dictionary["Forever Ledger"] = "永恒账本"
dictionary["Forever Ledger hears it from guildmates and group members who have a newer version, and says so in chat once a session. It only shares the version number."] = "从公会或队伍中使用较新版本的玩家获取版本号，每次会话在聊天中提醒一次。仅分享版本号。"
dictionary["Forever Ledger's lines on item tooltips."] = "Forever Ledger 添加的物品提示行。"
dictionary["Forever Ledger: reload now to see the new look?"] = "Forever Ledger：现在重新加载界面以应用新外观？"
dictionary["Forever Ledger|r  "] = "Forever Ledger|r  "
dictionary["Formula"] = "公式"
dictionary["Found a bug?"] = "发现问题？"
dictionary["Found a vendor flip: %s (vendor pays %s), but you can't afford it yet: %s each, you have %s."] = "发现卖店套利机会：%s（商店收购价%s），但当前金币不足：每件%s，你持有%s。"
dictionary["From Classic: not yet confirmed in Forever"] = "经典服资料：尚未在无限服核实"
