dictionary["Full scan"] = "全量扫描"
dictionary["Full scan done: %d listings across %d items in %s."] = "全扫完成：%d条挂单，涉及%d种物品，用时%s。"
dictionary["Full scan done: %d listings across %d items, about %d min after Forever Ledger asked for one."] = "全扫完成：%d条挂单，涉及%d种物品，距 Forever Ledger 发出请求约%d分钟。"
dictionary["Full scan in %d:%02d"] = "全量扫描倒计时 %d:%02d"
dictionary["Full scan or materials."] = "全扫或扫描材料。"
dictionary["Full scan: Ready"] = "全量扫描：已就绪"
dictionary["Full scans aren't available in this client. Use /fl scan materials instead."] = "当前客户端不支持全扫，请改用 /fl scan materials 扫描材料。"
dictionary["Gather the herbs near your quests. Mageroyal and Briarthorn sometimes give Swiftthistle as a bonus."] = "采集任务区域附近的草药。魔皇草和石南草有时会附带雨燕草。"
