dictionary["Gear with random stats (of the Eagle) also shows the price of that exact version."] = "带随机属性的装备（如“雄鹰之”）也会显示对应变体的价格。"
dictionary["Gear: versions with different stats sell at different prices."] = "装备的不同属性版本可能有不同售价。"
dictionary["General"] = "通用"
dictionary["Getting started"] = "入门"
dictionary["Getting the final price for "] = "正在获取最终报价："
dictionary["Global settings"] = "全局设置"
dictionary["Go now"] = "立即继续"
dictionary["Goes away once this character knows it. Settings, Global settings, Modules turns it off everywhere; Hide here on this character."] = "该角色学会后自动隐藏。在“设置 → 全局设置 → 模块”中可对所有角色关闭；“对此角色隐藏”只影响当前角色。"
