dictionary["Help that mentions \"%s\", from every topic."] = "所有主题中提到“%s”的帮助。"
dictionary["Herbalism"] = "草药学"
dictionary["Herbs go into potions (now First Aid in Forever) and skill-ups, so they keep selling."] = "草药可用于制作药水（无限服归入急救）和专业冲级，因此持续有需求。"
dictionary["Here"] = "这里"
dictionary["Hidden from addons"] = "插件无法读取"
dictionary["Hide here"] = "对此角色隐藏"
dictionary["Hide the riding fund on this character"] = "对此角色隐藏骑术储蓄"
dictionary["Hold Ctrl for price history"] = "按住 Ctrl 查看价格历史"
dictionary["Hold Ctrl over an item for the cheapest price over the last 14 days, which way it's heading, the usual price this month, how many are usually listed and the lowest price ever seen."] = "悬停时按 Ctrl，查看最近 14 天最低价、趋势、本月常见价、常见挂单量和历史最低价。"
dictionary["Hold Ctrl over an item: the cheapest price over the last 14 days, whether it's rising or falling, the usual price this month, how many are usually listed and the lowest price ever seen. It builds up with each scan."] = "悬停物品时按 Ctrl，查看最近 14 天最低价、涨跌趋势、本月常见价、常见挂单数量和历史最低价。历史会随着扫描逐渐积累。"
dictionary["Hold Shift for Forever Ledger details"] = "按住 Shift 查看 Forever Ledger 详情"
dictionary["Hold Shift for Forever Ledger details, Ctrl for price history"] = "按住 Shift 查看 Forever Ledger 详情，按 Ctrl 查看价格历史"
dictionary["Hover Up to for its source. From a shuffle: its buying cap, not today's price; if two shuffles use an item, the lower cap wins. Add the shuffle again or use Buy again to refresh it. Added by hand: usual price plus this list's allowance (Pay up to X% over the usual price, starting at 10%); change the percentage on each list, then switch buying on or use Buy again to fill it. Type any price yourself, including off: it always wins and is never changed automatically. Existing limits are treated as yours. A shuffle route that can no longer be valued turns off until refreshed with known prices."] = "悬停最高买入价可查看来源。加工套利采用其采购上限，多个加工项目共用材料时取较低上限；再次添加加工项目或点击再次购买可刷新。手动添加的物品采用常见价加清单溢价，初始为 10%；可修改清单比例，再启用购买或再次购买填入。手动价格和 off 始终优先，不会自动覆盖，已有上限按手动值保留。无法再估值的加工路线会暂停，直到用已知价格刷新。"
dictionary["Hover a deal: the usual cheapest and typical prices and how many days of your scans they come from, how many are usually listed, and the next listing up. Profit assumes you resell at the usual cheapest price or just under the next listing, whichever is lower. Click to search the auction house."] = "悬停查看常见最低价、典型价格、扫描天数、常见挂单量和下一档价格。预计转售价取常见最低价与略低于下一档挂单价中的较低者。点击可在拍卖行中搜索。"
dictionary["Hover a spell for why. Advice only."] = "悬停技能可查看原因，仅供参考。"
dictionary["Hover any item to see what it's worth to you. Settings can make it short (today's cheapest price and what it's worth to you), with Shift for more. With 20 or more listed, selling on the auction house is valued from today's prices; with fewer, from this month's usual price if that's lower, so a few hopeful listings don't fool it, and a grey line says so."] = "悬停物品可查看对你的价值。设置中可选择精简提示（今日最低价与物品价值），按 Shift 查看更多。拍卖挂单至少有 20 件时按今日价格估值；更少时，若本月常见价更低则采用常见价，并以灰字说明，避免少量高价挂单影响判断。"
dictionary["How Forever Ledger's windows look. A change shows after a reload."] = "Forever Ledger 窗口外观。修改后重新加载界面生效。"
dictionary["How big Forever Ledger's windows are, from 75% to 150%. Drag, then let go."] = "窗口缩放范围为 75%～150%。拖动后松开滑块即可生效。"
dictionary["How fast an item sells: Fast, Steady, Slow, Rare (seldom listed, goes quickly) or No sales seen, judged against items of the same kind, so ore and swords aren't held to the same bar. It counts listings that vanished before they could have expired, so it builds up as you run full scans (fastest with Watch flips) and shows after 3 hours of scans compared (and, in the first day, at least 3 sales)."] = "销售速度分为快、稳定、慢、少见（挂单少但很快消失）和未观察到成交，按同类物品比较，材料与装备使用不同标准。根据两次扫描之间在到期前消失的挂单估计，并非实际成交回报。比较数据累计三小时后显示，首日还需至少三次观察到的成交。持续监测可更快积累。"
dictionary["How fast it sells"] = "销售速度"
dictionary["How it works"] = "使用方式"
dictionary["How items are valued"] = "物品估值方式"
dictionary["How long it's kept"] = "保存时长"
dictionary["How many are listed cheaply enough to make a profit."] = "价格足够低、可获利的在售数量。"
dictionary["How many steps, including the sale."] = "包含出售在内的步骤数量。"
dictionary["How many times you could do it profitably with what's listed now: only listings cheap enough count, and the scarcest thing you buy on the auction house sets the limit. \"no limit\" when everything comes from vendors."] = "按当前挂单可盈利执行的次数：只计算价格足够低的挂单，并受最稀缺拍卖材料限制。全部来自商店时显示“不限”。"
dictionary["How many to buy. Empty is one. Type any to keep buying it whenever it's at or under Up to; it's never marked done. (With Up to any, it buys one: any of both would buy every listing.)"] = "要购买的数量，留空表示 1 个。输入 any 后，会持续购买价格不超过上限的挂单，且不会标记为完成。若价格上限也设为 any，则只买 1 个，以免买下所有挂单。"
dictionary["How many ways to use an item to list, best first."] = "列出多少种用途，按价值从高到低排列。"
dictionary["How sure"] = "可靠程度"
dictionary["How sure: "] = "可靠程度："
dictionary["How to get the most for it. Hover an item for the whole way."] = "收益最高的处理方式。将鼠标移到物品上可查看完整步骤。"
dictionary["If Auctionator or another addon runs a full scan, Forever Ledger reads it too. With Auctionator, TSM or ForeverForge installed, features they already cover (like auction prices in tooltips, or a sound when an auction sells) are switched off once, with a message; turn them back on in Settings."] = "Auctionator 或其他插件完成全扫后，Forever Ledger 也会读取结果。检测到 Auctionator、TSM 或 ForeverForge 后，会一次性关闭其已提供的重复功能（如拍卖价格提示或售出声音）并说明；可在设置中重新开启。"
dictionary["If all bought"] = "全部买下"
dictionary["If the flip watch was on when you closed the auction house, start it again when you come back. It can only scan while the auction house is open."] = "离开拍卖行时若正在监测，下次回来时继续。监测只能在拍卖行打开期间扫描。"
dictionary["If you resell"] = "如果转卖"
dictionary["Import"] = "导入"
dictionary["Import shopping lists"] = "导入购物清单"
dictionary["Import text ends early. Make sure you copied all of it."] = "导入文本不完整，请确认已复制全部内容。"
dictionary["Import text is damaged near character "] = "导入文本在以下字符位置附近损坏："
dictionary["Import text is damaged."] = "导入文本已损坏。"
dictionary["Imported"] = "已导入"
dictionary["Imported %d characters and %d prices."] = "已导入%d个角色和%d项价格。"
dictionary["Imported %d settings as the profile %s; this character uses it now. Switch back any time in Settings, Profiles."] = "已导入 %d 项设置，创建配置 %s 并为此角色启用。可随时在“设置→配置方案”中切换。"
dictionary["In original Classic (unconfirmed in Forever):"] = "原经典服资料（尚未在无限服核实）："
dictionary["In your bags"] = "背包中"
dictionary["In your bank"] = "银行中"
dictionary["In your mailbox: |cff7fd39c%s|r (%s)"] = "邮箱金币：|cff7fd39c%s|r（%s）"
dictionary["It also always leaves you %s (Settings, Auction house)."] = "同时始终保留 %s（设置→拍卖行）。"
dictionary["It binds and no vendor buys it"] = "该物品会绑定，且商店不收购"
dictionary["It finds gold for you: things to buy and sell on, and what your crafting is worth. Five things to start with:"] = "查找低买高卖的机会，计算制作价值。从以下五项开始："
dictionary["It never pays more than the limit shown (checked again on the final price) or more than you have, and every purchase is your own tick or click, as Blizzard requires. Scroll to buy only works with the mouse over the top strip; untick it to buy by clicking only. Right-click an item to skip it. Items you can't afford yet stay at the bottom of the list, grayed and marked can't afford, and are skipped until you have the gold; scroll past the last one you can buy and you get the error sound and a red message, once."] = "不会支付高于显示上限或现有金币的价格，最终报价还会再次检查。每笔购买都需要你点击或滚动一次。滚轮购买仅在顶部条内生效，也可关闭后仅用点击。右键跳过物品。买不起的物品保留在底部、变灰并标注；处理完所有买得起的项目后，会播放一次错误音并显示红色提示。"
dictionary["It only answers addons every second or so; this carries on by itself."] = "拍卖行大约每秒响应一次插件请求，随后会自动继续。"
dictionary["It sells slowly for how many are listed."] = "相对于上架数量，售出速度较慢。"
