dictionary["Item levels: all"] = "物品等级：全部"
dictionary["Item levels: none"] = "物品等级：未选择"
dictionary["Items"] = "物品"
dictionary["Items from your shopping lists ticked \"Buy from this list in the Buy queue\", at or under your price."] = "已勾选“加入购买队列”的购物清单物品，仅购买价格不超过上限的挂单。"
dictionary["Items one of your recipes makes have a Buy/Craft button: set Craft and the list shows the materials for the number you want, with Up to for each (usual price plus this list's allowance unless you type one) and how many are bought. Materials a vendor sells are marked vendor. Hover an item one of your recipes makes: what buying it would cost against buying the materials to craft it, and which is cheaper."] = "可由某个角色制作的物品会显示购买/制作按钮。选择制作后，清单列出所选数量需要的材料、各材料价格上限和已购数量。默认上限为常见价加清单溢价，手动价格优先。商店材料会标注商店。悬停可比较直接买成品和购买材料制作的成本，判断更便宜的方式。"
dictionary["Items quests ask for (Bronze Tube, Spider Ichor, Flask of Oil...) list the quest, its level and how many, for your faction. In yellow with keep it when this character hasn't reached that level yet, so you don't vendor it. Quests this character has done, ones gray for its level and other classes' quests are left out (Settings, Tooltips: Only quests this character still needs; off shows them all, marked). Leveling players buy these once per character, so they sell; the Deals tab's hover says when a deal is one. From original Classic quests: Forever may have changed some."] = "需要某种物品的任务会显示任务名称、等级和数量，仅限本阵营。当前角色以后需要时会以黄色提示保留，避免误卖。默认排除已完成、等级过低或其他职业任务；可在设置中关闭此筛选并查看标记后的完整列表。升级角色会按需购买这些物品，低价机会提示也会标记任务物品。任务数据来自经典旧世，无限服可能有所修改。"
dictionary["Journeyman"] = "中级"
dictionary["Judged on"] = "评估依据"
dictionary["Just under the cheapest"] = "略低于最低价"
dictionary["Keep every rank as it comes: it's a spell you lean on, and an old rank falls behind."] = "学到新等级时及时升级：这是常用技能，旧等级效果会落后。"
dictionary["Keep in mind"] = "注意"
dictionary["Keep them on"] = "保持开启"
dictionary["Keeping data"] = "数据保存"
dictionary["Keeps looking for flips while the auction house stays open: a full scan whenever the game allows one (about every 15 minutes) and quick checks of likely items in between. New flips chime and join the queue. Click again to stop."] = "拍卖行打开期间持续查找套利机会：游戏允许时进行全量扫描（约每 15 分钟一次），其间快速查询可能有机会的物品。新机会会播放提示音并加入队列，再次点击可停止。"
dictionary["Keeps looking for items below vendor price while the auction house stays open: a full scan every 15 minutes, quick checks in between. Chimes when it finds one, and new flips join the Buy queue."] = "拍卖行打开期间持续查找低于商店收购价的物品：每 15 分钟进行一次全量扫描，其间快速查询。发现机会时播放提示音，并加入购买队列。"
dictionary["Kept them on. You can change this any time in Settings."] = "已保持开启。可随时在设置中修改。"
dictionary["Kill humanoids on your quests: keep the Linen, vendor the gray items, check any greens. Move on when the camp is crowded."] = "任务中击杀人形怪时保留亚麻布，将灰色物品卖给商店，检查绿色装备的价值。营地拥挤时可换地方。"
dictionary["Known"] = "已学会"
