dictionary["Leaves out quests this character has done, ones gray for its level, and other classes' quests. Off: all of them, marked (done), (too low) or (other class), handy when selling to others."] = "排除已完成、等级过低或其他职业的任务。关闭后会全部显示并标注，便于给他人出售物品。"
