dictionary["Ledger, Sessions (or See all sessions on the Dashboard): every session with when, length, gold, what you looted, gold an hour and the character; sort by any column. Hover one for where its gold came from and the best loot."] = "账本的会话页（或总览中的全部会话）列出每次会话的时间、时长、金币、拾取、每小时金币和角色。可按列排序，悬停查看收入来源和最好拾取。"
dictionary["Left out %d your Enchanting is too low for (marked \"skill\")."] = "已排除附魔等级不足的 %d 项，标有“技能”。"
dictionary["Length"] = "时长"
dictionary["Level"] = "等级"
