dictionary["Leveling tab"] = "升级赚钱页"
dictionary["Like price, flip, list, scan or sound. Or pick a topic on the left."] = "例如价格、套利、清单、扫描或声音，也可选择左侧主题。"
dictionary["Limited supply"] = "限量供应"
dictionary["Linen and coin from humanoid camps"] = "在人形怪营地获取亚麻布和金币"
dictionary["Link"] = "配对"
dictionary["Link your other account"] = "配对另一个账号"
dictionary["Link your other account in Settings, Characters (or /fl pair First Last, on both characters): prices and recipes go between your two accounts while both are online: your characters first, then the prices (those can take several minutes), then the days of price history the other missed while offline (up to 14, about a minute a day). Pairing asks whether it's your own account: say yes and your gold and sales go too, so both Dashboards and Ledgers match. They include your buyers' names, so say no for a friend. Every new link starts with sharing off and asks again. Change that with \"Share gold and sales\", and share bags and bank with \"Share bags and bank\" (both in Global settings, Advanced). /fl unpair stops it and removes the other side's characters, gold and sales; the prices stay."] = "在“设置→角色”或用 /fl pair First Last 双向配对自己的另一个账号。双方在线时先同步角色，再同步价格（可能数分钟），最后补充对方离线时缺失的最多 14 天价格历史（约每天一分钟）。配对会询问是否为自己的账号，确认后可分享金币和买卖，使总览、账本一致；其中包含买家名称，配对朋友时应拒绝。每次新配对都从关闭分享开始询问。可在“全局设置→高级”修改金币销售及背包银行分享。/fl unpair 停止同步并移除对方角色、金币和销售，保留价格数据。"
dictionary["Link your other account, see every character Forever Ledger knows about, and remove ones you no longer have."] = "配对自己的另一个账号、查看插件记录的所有角色，以及移除已不再使用的角色。"
dictionary["Linked to %s: |cff7fd39conline|r. Share gold and sales, or bags and bank, in Global settings, Advanced."] = "已配对 %s：|cff7fd39c在线|r。可在“全局设置→高级”中选择分享金币、交易、背包和银行。"
dictionary["Linked to %s: |cffee8597not seen online yet|r. Both characters need to be online and linked to each other."] = "已配对 %s：|cffee8597尚未检测到在线|r。双方角色都必须在线并互相配对。"
