dictionary["Listings at or below an item's buy limit get a green tint, bar and BUY badge."] = "价格不高于买入上限的挂单会显示绿色底色、标记条和“购买”标识。"
dictionary["Listings well below the price an item is usually cheapest at, to buy and resell: price now, usual low, how many are worth buying, profit after the cut and one unsold listing, and how sure it is (Good, Fair or Thin)."] = "列出明显低于常见最低价、适合买入转售的挂单，显示现价、常见最低价、值得购买的数量、扣除手续费和一次未售出保证金后的利润，以及数据可靠程度。"
dictionary["Listings well below the price they're usually cheapest at, to buy and resell. Hover a deal for why it's one; "] = "明显低于通常最低价的挂单，可买入后转售。悬停查看判断依据；"
dictionary["Listings worth buying get a green bar and a badge saying why (FLIP, DE, CRAFT, USE), and the line above says how many are left."] = "值得购买的挂单会显示绿色标记条及原因标识（套利、分解、制作、使用），上方显示剩余数量。"
