dictionary["Named lists of items, for example twink gear to watch for or raid consumables to buy. Pick a list from the dropdown at the top; New, Rename and Delete are beside it. With the list open, shift-click an item to add it (or drag it, or type its name: names are suggested as you type, Enter takes the top one). Open them anywhere, to plan before you go to the auction house: the Shopping lists button at the top of this window, Shift-click on the minimap button, or /fl lists."] = "可建立带名称的购物清单，例如小号装备或团队消耗品。顶部下拉框选择清单，旁边可新建、改名或删除。Shift 点击、拖入物品或输入名称均可添加；输入时会提示名称，Enter 选择首项。可以在任何地方规划：窗口顶部购物清单按钮、Shift 点击小地图按钮或 /fl lists 均可打开。"
