dictionary["No deals yet. Deals need prices from the last hour (a full scan or the flip watch) and at least 4 days of scans "] = "尚无机会。需要最近一小时内的价格数据（全量扫描或套利监控），以及至少 4 天扫描记录，"
dictionary["No disenchants recorded yet. Disenchant some items, then /fl de. (/fl de reset starts a fresh count.)"] = "暂无分解记录。分解物品后输入 /fl de 查看；/fl de reset 可重新统计。"
