dictionary["No gold recorded in this range yet."] = "此时间范围内暂无金币记录。"
dictionary["No item called \"%s\" found. Try part of its name."] = "找不到名为“%s”的物品，请尝试输入部分名称。"
dictionary["No item levels picked: choose some under Item levels."] = "尚未选择物品等级：请在“物品等级”中勾选。"
dictionary["No items both bought and sold for these filters yet. Once you've bought and sold the same item, its profit shows here."] = "当前筛选条件下暂无已买入又卖出的物品。同一物品完成买入和卖出后，会在此显示利润。"
dictionary["No lists here yet: on the Shopping lists tab, tick Buy from this list in the Buy queue."] = "尚无可购买的清单：请在“购物清单”中勾选“加入购买队列”。"
