dictionary["No money in or out recorded today yet."] = "今天暂无收支记录。"
dictionary["No other money for these filters yet: repairs, mail, trades, loot, quests, training and flights show here by day."] = "当前筛选条件下暂无其他收支。修理、邮件、交易、拾取、任务、训练和飞行费用会按日显示在此。"
dictionary["No position recorded for that yet."] = "尚未记录该目标的位置。"
