dictionary["No sales for these filters yet. Auction sales are logged when you take the money from the mailbox; vendor sales as you sell."] = "当前筛选条件下暂无出售记录。领取拍卖邮件中的金币时记录拍卖收入；卖给商店时即时记录。"
