dictionary["No sessions for these filters yet. Start one with Start a session on the Dashboard (or /fl session start); it's listed here when you stop it."] = "当前筛选条件下暂无统计时段。在总览中点击“开始统计”或输入 /fl session start，停止统计后会列在此处。"
