dictionary["No trainers seen yet. Open a profession trainer's window."] = "尚未记录训练师，请打开专业训练师窗口一次。"
dictionary["No version called \"%s\" has turned up in your full scans yet: check the spelling. Added anyway; Search all looks for names containing it."] = "全量扫描尚未发现名为“%s”的版本，请检查拼写。仍会添加该物品；“搜索全部”会查找包含此名称的挂单。"
dictionary["No. Every purchase and auction is your own click (or wheel tick), as Blizzard requires. Forever Ledger finds, suggests and queues."] = "不会。每次购买和上架都需要你点击或滚动一次，这是游戏要求。插件只负责发现机会、建议和排列队列。"
dictionary["No: the game only lets addons search with the auction house open. The watch pauses when you close it and picks up when you come back."] = "不能。游戏只允许在拍卖行打开期间搜索。关闭后暂停，返回时继续。"
dictionary["None"] = "无"
dictionary["None at current prices. Scan the auction house, then click Refresh."] = "按当前价格暂无机会。请扫描拍卖行，再点击“刷新”。"
dictionary["None bought in %d hours of scans: it may not sell."] = "%d小时扫描中未观察到购买，可能难以售出。"
dictionary["None listed at the last Search all (%s)."] = "上次“搜索全部”时无挂单（%s）。"
dictionary["None undercut at the last check."] = "上次检查时没有被压价的拍卖。"
dictionary["None yet. Start a session to count what your time is worth."] = "暂无统计。开始统计后可查看游玩期间的收益。"
dictionary["Not a price yet"] = "尚不是有效价格"
dictionary["Not for sale"] = "不出售"
dictionary["Not in Forever Ledger's list for your class yet."] = "Forever Ledger 尚未收录该职业的此项技能建议。"
dictionary["Not known"] = "未学会"
dictionary["Not needed leveling as %s."] = "使用%s天赋升级时可暂缓。"
dictionary["Not profitable"] = "无利润"
dictionary["Not reviewed yet"] = "尚未评估"
dictionary["Not ticked"] = "未勾选"
dictionary["Not while leveling. Come back to it at 60, or if you start using it."] = "升级期间可暂缓，可在60级或开始使用此技能时再学。"
dictionary["Note"] = "说明"
dictionary["Nothing bought or sold"] = "暂无买卖记录"
dictionary["Nothing earned, spent or looted in it."] = "该时段没有收入、支出或拾取。"
dictionary["Nothing else is listed right now to compare with."] = "当前没有其他挂单可供比较。"
dictionary["Nothing found"] = "未找到内容"
dictionary["Nothing here matches the filter: %d %s hidden by it. Click All, or clear the search box."] = "没有符合筛选条件的机会：%d 项 %s 已隐藏。可点击“全部”或清空搜索框。"
dictionary["Nothing here matches the search."] = "没有符合搜索条件的物品。"
dictionary["Nothing here."] = "暂无物品。"
dictionary["Nothing is at least 10% cheaper at Booty Bay than it sells for here, after the cut."] = "扣除手续费后，没有在藏宝海湾买入比这里卖价至少低 10% 的物品。"
dictionary["Nothing listed on this character. What you put up on the auction house shows here."] = "此角色尚无在售物品，拍卖行上架后会显示在这里。"
dictionary["Nothing new to learn at this level.\n"] = "当前等级没有可学习的新技能。\n"
dictionary["Nothing recorded for these filters yet. Auction sales are logged when you take the money from the mailbox; purchases, vendor trades and other money as they happen."] = "当前筛选条件下暂无记录。领取拍卖邮件中的金币时记录拍卖收入；购买、商店交易及其他收支会即时记录。"
dictionary["Nothing saved for this character yet: log in on it once (and open its bank to see that too)."] = "尚未保存该角色的数据：请先登录一次，打开银行后也会记录银行物品。"
dictionary["Nothing saved from the bank yet: open the bank on this character once."] = "尚未保存银行数据：请用该角色打开银行一次。"
dictionary["Nothing sells for at least 10% more at Booty Bay than here, after both cuts."] = "分别扣除手续费后，没有在藏宝海湾出售比这里至少多赚 10% 的物品。"
dictionary["Nothing sold lately."] = "最近没有售出记录。"
dictionary["Nothing to buy yet."] = "暂无可购买物品。"
dictionary["Nothing to check: everything you listed has sold."] = "无需检查：你上架的物品均已售出。"
dictionary["Now"] = "当前"
dictionary["Offer your best water and food to groups and people asking in Trade, for a tip. The Customers window spots them."] = "向队伍和交易频道中有需求的玩家提供当前最好的饮水和食物，收取小费。客户窗口可帮助发现需求。"
dictionary["On a Mage from level 40: portal requests, and the Sell portals button."] = "40 级以上法师：识别传送门需求，并提供传送门服务按钮。"
dictionary["On a Mage: requests for water and food, and the Sell food and water button."] = "法师角色：识别食水需求，并提供出售食水按钮。"
dictionary["On a Rogue from level 16: lockbox requests, and the Offer lockpicking button."] = "16 级以上盗贼：识别开锁需求，并提供开锁服务按钮。"
dictionary["On a Warlock from level 20: summon requests, and the Offer summons button."] = "20 级以上术士：识别召唤需求，并提供召唤服务按钮。"
dictionary["On a Waylaid Crate: the cheapest way to fill it at today's prices."] = "在补给箱上显示按当前价格补满所需物品的最低成本。"
dictionary["On a bag: what one slot costs at today's cheapest price (auction house or vendor), and the cheapest bag per slot right now."] = "显示当前最低价格下每个背包格的成本，以及当前每格价格最低的背包。"
dictionary["On the Sell tab, if a vendor pays more than your listing would bring after the auction house cut, a red line under Post says so and Post is grayed out until you click Post anyway. Settings, Auction house: untick Stop posts below vendor price to keep just the warning."] = "若卖给商店的收入高于拍卖扣费后的收入，上架按钮下会显示红色提示，并禁用上架，直到点击仍然上架。若只希望保留警告，可在拍卖行设置中取消阻止低于商店收购价上架。"
dictionary["On the Sell tab, under the Create Auction button: your usual price and the cheapest now, with Undercut (1 copper under the cheapest) and Usual buttons that fill in the price. When the cheapest is well below usual it says so, so you can wait. You still click Post (Settings, Auction house)."] = "在出售页的创建拍卖按钮下方，显示常见价与当前最低价。压价按钮填入低于最低价 1 铜，常见价按钮填入常见价。最低价明显低于常见价时会提示，方便决定是否等待。仍需自己点击上架，可在拍卖行设置中调整。"
dictionary["On the Sell tab, when a vendor would pay more than the auction house after its cut, Post is grayed out until you click Post anyway. Off: just the warning."] = "若卖商店的收入高于拍卖扣费后的收入，“上架”会禁用，直到点击“仍然上架”。关闭后仅显示警告。"
dictionary["On the auction house"] = "在拍卖行中"
dictionary["On the auction house at the last Search all (%s):"] = "上次“搜索全部”时的拍卖挂单（%s）："
dictionary["On the auction house: keeps scanning while it stays open and chimes when a new vendor flip turns up. It can only scan with the auction house open: it pauses when you close it and picks up again when you come back (Settings, Auction house: Resume the flip watch)."] = "拍卖行打开时持续扫描，发现新的卖店套利机会会提示。关闭拍卖行后暂停，下次返回时继续（可在“设置→拍卖行→恢复套利监测”中调整）。"
dictionary["On the way: |cff7fd39c%s|r%s"] = "寄送中：|cff7fd39c%s|r%s"
dictionary["One craft at today's prices (vendor where cheaper)"] = "按当前价格制作一次；商店更便宜时采用商店价格"
dictionary["One line, only on items that bring at least 25% more at the neutral auction house (Booty Bay, Gadgetzan, Everlook) after its 15% cut, from your last scan there. Off by default; the Deals tab's Booty Bay view lists them all."] = "根据上次中立拍卖行扫描，只为扣除 15% 手续费后收益至少高 25% 的物品增加一行提示。默认关闭；低价机会页的藏宝海湾视图会列出全部物品。"
dictionary["One unsold listing"] = "一次流拍"
dictionary["One version"] = "指定变体"
dictionary["Only live sync to your own paired character (off until /fl pair), and ads in Trade when you click an ad button."] = "仅向自己的配对角色进行实时同步（使用 /fl pair 前关闭），以及点击广告按钮时在交易频道发广告。"
dictionary["Only worth disenchanting"] = "仅显示值得分解的物品"
dictionary["Open Deals"] = "打开低价机会"
dictionary["Open Help"] = "打开帮助"
dictionary["Open a crate and click Add cheapest fill to a shopping list: the crate and its items go on a list named after the crate, with prices high enough to buy them all at your last scan. What you already have counts towards a crate list's Want (only crate lists do this). Tick Buy from this list in the Buy queue on it to buy what you're short. Set the crate's Want to fill several at once: every item's Want follows it. The list is temporary: each crate you fill takes one off, and the list goes with the last one (or after a week)."] = "打开补给箱并选择把最低成本交付材料加入清单，会创建以箱子命名的清单，含箱子和材料，并按上次扫描价格设置足够购买的上限。补给箱清单会扣除已拥有数量，这是此类清单的特例。勾选购买后补齐缺少物品。调整箱子目标数量可同时填多个箱子，材料目标会跟随。每交一个箱子会扣除一次目标，最后一个完成或一周后删除临时清单。"
dictionary["Open a shuffle or vendor flip, pick a regular list or New list, choose how many crafts (or items), then Add to shopping list. Its purchases and price limits are added; an existing item keeps its bought count and any price you typed. A disenchant group uses its cheapest item. Crate lists and lists with Any price are left out. New lists start with buying off: check Want and Up to and tick Buy from this list when ready."] = "打开加工或卖店套利项，选择现有清单或新建清单，再选择制作或购买数量，点击加入购物清单。清单会加入采购项目及价格上限；已有物品保留已购买数量和手动价格。分解组采用其中最便宜的物品。不使用补给箱清单或任意价格清单。新清单默认关闭购买，设置目标数量和上限后再勾选按清单购买。"
dictionary["Open each profession window once on every character."] = "在每个角色上分别打开一次各个专业窗口。"
dictionary["Open each profession window once on every character. Forever Ledger reads your recipes from it."] = "在每个角色上分别打开一次专业窗口，以便插件读取配方。"
dictionary["Open or close the window."] = "打开或关闭窗口。"
dictionary["Open shopping lists"] = "打开购物清单"
dictionary["Open the Buy queue after a full scan"] = "全扫后打开购买队列"
dictionary["Open the Customers window"] = "打开客户窗口"
dictionary["Open the auction house first, then click Search again."] = "请先打开拍卖行，再次点击“搜索”。"
dictionary["Open the auction house first, then start the flip watch."] = "请先打开拍卖行，再开始套利观察。"
dictionary["Open the auction house first."] = "请先打开拍卖行。"
dictionary["Open the auction house to see your auctions."] = "打开拍卖行即可查看你的拍卖。"
dictionary["Open the auction house, then Search all."] = "打开拍卖行后点击“搜索全部”。"
dictionary["Open the auction house, then click a deal to search for it."] = "打开拍卖行后，点击机会即可搜索。"
dictionary["Open the auction house, then click a flip to search for it. Right-click a flip for details."] = "打开拍卖行后点击卖店套利项目进行搜索，右键查看详情。"
dictionary["Open the auction house, then click a line to search for it."] = "先打开拍卖行，再点击条目搜索物品。"
dictionary["Open the auction house, then click an item to search for it."] = "先打开拍卖行，再点击物品进行搜索。"
dictionary["Open this window"] = "打开窗口"
dictionary["Open your class trainer: a panel beside it sorts what you can learn now into Must have, Nice to have and Skip while leveling (Dampen Magic, say), with the gold each costs and what you'd save. Spells for another tree than the one your talent points are in go to Skip; a spell you know but haven't cast in a week to Nice to have. Hover a spell for why and when to upgrade. It shows at class and portal trainers, not riding ones, and not once you're 60. Advice only: you train in Blizzard's window. Settings, Global settings, Modules."] = "打开职业训练师时，侧栏将可学法术分为必学、可选、升级期间可缓，显示费用和可节省金币。非主天赋树法术通常归为可缓，已学但一周未用的法术归为可选。悬停查看理由和升级时机。在职业和传送门训练师处显示，不在骑术训练师处显示，60 级后停止。只提供建议，仍在原窗口学习。可在全局模块设置中调整。"
dictionary["Opening the auction house: one line in chat with what sold since you were last there, and the gold it brings."] = "打开拍卖行时，在聊天中显示自上次访问以来售出的物品及所得金币。"
dictionary["Opens on a new request. /fl customers opens it any time."] = "发现新需求时打开。/fl customers 可随时打开。"
dictionary["Opens when someone in chat asks for what your character can do, with Whisper and Invite buttons. x hides one request; Clear all (bottom right) hides them all. /fl customers opens it any time."] = "聊天中出现当前角色可提供的服务需求时打开，提供密语和邀请按钮。x 隐藏单条需求，“全部清除”隐藏所有需求。/fl customers 可随时打开。"
dictionary["Opens with"] = "打开方式"
dictionary["Original Classic recipe (skill %d, makes %g): Forever may differ. Open the profession window on a character who knows it to use theirs."] = "原版经典旧世配方（技能 %d，产出 %g）：无限服可能不同。请在已学会此配方的角色上打开专业窗口，以使用该角色的数据。"
dictionary["Other"] = "其他"
dictionary["Other addons"] = "其他插件"
dictionary["Other characters keep it. /fl fund shows it here again; Settings, Global settings, Modules turns it off everywhere."] = "其他角色仍会显示。输入 /fl fund 可为当前角色恢复；在“设置 → 全局设置 → 模块”中可对所有角色关闭。"
dictionary["Other characters: on this ruleset and faction, as of their last login."] = "同规则、同阵营其他角色的持有量，以各角色上次登录记录为准。"
dictionary["Other characters: on this ruleset and faction, none have any."] = "同规则、同阵营其他角色均未持有。"
dictionary["Other income"] = "其他收入"
dictionary["Other professions"] = "其他专业"
dictionary["Other spending"] = "其他支出"
dictionary["Other versions:"] = "其他版本："
dictionary["Over your limit: the cheapest is %s and %s is left of your Spend at most for this visit."] = "超过预算：最低价 %s，本次访问剩余预算 %s。"
dictionary["Over your limit: the cheapest is %s and buying it would take you below the %s you keep (Settings, Auction house)."] = "超过预算：最低价 %s，购买后金币将低于保留额 %s（设置→拍卖行）。"
dictionary["Overview"] = "概况"
dictionary["Paid skill-ups with no stock to sell."] = "提供服务时有机会提升技能，无需囤积成品。"
dictionary["Paste a profile with Ctrl+V, then click Import. It becomes a new profile and this character switches to it; your other profiles stay as they are."] = "按 Ctrl+V 粘贴配置，再点击导入。会新建配置并为当前角色启用，其他配置保持原样。"
dictionary["Paste a shared list with Ctrl+V and click Import. A plain list of item names (or Wowhead links), one per line, works too. Your own lists are never changed: an import with the same name is added as a new list."] = "按 Ctrl+V 粘贴分享的清单，再点击“导入”。也支持每行一个物品名称或 Wowhead 链接。已有清单不会被修改；导入同名清单时会另建一张。"
dictionary["Paste an export from your other account with Ctrl+V, then click Import. Newer data replaces older data."] = "按 Ctrl+V 粘贴另一账号导出的数据，再点击“导入”。较新数据会替换较旧数据。"
dictionary["Paste here (Ctrl+V)"] = "在此粘贴（Ctrl+V）"
dictionary["Pattern"] = "图样"
dictionary["Paused while you search the auction house yourself."] = "你正在手动搜索拍卖行，队列已暂停。"
dictionary["Pay up to"] = "最高支付"
dictionary["Per Favor"] = "每点青睐成本"
dictionary["Per craft"] = "每次制造"
dictionary["Per hour"] = "每小时"
dictionary["Per slot (%d slots)"] = "每格价格（%d 格）"
dictionary["Physician"] = "医师"
dictionary["Pick another click if a different addon uses Alt-click (some disenchanting addons do). Ctrl-click no longer opens the dressing room; with Ctrl+Alt-click, Ctrl-click still does."] = "若其他插件使用 Alt 点击，可改用另一组合键。Ctrl 点击会替代试衣间；选择 Ctrl+Alt 点击时，Ctrl 点击仍可打开试衣间。"
dictionary["Pick herbs as you go"] = "顺路采草药"
dictionary["Pin"] = "标记"
dictionary["Plan your shopping"] = "计划采购"
dictionary["Plans"] = "设计图"
dictionary["Players moving past copper need tin and bronze."] = "专业进度超过铜制品的玩家需要锡和青铜。"
dictionary["Plays the raid warning sound when a scan finds new vendor flips or deals."] = "扫描发现新的卖店套利或低价机会时，播放团队警报音。"
dictionary["Plus %d more%s. Type /fl shuffles all to see everything."] = "另有%d项%s。输入 /fl shuffles all 可查看全部。"
dictionary["Post anyway"] = "仍然上架"
dictionary["Post your crafting (with profession links) to Trade, and on those classes your food and water, portals, summons or lockpicking. Right-click a button to change the text."] = "向交易频道发布带专业链接的制作服务广告，或相应职业的食水、传送门、召唤与开锁服务。右键按钮修改文案。"
dictionary["Posted"] = "上架价格"
dictionary["Press Ctrl+A, then Ctrl+C to copy. Paste it into Import on your other account, or send it to Claude."] = "按 Ctrl+A 全选，再按 Ctrl+C 复制。可粘贴到另一账号的导入窗口，或发送给 Claude。"
dictionary["Press Ctrl+A, then Ctrl+C. Paste this into a chat with Claude to check flips at today's prices."] = "按 Ctrl+A 全选，再按 Ctrl+C 复制。可将此内容粘贴到与 Claude 的对话，按当前价格检查套利机会。"
dictionary["Press Ctrl+C to copy, then paste it in Discord (between ``` marks keeps it tidy) or send it to a friend. They paste it into Import on their Shopping lists tab."] = "按 Ctrl+C 复制，再粘贴到 Discord 或发送给朋友。在 Discord 中用 ``` 包裹可保留排版；对方可在“购物清单→导入”中粘贴。"
dictionary["Price"] = "价格"
dictionary["Price each"] = "单价"
dictionary["Price everything"] = "为所有物品获取价格"
dictionary["Price helper"] = "价格助手"
dictionary["Price helper on the Sell tab"] = "出售页价格助手"
dictionary["Price history"] = "历史价格"
dictionary["Price history while Ctrl is held"] = "按住 Ctrl 显示历史价格"
dictionary["Price history: every item keeps 90 days of daily prices, and full scans keep each version of random-stat gear (\"of the Eagle\") on its own."] = "历史价格：每件物品保留 90 天逐日价格，全扫还会分别记录随机属性装备（如“雄鹰之”）的不同变体。"
dictionary["Price history|r"] = "价格历史|r"
dictionary["Price lookup"] = "价格查询"
dictionary["Price lookup: look any item up by name, even one you don't have, or Alt-click a listing at the auction house for that exact version."] = "价格查询：按名称查询任意物品，即使尚未拥有；也可 Alt 点击拍卖挂单，查看该具体变体。"
dictionary["Price source set to "] = "价格来源已设为"
dictionary["Price window"] = "价格窗口"
dictionary["Price window: Alt-click any item, or type /fl price, for its usual price, trend, the cheapest now and a price graph over 2 weeks, 3 months or a year."] = "价格窗口：Alt 点击物品或输入 /fl price，查看常见价格、趋势、当前最低价，以及两周、三个月或一年的价格图。"
dictionary["Prices"] = "价格"
dictionary["Prices and flips work from your first full scan. Deals and how fast things sell need a few days of scans to know what's usual."] = "价格和卖店套利在第一次全扫后即可使用。低价转售和销售速度需要数天扫描，才能判断常见水平。"
dictionary["Prices and their history, vendor and trainer locations you've seen, your characters' recipes, gold, sales and purchases, bags and bank, chat requests it spotted, and your work log."] = "价格及历史、已访问的商人和训练师位置、角色配方、金币、买卖、背包银行、识别出的聊天需求以及服务记录。"
dictionary["Prices and worth"] = "价格与价值"
dictionary["Prices as text"] = "价格文本"
dictionary["Prices checked"] = "价格检查时间"
dictionary["Prices from your scans"] = "价格来自你的扫描"
dictionary["Prices jump around a lot from day to day."] = "每日价格波动较大。"
dictionary["Prices move: Booty Bay's are only as fresh as your last visit there."] = "价格会变化：藏宝海湾价格以你上次到访扫描为准。"
dictionary["Profession"] = "专业"
dictionary["Professions"] = "专业"
dictionary["Professions this character doesn't have. A star: another of your characters on this realm and faction has it."] = "当前角色没有学习的专业。星号表示同服务器、同阵营的其他角色已学习。"
dictionary["Profile"] = "配置"
