dictionary["Sales and purchases one by one for 30 days, then as one line per item per month for a year. Gold and money in and out per day for a year, then per month. Prices per day for 14 days, then weekly averages for a year. Recipes, vendors, items and your characters are kept for good. Nothing is lost at a reload: only data past these ages is summed up or dropped."] = "逐笔买卖保存 30 天，之后按物品和月份汇总保存一年。金币及每日收支保存一年，之后按月汇总。价格按日保存 14 天，之后按周平均保存一年。配方、商人、物品和角色永久保存。重新加载不会丢失数据，只汇总或清理超过期限的数据。"
