dictionary["Select rows to see what they add up to: click one, Shift-click another for everything between, Ctrl-click to add or take one, or press and drag across rows. The bottom line shows the money in, out and net of the selection. Right-click a row or Clear selection to start again."] = "点击选一行，Shift 点击选中间所有行，Ctrl 点击增减选择，也可按住拖过多行。底部显示所选记录的收入、支出和净额。右键一行或点击清除选择可重选。"
