dictionary["Selling"] = "出售"
dictionary["Selling an item on the auction house (its Worth to you line), resale deals and the Booty Bay view allow for one 8-hour listing that doesn't sell (its deposit is lost). The deposit comes back when a listing sells. Materials further down a chain (dust from disenchanting, a craft's output) don't count it, so the Disenchant finder, shuffles, vendor flips and shopping-list limits are unchanged. If this makes selling to a vendor better, the option says Vendor it instead. Deposits use the auction house's quote when available, otherwise Classic's formula, which matches Forever: 5% of the vendor price per 2 hours (25% at Booty Bay), so 20% for 8 hours. Without a known vendor price, it's zero."] = "拍卖出售估值、转售机会和藏宝海湾比较会预留一次 8 小时未售出挂单的保证金损失，成交时保证金退还。后续加工链中的材料不扣此项，因此分解筛选、加工套利、卖店套利和购物清单上限不受影响。若扣除后卖商店更好，会建议卖店。保证金优先采用拍卖行报价，否则使用与无限服相符的经典公式：每两小时为商店收购价的 5%（藏宝海湾 25%），即八小时为 20%。商店收购价未知时按零计。"
dictionary["Selling at Booty Bay instead brings %s more each."] = "改在藏宝海湾出售，每件扣费后多赚 %s。"
dictionary["Selling to a vendor has no risk, only the effort of buying. 0 counts any listing below vendor price."] = "卖给商店只需完成购买操作，无需等待转售。设为 0 时，列出所有低于商店收购价的挂单。"
dictionary["Sells"] = "出售方式"
dictionary["Sells for more there"] = "当地卖价更高"
dictionary["Sells for, after cut"] = "扣费后卖价"
dictionary["Sells on the auction house"] = "拍卖行出售"
dictionary["Sells on the auction house (depends on buyers):"] = "在拍卖行出售（取决于买家）："
dictionary["Sells to a vendor"] = "卖给商店"
dictionary["Sells to a vendor (safe):"] = "卖给商店（收益确定）："
dictionary["Sends what your characters carry and keep in the bank to the character you linked (Settings, Characters), so it counts in Have, shopping lists and the Characters tab there. Only for your own second account: off by default. Unlinking removes what you got from them."] = "把角色背包和银行数据发给已配对角色，供其“已有数量”、购物清单和角色页使用。仅适用于自己的第二账号，默认关闭。解除配对会删除从对方收到的数据。"
dictionary["Sends your characters' gold, money in and out, Ledger entries and sessions to the character you linked (Settings, Characters), so both accounts' Dashboards and Ledgers show the same. These include your buyers' names, so leave it off if you linked a friend. Unlinking removes what you got from them."] = "把角色金币、收支、账本和会话记录发送给已配对角色，使两个账号显示相同总览和账本。其中包含买家名称；若配对的是朋友，请保持关闭。解除配对会删除从对方收到的数据。"
dictionary["Server type"] = "服务器类型"
dictionary["Services"] = "服务"
dictionary["Session"] = "统计时段"
dictionary["Session over after %s: gold %s, looted about %s, so about %s an hour."] = "统计结束，用时%s：金币%s，拾取估值约%s，每小时约%s。"
dictionary["Session started: gold in and out and what you loot are counted. /fl session stop (or Stop on the tracker) ends it."] = "统计已开始，将记录金币收支和拾取。输入 /fl session stop 或点击统计条的停止按钮可结束。"
dictionary["Session stopped. Nothing happened in it, so it isn't kept."] = "统计已停止。没有收支或拾取，因此未保存。"
