dictionary["Sessions and runs"] = "会话与副本"
dictionary["Sessions list"] = "会话列表"
dictionary["Set Want and Up to for each item, and the Buy queue buys them for you."] = "为每个物品设置所需数量和价格上限，购买队列将按此购买。"
dictionary["Set by you"] = "手动设置"
dictionary["Set by you. This price is never changed automatically."] = "由你设置，此价格不会自动修改。"
dictionary["Sets of settings your characters can share, switch between, export and import."] = "角色可以共用、切换、导出或导入的设置方案。"
dictionary["Settings"] = "设置"
dictionary["Settings and Help each have a search box above their list: type two letters or more to see everything that mentions it, from every section at once."] = "设置和帮助列表上方都有搜索框。输入至少两个字母，可同时查找所有分区中包含该词的内容。"
dictionary["Settings and look"] = "设置与外观"
dictionary["Settings that mention \"%s\", from every page."] = "所有页面中提到“%s”的设置。"
dictionary["Settings, Appearance: FL Clean (flat and quiet), FL Bronze (a bronze edge, gold titles, sections as cards, switches) or FL Gilded (a bronze frame, gold serif titles), and an accent color: Auto uses EllesmereUI's when it's installed, or pick one, or Custom. A new look shows after a reload; it offers one. Size makes the windows smaller or bigger, 75% to 150%: drag, then let go."] = "“设置→外观”提供简洁、青铜和鎏金三种主题。强调色可自动采用 EllesmereUI 颜色，也可手动选择或自定义。修改主题后会提示重新加载。窗口大小可在 75%～150% 间调整，拖动滑块后松开生效。"
dictionary["Settings, Characters lists every character Forever Ledger knows, when each was last seen and where it came from. Addons can't see a character being deleted, so remove old ones there: click Remove twice. It forgets the level, professions, recipes, bags and bank; prices and gold history stay. Not the one you're on."] = "在“设置→角色”中可查看各角色、上次出现时间和来源。插件无法得知角色是否已删除，因此需点击两次“移除”清理旧记录。清除等级、专业、配方、背包和银行，保留价格和金币历史。不能移除当前角色。"
dictionary["Settings, Profiles: a profile is a set of settings characters can share, say no tooltips on one character, no customer finder on another. Each character uses one (Default to start). New profile copies your settings now; Rename, Reset to defaults and Delete profile (click twice) work on the one this character uses. Export / import opens one window: Export copies a profile as text with the parts you tick; Import makes a new profile from someone's text. Global settings are never in a profile."] = "“设置→配置方案”可管理角色共用的设置组合。每个角色起初使用默认配置。新建会复制当前设置；重命名、恢复默认和删除（点击两次）影响当前配置。导出只包含勾选的部分，导入会新建配置。全局设置不包含在配置方案中。"
dictionary["Share"] = "分享"
dictionary["Share \""] = "分享“"
dictionary["Share / import"] = "分享/导入"
dictionary["Share / import (top right of the list) opens a window with two tabs. Share copies a list as plain text to paste in Discord or send a friend; Import reads it back (or a plain list of item names, item numbers or Wowhead links, one per line). Imports never change your own lists, and never buy by themselves: tick Buy from this list to buy from one."] = "清单右上方的分享/导入窗口有两个标签。分享将清单复制为文本，供粘贴到 Discord 或发给朋友；导入可读取此文本，也支持每行一个物品名称、ID 或 Wowhead 链接。导入不会覆盖原清单，也不会自行购买，须勾选按清单购买。"
dictionary["Share and import"] = "分享与导入"
dictionary["Share bags and bank with your sync partner"] = "向配对角色分享背包和银行"
dictionary["Share gold and sales with your sync partner"] = "向配对角色分享金币和交易记录"
dictionary["Share prices and recipes with a character on your other account while both are online. Type its first and last name, click Link, then do the same on that character for this one."] = "双方在线时，与另一个账号的角色分享价格和配方。填写角色全名并点击配对，再在对方角色上反向配对。"
dictionary["Shift-click for shopping lists."] = "按 Shift 点击查看购物清单。"
dictionary["Shift-click, drag or type an item"] = "按 Shift 点击、拖入或输入物品"
dictionary["Shopping list"] = "购物清单"
dictionary["Shopping list \"%s\": %d %s left to fill."] = "购物清单“%s”：还需填满%d个%s。"
