dictionary["Shopping list for a crate"] = "补给箱购物清单"
dictionary["Shopping lists"] = "购物清单"
dictionary["Shopping lists hold what you want to buy and the most you'd pay. Plan anywhere; they show beside the auction house when you get there."] = "购物清单保存想买的物品和最高买入价。可随时规划，抵达拍卖行后会在侧栏显示。"
dictionary["Shopping lists view"] = "购物清单视图"
