dictionary["Skill"] = "技能"
dictionary["Skin every beast you kill anyway on quests. One skin per corpse in Forever. Sell leather when it's worth more than a vendor pays."] = "给任务中顺手击杀的野兽剥皮。无限服每具尸体可剥取一份皮革。拍卖售价高于商店收购价时可考虑出售。"
dictionary["Skin the beasts you kill"] = "剥取击杀野兽的皮"
dictionary["Skinning"] = "剥皮"
dictionary["Skip"] = "跳过"
dictionary["Skip while leveling"] = "升级时可暂缓"
dictionary["Skip while leveling."] = "升级期间可暂缓。"
dictionary["Slow"] = "慢"
dictionary["Sold"] = "已卖出"
dictionary["Sold "] = "卖出"
dictionary["Sold by "] = "出售者："
dictionary["Sold since you were last here: %s. About %s with deposits back, in your mail or on the way (the Auctions tab, Sold)."] = "离开期间已售出：%s。含退回押金约 %s，已到邮箱或正在寄送，可在“我的拍卖→已售出”查看。"
dictionary["Sold to vendor"] = "卖给商店"
dictionary["Sold to vendors"] = "卖给商店"
dictionary["Some data, but not a lot, or a warning below."] = "已有部分数据，但数量有限，或存在下方提示的问题。"
dictionary["Someone else bought them first, or their price is too old: finds over 15 minutes old are left out until a scan finds them again. Items you can't afford stay at the bottom, marked."] = "可能已被他人买走，或报价太旧。超过 15 分钟的记录会暂时排除，直到再次扫描发现。买不起的物品仍留在队列底部并标注。"
dictionary["Sound"] = "声音"
dictionary["Sound when an auction sells"] = "拍卖售出时播放提示音"
dictionary["Spend at most"] = "本次花费上限"
dictionary["Spend at most, this visit"] = "本次访问预算上限"
dictionary["Spend talent points and this gets clearer."] = "分配天赋点后可提供更明确的建议。"
dictionary["Spent"] = "已花费"
dictionary["Spent %s of %s so far."] = "目前已花费 %s，总预算 %s。"
dictionary["Spent %s of %s. Raise Spend at most below to buy more, or it starts again next visit."] = "已花费 %s，总预算 %s。可提高下方预算上限继续购买，下次打开拍卖行会重置。"
dictionary["Spot people in chat asking for what this character can do (LF enchanter, WTB an item you craft, Mage water)."] = "识别聊天中需要当前角色服务的玩家，例如找附魔、求购你能制作的物品或法师食水。"
dictionary["Spotting people in chat who want what this character can do."] = "识别聊天中需要当前角色服务的玩家。"
dictionary["Stacks are bought in two steps: price, then confirm."] = "堆叠材料需要两步购买：获取报价，然后确认。"
dictionary["Start"] = "开始"
dictionary["Start a session"] = "开始统计"
dictionary["Start one (Start a session at the top of the Dashboard, Ctrl-click on the minimap button, or /fl session start) and a small tracker you can drag counts what your time is worth: gold an hour, gold in and out, and what you loot (at the better of auction and vendor price; Settings can make it vendor only). Right-click the tracker to fold it to one line. Stop it to get a summary in chat; it joins the Dashboard's sessions. A session carries on through a logout on the same character."] = "可在总览角色列表旁开始会话，或 Ctrl 点击小地图按钮、输入 /fl session start。可拖动的小窗口统计每小时金币、收支和拾取价值；默认取拍卖与商店较高者，可设为仅商店。右键可折叠为一行。结束时在聊天中汇总并加入总览记录。同一角色退出登录后会话仍会继续。"
dictionary["Starting zone, then Westfall and Loch Modan"] = "起始区域，之后前往西部荒野和洛克莫丹"
dictionary["Starting zone, then the Barrens and Silverpine"] = "起始区域，之后前往贫瘠之地和银松森林"
dictionary["Status"] = "状态"
dictionary["Stays on your PC"] = "保存在你的电脑"
dictionary["Steady"] = "稳定"
dictionary["Steady prices over a week or more."] = "一周以上的价格较稳定。"
dictionary["Steps"] = "步骤"
dictionary["Stop"] = "停止"
dictionary["Stop posts below vendor price"] = "阻止低于商店收购价上架"
dictionary["Stop scan"] = "停止扫描"
dictionary["Stop the session"] = "停止统计"
dictionary["Stop watch"] = "停止监控"
dictionary["Stop watching"] = "停止监控"
dictionary["Sure"] = "可信度"
dictionary["Sure?"] = "确认？"
dictionary["Sure? Click again"] = "确定？再次点击"
dictionary["Sync status."] = "同步状态。"
dictionary["Sync with your other account"] = "与另一个账号同步"
dictionary["TSM price"] = "TSM 价格"
dictionary["TSM's prices"] = "TSM 价格"
dictionary["TSM's prices, or this addon's scans where TSM has none"] = "优先使用 TSM 价格，缺失时使用本插件扫描数据"
dictionary["Tailor"] = "裁缝"
dictionary["Tailoring"] = "裁缝"
dictionary["Taken off every auction house sale in values and shuffles, at your faction's auction house. Neutral ones (Booty Bay, Gadgetzan, Everlook) take 15%, counted by themselves."] = "在本阵营拍卖行计算物品价值和加工套利时，扣除每次成交的手续费。中立拍卖行（藏宝海湾、加基森、永望镇）按 15% 单独计算。"
dictionary["Talents"] = "天赋"
dictionary["Technique"] = "工艺图"
dictionary["Tell me when a new version is out"] = "有新版本时提醒"
dictionary["Testing"] = "测试"
dictionary["That costs more than you can spend now: checking again."] = "价格超过当前可用金币，正在重新检查。"
dictionary["That isn't a Forever Ledger export."] = "这不是 Forever Ledger 导出的数据。"
dictionary["That isn't a settings profile. (Data from Export / import on the Characters tab goes in there.)"] = "这不是设置配置。（角色页“导出 / 导入”的数据应在对应页面导入。）"
dictionary["That list has no items yet."] = "该清单暂无物品。"
dictionary["That name is taken by the Default profile."] = "此名称已被默认配置占用。"
dictionary["That name is too long (30 letters at most)."] = "名称太长，最多 30 个字母。"
dictionary["That profile has no settings this version of Forever Ledger knows."] = "此配置不包含当前版本可识别的设置。"
dictionary["That purchase failed: the listings changed. Checking again."] = "购买失败：挂单已变化，正在重新检查。"
dictionary["That was a while ago: checking it's still there."] = "挂单已有一段时间，正在重新确认是否仍在售。"
dictionary["That's a settings profile: import it in Settings, Profiles."] = "这是配置方案，请在“设置 → 配置方案”中导入。"
dictionary["That's everything you can buy: the %d left %s more than %s or wait for a lower price."] = "已买完当前能购买的物品：剩余 %d 个 %s 超过 %s，或需等待降价。"
dictionary["The %s profile is back to Forever Ledger's defaults. Global settings weren't touched."] = "配置 %s 已恢复为 Forever Ledger 默认值。全局设置未改动。"
dictionary["The Auctions tab beside the auction house: All, Up, Undercut and Sold, like the Ledger. Each auction shows how many, your price each, the cheapest now, and undercut (red) or cheapest (green); sold ones show what you get after the cut and when the gold reaches your mailbox. The bottom line says what gold is on the way and what's waiting in your mailbox. Check prices looks them all up; scans and the flip watch check them too, and an undercut gets a chat line and a sound (Settings, Auction house). Cancel next undercut asks once, then each click cancels the next one (each loses its deposit). Opening the auction house says in chat what sold while you were away and the gold it brings (Settings, Auction house)."] = "拍卖行旁的“我的拍卖”提供全部、在售、被压价和已售出视图。显示数量、你的单价、当前最低价及红色压价或绿色最低价标记。已售出项显示税后收入和邮件到账时间，底部汇总在途及待领取金币。可一次检查全部价格，扫描和监测也会检查并提醒被压价。取消下一件被压价拍卖需逐次点击，取消会损失保证金。打开拍卖行时还可汇总离线期间售出收入。"
dictionary["The Buy queue never takes your gold below this, so there's always enough for repairs, training or a mount. Type 100 for 100g. \"off\": it may spend all of it. (The most to spend each visit is on the Buy queue itself.)"] = "购买队列不会使金币低于此金额，以保留修理、训练或坐骑资金。输入 100 表示 100 金；“off”表示允许花完。每次访问的支出上限在购买队列中设置。"
dictionary["The Crates tab and the \"cheapest fill\" tooltip line."] = "补给箱页面和物品提示中的最低交付成本。"
dictionary["The Crates tab and the cheapest way to fill each crate."] = "补给箱页面及每个箱子的最低补满成本。"
dictionary["The Customers window. /fl customers on or off turns the customer finder on or off."] = "客户窗口。使用 /fl customers on 或 off 开关需求识别。"
dictionary["The Deals tab (/fl deals list in chat)."] = "低价机会页（/fl deals list 在聊天中列出）。"
dictionary["The Deals tab lists items selling well below their usual price, to buy and resell."] = "低价机会页列出明显低于常见价格、适合买入转售的物品。"
dictionary["The Default profile keeps its name. Make a new profile to name your own."] = "默认配置不能改名。请新建配置后自行命名。"
dictionary["The Forever Ledger button on the minimap. /fl opens the window either way."] = "在小地图显示 Forever Ledger 按钮。无论是否显示，都可使用 /fl 打开。"
dictionary["The Help tab explains every feature, and can show this again."] = "帮助页介绍所有功能，也可以再次显示本引导。"
dictionary["The Help tab explains every feature. /fl new shows this again."] = "帮助页介绍所有功能，/fl new 可再次显示本页。"
dictionary["The Leveling tab (ways to make gold while leveling, under level 20), training advice at the class trainer and the riding fund on the Dashboard. Off: none of it runs, and the spells you cast aren't counted. It switches itself off on level 60 characters."] = "包含 20 级以下的升级赚钱建议、职业训练建议和总览中的骑术储蓄目标。关闭后这些功能均停止运行，也不再统计施放的法术。角色达到 60 级时自动关闭。"
dictionary["The Silence button (bottom right of the Customers window) quiets the alerts: until you're next in a capital city, until you reload, until you log out, or always (that turns the finder off; Turn alerts back on, or /fl customers on, brings it back). While quiet, requests are still listed in the window, with no pop-up, sound or chat line."] = "客户窗口右下方可选择暂停至下次进入主城、重新加载、退出登录，或永久关闭。暂停期间仍记录需求，但不弹窗、不播放声音、不发聊天提示。可用“恢复提醒”或 /fl customers on 恢复。"
dictionary["The auction house"] = "拍卖行"
dictionary["The auction house can't tell what actually sold. Buy what you'd be happy to hold for a while."] = "拍卖行无法确认某件挂单是否真正成交。请只购买你愿意持有一段时间的物品。"
dictionary["The auction house hasn't sent the full scan yet. It can take minutes when it's busy: keep it open and it's read when it arrives. It allows one about every 15 minutes."] = "拍卖行尚未返回全扫数据，繁忙时可能需要数分钟。请保持窗口打开，返回后会自动读取。约每15分钟允许全扫一次。"
dictionary["The auction house hasn't sent the full scan yet. Scanning your materials instead; keep the auction house open and it's read if it arrives."] = "拍卖行尚未返回全扫数据，现改为扫描材料。请保持窗口打开，数据返回后会自动读取。"
dictionary["The auction house is catching up: try again in a moment."] = "拍卖行正在处理请求，请稍后重试。"
dictionary["The auction house refused that purchase."] = "拍卖行拒绝了此次购买。"
dictionary["The auction house shows what's listed, not what sold. \"Sells\" counts listings that vanished before they could have expired (bought, or cancelled): a low estimate that gets better the more full scans you run, fastest with Watch flips."] = "拍卖行提供上架数据，不提供真实成交清单。“售出”统计到期前消失的挂单，可能是被买走或撤单。它只是粗略估计，全扫次数越多越有参考价值，开启套利观察可加快数据积累。"
dictionary["The best of selling on the auction house, selling to a vendor, disenchanting, or crafting it into something, with the best few ways listed. Disenchanting counts what the materials sell for, as an average: each disenchant gives one result, and the tooltip shows the chance of each. Settings, Tooltips chooses which ways it counts (turn off crafting to leave out what your alts could make); shuffles and the Buy queue still count every way."] = "比较拍卖出售、卖商店、分解、加工等用途，列出最优及次优方式。分解按材料转售的平均收入估值，并显示各种产出的概率。设置中的物品提示可选择计入哪些用途；加工套利和购买队列始终考虑全部用途。"
dictionary["The best way to use the item (auction house, vendor, disenchanting or crafting it into something) and the next best few."] = "列出物品价值最高的用途（拍卖、卖商店、分解或加工）以及次优用途。"
dictionary["The box near the bottom of the Buy queue caps what it spends this auction house visit (type 50 for 50g; it starts again each time you open the auction house). No limit until you type one; what's left shows beside it. Items over it are marked over limit and skipped. To always keep some gold back for repairs or a mount: Settings, Auction house, Buy queue: always keep."] = "购买队列底部可设置本次访问拍卖行的支出上限，例如输入 50 表示 50 金。每次重新打开拍卖行时重新计数；未设置则不限。旁边显示剩余额度，超出额度的项目会标注并跳过。若希望始终保留修理或坐骑资金，可在“设置→拍卖行→购买队列：始终保留金币”中设置。"
dictionary["The cheapest on the auction house (how many listed, how long ago), the average of the cheapest 20, and what a vendor sells it for."] = "显示最低拍卖价、挂单量、价格时间、最便宜 20 件的均价，以及商店售价。"
dictionary["The cheapest way to fill each crate at today's prices, with the crate's own price and gold per Merchant's Favor. After your first turn-in (a one-time quest), every crate pays 5s and 10 Favor; Net cost takes the 5s off, and shows green if a crate somehow pays for itself. Click a crate for every bundle and what you already have."] = "按当前价格列出各补给箱的最低补满成本、箱子价格及每点商人恩惠的成本。首次一次性任务交付后，每箱奖励 5 银和 10 点恩惠；净成本扣除 5 银。点击查看各组交付材料和已有数量。"
dictionary["The color of what's active: the chosen tab, switches that are on, highlights. Auto uses EllesmereUI's color when it's installed."] = "用于选中的标签、开启的开关和高亮。选择“自动”时，若已安装 EllesmereUI，则使用其颜色。"
dictionary["The final price would go over your limit: checking again."] = "最终报价超过预算，正在重新检查。"
dictionary["The finder also spots requests for Mage food, water and portals (portals from level 40), Warlock summons (from 20) and Rogue lockpicking (from 16), on those classes. Settings, Customers turns each one (and crafting) on or off."] = "对应职业还会识别法师食水及 40 级以上传送门、20 级以上术士召唤、16 级以上盗贼开锁需求。可在设置中分别开关这些服务和制作需求。"
dictionary["The first rank does the job. Later ranks mostly last longer or reach further: buy them with gold to spare."] = "初始等级足以发挥主要作用。后续等级通常只是延长持续时间或扩大范围，金币充裕时再学。"
dictionary["The first time you open the window, a short welcome lists the five things to start with. Show it again with the button under the list of topics, or /fl welcome."] = "首次打开窗口时显示五项简短入门引导。可用帮助主题列表下方的按钮或 /fl welcome 再次打开。"
dictionary["The game allows one about every 15 minutes. The Full scan button counts down to the next."] = "游戏约每 15 分钟允许全扫一次。全扫按钮会显示下一次可用倒计时。"
dictionary["The game blocked %s for addons. Buy from the auction house page instead, and tell us on Discord."] = "游戏禁止插件调用 %s。请在拍卖行原生页面购买，并在 Discord 反馈此问题。"
dictionary["The game blocked buying from the addon."] = "游戏阻止了插件购买。"
dictionary["The game didn't accept a map pin there."] = "游戏无法在该位置设置地图标记。"
dictionary["The highlights of this version. Every change is in the changelog on CurseForge and Wago."] = "本版本重点变化。全部记录见 CurseForge 和 Wago 更新日志。"
dictionary["The items come back by mail. Each loses its deposit."] = "物品退回邮箱，每项损失押金。"
dictionary["The line above says which one is next."] = "上方文字会显示下一项。"
dictionary["The list shows what's on the auction house; Search all checks it all at once. You buy by hand."] = "清单显示拍卖行现有挂单；“搜索全部”会一次查询整张清单，购买仍由你手动进行。"
dictionary["The minimap button and new version notices."] = "小地图按钮和新版本提示。"
dictionary["The most the Buy queue spends while the auction house is open. It starts again each time you open it. Leave it at no limit to spend freely. Type 50 for 50g, or 2g 50s."] = "限制拍卖行打开期间购买队列的总花费，每次重新打开拍卖行都会重置。“不限”表示不设预算。输入 50 表示 50 金，也可输入 2g 50s。"
dictionary["The most worth paying for it, after your safety margin. Green when it's already cheaper."] = "扣除安全余量后值得支付的最高价格。当前价格已更低时显示绿色。"
dictionary["The most worth paying, after your safety margin. Green when it's already cheaper."] = "扣除安全余量后值得支付的最高价格，当前价格已更低时显示绿色。"
dictionary["The next cloth reaches buyers before most players get there."] = "较早获取下阶段的布料，可满足进度较快玩家的需求。"
dictionary["The panel's bottom row has Watch flips, Full scan and Scan materials (Stop watching and Stop scan while they run), with the scan's progress just above. While the panel is open beside the auction house, the same buttons under the auction house window are hidden. With nothing to buy, the big button starts the flip watch."] = "队列底部提供监测套利、全扫和扫描材料按钮；运行时改为停止监测或停止扫描，进度显示在上方。侧栏打开时会隐藏拍卖行下方的同类按钮。没有可买物品时，大按钮可启动套利监测。"
dictionary["The price went up before buying: checking again."] = "购买前价格上涨，正在重新检查。"
dictionary["The sale after the cut (plus the deposit, if it was posted before this was counted)."] = "扣除手续费后的收入；若上架时尚未记录押金，另计退回押金。"
dictionary["The sale after the cut, plus your %s deposit back."] = "扣除手续费后的收入，加退回押金 %s。"
dictionary["The same for every character and profile: they decide what items are worth and what counts as a flip or a deal."] = "所有角色和配置共用，决定物品估值及套利机会的判断方式。"
dictionary["The whisper sound with each new request."] = "发现新需求时播放密语提示音。"
dictionary["Theme"] = "主题"
dictionary["Theme and color"] = "主题与颜色"
dictionary["Themes"] = "主题"
dictionary["Then:"] = "然后："
dictionary["There's already a profile called %s."] = "已存在名为 %s 的配置。"
dictionary["Things listed for less than a vendor pays, found by scans. Buy them, sell them to a vendor."] = "扫描发现的一口价低于商店收购价的物品。买下后卖给商店即可获利。"
dictionary["Things on the auction house for less than a vendor pays. They're in the Buy queue beside the auction house (its Vendor flips view); a full scan that finds some opens it if it's closed, and the flip watch chimes. Settings, Global settings, Flips and deals sets the least profit worth your time, as a share of the vendor price and as an amount."] = "拍卖价低于商店收购价的物品，会出现在拍卖行旁购买队列的卖店套利视图。全扫发现机会时会打开尚未显示的队列，监测发现机会时播放提示音。可在“设置→全局设置→套利与低价机会”中设置最低利润金额及比例。"
dictionary["This character"] = "当前角色"
dictionary["This client has no auction house scanning."] = "当前客户端不支持拍卖行扫描。"
dictionary["This list wants only the \"%s\" version; Listed and Cheapest count just that one."] = "此清单只需要“%s”版本；在售数量和最低价仅统计该版本。"
dictionary["Those listings were just bought: checking again."] = "这些挂单刚被买走，正在重新检查。"
dictionary["Tick \"Use my types\" first to set your own types."] = "先勾选“使用自定义类型”，再设置配方类型。"
dictionary["Tick Buy from this list in the Buy queue: the list adds Want (how many to buy) and Up to (the most you'll pay for one: filled in from its source; hover to see where it came from; off means don't buy it), and the Buy queue's Shopping lists view buys them. Want is how many to buy, whatever you already have; Have shows how many are bought so far. It never buys more than Want. Type any in Want to keep buying it whenever it's at or under Up to, with no limit (not with Up to any, which would buy every listing: then it buys one). An item is done once its Want is bought, and stays done; Buy again (bottom right) starts the list over. The bottom line says about what buying the rest would cost."] = "勾选“在购买队列中按此清单购买”后，会显示目标数量和每件最高买入价，并由队列的购物清单视图执行。目标数量指还要购买多少，不扣除已经拥有的物品；已有数量会显示已为清单买入多少。不会超买。目标填 any 可在价格不超过上限时持续购买；但若价格也为 any，则只购买一件，避免买下全部挂单。完成目标后保持已完成状态，点击再次购买可重置。底部估算剩余采购成本。"
dictionary["Tick at least one part under Share in Settings, Profiles, to export it."] = "请先在“设置→配置方案→分享”中至少勾选一项。"
dictionary["Tick what to buy above."] = "在上方勾选要购买的分类。"
