dictionary["Type \"Soldier's Armor of the Monkey\", or shift-click a link of that version, to keep just that version on a list. Search all looks up every version of gear; hover an item for each version's price, yours first."] = "输入指定随机属性的装备名称（如“灵猴之士兵护甲”），或 Shift 点击对应链接，可只保留该变体。搜索全部会查询所有装备变体，悬停可看各变体价格，优先显示你的变体。"
dictionary["Type /bug on the Discord and fill in the short form. Include /fl api output or the BugSack error if you can."] = "在 Discord 使用 /bug 并填写简短表单。尽可能附上 /fl api 输出或 BugSack 错误。"
dictionary["Type /feature on the Discord. You'll get updates in your post."] = "在 Discord 使用 /feature，后续更新会回复到你的帖子。"
dictionary["Type /fl, or click the minimap button."] = "输入 /fl，或点击小地图按钮。"
dictionary["Type a name in the box first."] = "请先在输入框中填写名称。"
dictionary["Type a price any way: 2g 50s 25c, 2 50 25 or 2.50.25 (gold silver copper), 2 50 (gold silver), 25s, 75c, or a plain number for gold; it's tidied up when you press Enter, and a tip shows what it will be. Type any for any price, or tick Any price (bottom of the list) for the whole list (raid prep): the queue then buys the cheapest until it has bought what you want, never more than 3 times the usual price."] = "价格可输入 2g 50s 25c、2 50 25、2.50.25（金银铜）、2 50（金银）、25s、75c，纯数字按金币计算。Enter 后整理格式，提示会显示解析结果。输入 any 或勾选底部任意价格，可购买满足目标数量的最便宜物品，但不超过常见价格的三倍。"
dictionary["Type a price to set your own."] = "输入价格可自行设定。"
dictionary["Type an item's name in the box at the top right (two letters or more), or "] = "在右上方输入至少两个字符的物品名称，或"
dictionary["Type two letters or more of any item's name and pick it, or press Enter for the top one. You don't need to have it. A shift-clicked link or an item dragged here works too."] = "输入物品名称的至少两个字符，再选择结果，或按回车选择第一项。无需持有此物品，也支持按 Shift 点击链接或拖入物品。"
dictionary["Types"] = "类型"
