dictionary["Under the Create Auction button: the usual price and the cheapest now, and buttons to fill in 1 copper under the cheapest or the usual price. Says when the cheapest is well below usual."] = "在创建拍卖按钮下方显示常见价格与当前最低价，并可填入低于最低价 1 铜或常见价格。当前最低价明显低于常见价格时会提示。"
dictionary["Undercut"] = "被压价"
