dictionary["Undercut: %s x%d, yours %s each, cheapest now %s. The Auctions tab beside the auction house lists them."] = "被压价：%s，数量 %d。你的单价 %s，当前最低价 %s。可在拍卖行旁的“我的拍卖”中查看。"
dictionary["Unknown item"] = "未知物品"
dictionary["Unlimited-stock vendor items on shopping lists normally stay out of the auction house queue. On: buy them there at no more than the vendor price. Limited-stock items stay ordinary auction house items."] = "购物清单中的商店无限库存物品通常不进入拍卖购买队列。开启后，允许按不高于商店售价的价格购买。限量库存物品仍按普通拍卖物品处理。"
dictionary["Unlimited-stock vendor items show Vendor: price on lists and stay out of the auction house queue, including hand-added items. Settings > Auction house > Buying: Buy vendor items on the auction house too (off by default) permits buying at the vendor price; a lower price or off that you typed is still respected. Your stored price is kept. Right-click an item's Up to box to use its automatic price again; the hover shows the underlying shuffle cap or usual price plus the list allowance while a typed price is in force. Limited-stock vendor items remain ordinary auction house items."] = "商店无限库存物品在清单中显示商店售价，通常不进入拍卖购买队列，包括手动添加的项目。在“设置→拍卖行→购买”中可允许按不高于商店售价购买；你手动设置的更低价或 off 仍优先。手动价格会保留，右键最高价输入框可恢复自动定价；悬停显示加工上限或常见价加溢价。限量库存物品仍按普通拍卖物品处理。"
dictionary["Unlink"] = "解除配对"
