dictionary["Vendor flips or Shopping lists, switched at the top of the panel, one at a time; the one you're on is the one that buys, so a list never buys a flip by accident. Each has its own buttons at the bottom. When there is something to buy, the strip at the top glows (gold for Vendor flips, purple for Shopping lists); with Scroll to buy ticked it also shows a mouse wheel: that's where to scroll. Scans and the flip watch add to the lists but never switch the view; new flips found while you're on Shopping lists show a gold count on the Vendor flips button (and on the Buy queue tab)."] = "顶部在卖店套利和购物清单两种视图间切换，当前视图决定购买内容，避免误买另一类。各视图有自己的底部按钮。可购买时顶部条发光：套利为金色，清单为紫色；启用滚轮购买后显示滚轮图标。扫描只补充列表，不切换视图。浏览清单时发现新套利，会在套利按钮和购买队列标签上显示金色数量。"
