dictionary["Waiting to hear whether the last purchase went through."] = "正在确认上一笔购买是否成功。"
dictionary["Waiting: none listed at or under your price at the last search. Raise Up to on the list, or click Search all on the list again later."] = "等待中：上次搜索没有价格不超过上限的挂单。可提高清单中的价格上限，或稍后再次点击“搜索全部”。"
