dictionary["What a green disenchants into, on average."] = "绿装平均能分解出哪些材料。"
dictionary["What a session counts each looted item as worth. Auction house prices are after the cut; items that bind when picked up always count at vendor price. Start a session with /fl session start or on the Dashboard."] = "统计拾取物品时使用的估值方式。拍卖价格会扣除手续费；拾取绑定物品始终按商店收购价。可在总览或使用 /fl session start 开始会话。"
dictionary["What a vendor pays, minus what it costs."] = "商店收购价减去买入成本。"
dictionary["What are the 120 items the watch re-checks?"] = "持续监测复查的 120 种物品是什么？"
dictionary["What everyone has, added up; hover an item for who has it."] = "汇总所有角色的物品；将鼠标移到物品上可查看持有角色。"
