dictionary["What it's worth"] = "物品估值"
dictionary["What one is worth to you: the best of selling it on the auction house (after the cut), to a vendor, disenchanting it or crafting it into something."] = "单件物品的最高预计价值：比较拍卖出售（扣除手续费）、卖给商店、分解或加工制造的收益。"
dictionary["What sold while you were away"] = "离线期间售出汇总"
