dictionary["What to do"] = "操作方法"
dictionary["What to look for"] = "识别哪些需求"
dictionary["What you buy or craft first. Click a row for what to buy and every step."] = "首先购买或制作的物品。点击可查看购买清单和全部步骤。"
dictionary["What you own counts this character's bags, bank and purchases still in the mail, and your characters on this ruleset and faction. Hover a number to see where."] = "持有数量包括本角色背包、银行、仍在邮箱的购买物品，以及同规则、同阵营其他角色的物品。悬停数字可查看存放位置。"
dictionary["What you own of each item: this character's bags, bank and auction house purchases still in the mail, and your characters on this ruleset and faction. On a list you buy from it reads 3 (20): 3 bought for the list, 20 owned. Hover the number to see where. It's there to know, it doesn't change what's bought."] = "显示该角色背包、银行、拍卖购入但仍在邮件中的物品，以及相同模式和阵营其他角色的已有数量。启用购买的清单会显示如 3 (20)，表示为清单买入 3 个，总共拥有 20 个。悬停可看位置。该数字只供参考，不影响实际购买数量。"
dictionary["What you've seen in game first, otherwise original Classic data marked (Classic), or the auction house when its recipe item is listed there. Pin puts a map pin on the vendor, trainer or mob."] = "优先使用你在游戏中实际记录的来源，否则使用标注为“经典旧世”的数据；配方物品当前上架时，也显示拍卖来源。“标记”会在商人、训练师或怪物位置放置地图标记。"
dictionary["What's new"] = "更新内容"
dictionary["What's new in "] = "版本更新："
dictionary["What's new in %s:"] = "%s 更新内容："
dictionary["When"] = "时间"
dictionary["When a full scan finds vendor flips and the Buy queue beside the auction house is closed, open it. The flip watch's quick checks only chime."] = "全扫发现卖店套利机会且购买队列尚未打开时，自动打开队列。持续监测中的快速检查只播放提示音。"
dictionary["When a guildmate or group member has a newer Forever Ledger, chat says so once a session, with where to update. Only the version number is shared (Settings, Minimap and updates)."] = "公会或队伍成员使用较新版本时，每次会话在聊天中提示一次更新位置。仅分享版本号；可在“小地图与更新”中设置。"
dictionary["When a scan finds one of your auctions undercut: a line in chat, once per price. The Auctions tab beside the auction house lists them all."] = "扫描发现你的拍卖被压价时在聊天中提示；每个价格仅提示一次。拍卖行旁的“我的拍卖”页列出全部记录。"
dictionary["When most of what's listed is that cheap, the price has dropped and it's no bargain: rated Thin. Deals need at least 4 days of scans (or TSM). Thin data (few days, jumpy prices, usually only one listed) is hidden unless you tick Show thin data too."] = "若多数挂单都如此便宜，可能是整体跌价，会标为“数据不足”。低价机会需要至少四天扫描数据或 TSM 数据。样本少、价格跳动大或通常只有一件挂单时，默认隐藏，可勾选显示不足数据。"
dictionary["When to upgrade"] = "何时升级"
dictionary["When you open your class trainer, a panel beside it sorts what you can learn now into Must have, Nice to have and Skip while leveling, with what each costs and why (hover). It follows the tree your talent points are in and the spells you actually cast. Advice only: you still train in Blizzard's window."] = "打开职业训练师时，侧栏将当前可学技能分为“必学”“可选”“升级期间可缓”，并列出费用和理由（悬停查看）。建议参考天赋投入和实际施放的法术。仅提供建议，仍需在游戏原有窗口中学习。"
dictionary["When you're strong enough for the camp, farm Wool Cloth; sell it apart from Linen."] = "能够应对营地敌人后可收集毛料，与亚麻布分开出售。"
dictionary["Where"] = "来源"
dictionary["Where Up to comes from"] = "买入上限的来源"
dictionary["Where from"] = "获取来源"
dictionary["Where from (hover for all)"] = "获取途径（悬停查看全部）"
dictionary["Which of your characters' recipes use it, and how many."] = "哪些角色的配方使用该物品，以及所需数量。"
dictionary["While the flip watch runs: the game's music, effects, ambience and voices go off, and Forever Ledger's chimes play at full volume, even with the game in the background, plus a chime when you win an auction. Your sound settings come back when the watch stops. /fl quiet turns it on for one character until you type it again."] = "监测期间关闭游戏音乐、音效、环境音和语音，Forever Ledger 提示音以全音量播放，游戏在后台时也生效；买到拍卖物品时也会提示。停止监测后恢复声音设置。/fl quiet 可为当前角色切换安静模式。"
dictionary["Whole %s realm, both factions"] = "%s服务器的双方阵营"
dictionary["Whose characters to show and add up. Only characters on the same realm and faction share an auction house and can mail each other."] = "选择要显示并汇总的角色。只有同服务器、同阵营的角色共享拍卖行并可以互寄邮件。"
dictionary["Why are some things empty on the first day?"] = "为什么第一天有些页面为空？"
dictionary["Why are there no deals?"] = "为什么没有低价机会？"
dictionary["Why can't I run a full scan?"] = "为什么不能全扫？"
dictionary["Why did items disappear from the queue?"] = "为什么物品从队列消失？"
dictionary["Why does it say none listed?"] = "为什么显示没有挂单？"
dictionary["Why it pays"] = "收益来源"
dictionary["Why it's a deal"] = "判断依据"
dictionary["With the mouse over the top strip (it glows when there's something to buy), each tick of the wheel down buys the next item; stacks of materials take a second tick to confirm. It keeps working while the list is empty, so new flips can be bought the moment they show up. Off: only clicking Buy buys."] = "将鼠标移到上方栏位，有可购项目时该栏会发光。每向下滚动一格购买下一项；堆叠材料需要再滚动一次确认报价。列表为空时仍可保持开启，新套利机会出现后即可购买。关闭后仅点击“购买”才能成交。"
