language.strings["%d trainers seen, %d from city guards, %d more from Classic (unconfirmed). Ask a guard for a profession trainer to add Forever's real spot."] = "已发现 %d 位训练师，卫兵提供 %d 位，另有经典旧世数据 %d 位（未确认）。询问卫兵专业训练师的位置，可记录时光服的实际位置。"
