language.strings["%d. %s"] = "%d. %s"
language.strings["%d. Disenchant. On average each one gives:"] = "%d. 分解。平均每件获得："
language.strings["%d. Sell to a vendor"] = "%d. 卖给商店"
language.strings["%g%% or more below the usual cheapest price over %s (from %s)%s, or %s"] = "低于常见最低价至少 %g%%，统计范围%s（来源%s）%s，或%s"
