language.strings["%s (%s)"] = "%s（%s）"
language.strings["%s (can't be bought)"] = "%s（无法购买）"
language.strings["%s (species %s), tradeable %s, source: %s"] = "%s（种类 %s），可交易 %s，来源：%s"
