language.strings["%s and one unsold listing"] = "%s，并计入一次未售出挂单的保管费"
language.strings["%s each"] = "每件%s"
language.strings["%s listed"] = "在售 %s"
language.strings["%s%d selected:|r in %s, out %s, net %s"] = "%s已选 %d 项：|r收入 %s，支出 %s，净额 %s"
