language.strings["%s, level %d"] = "%s，等级 %d"
language.strings["%s, month total"] = "%s，当月合计"
language.strings["%s. From shuffle: %s. Uses the route's buying cap; the lower cap when two shuffles use this item. Refreshed when added again or on Buy again."] = "%s。加工套利来源：%s。价格上限取自该方案；两个方案共用此物品时取较低上限。重新添加或点击“再次购买”时刷新。"
language.strings["%s: %d recipes, %d known. Showing %d%s. (Classic) = original Classic data, unconfirmed in Forever until you see it."] = "%s：%d 个配方，已学 %d 个。显示 %d%s。“经典旧世”表示原版数据，在时光服实际见到前尚未确认。"
language.strings["%s: %s"] = "%s：%s"
language.strings["%s: %s each (%s; main input %s)"] = "%s：每件%s（%s；主要投入物品%s）"
language.strings["%sProfit %s %s (%d%%)%s."] = "%s利润%s（%s，利润率%d%%）%s。"
language.strings[", %d seconds after asking"] = "，请求后 %d 秒"
language.strings[", not asked for by this request"] = "，并非此次请求发起"
language.strings[", paid "] = "，收到 "
language.strings[", sell on the auction house"] = "，在拍卖行出售"
language.strings[", sell to vendor"] = "，卖给商店"
language.strings["- Post is"] = "— 上架按钮"
language.strings["- searching the item itself."] = "— 改为搜索物品本身。"
language.strings["/fl deals opens the Deals tab, /fl deals list lists them in chat. Deal settings: /fl deals usual 20 (percent below usual price), /fl deals period week/month/3months/6months/year/all, /fl deals history auto/local/tsm (where usual prices come from), /fl deals vendor 10% (percent below vendor price), /fl deals vendor 1s (least profit each), /fl deals sound."] = "/fl deals 打开市场机会；/fl deals list 在聊天中列出。设置：/fl deals usual 20（低于常见价的百分比）；/fl deals period week/month/3months/6months/year/all（统计时间）；/fl deals history auto/local/tsm（常见价来源）；/fl deals vendor 10%（低于商店收购价的百分比）；/fl deals vendor 1s（每件最低利润）；/fl deals sound（提醒声音）。"
language.strings["1 more step"] = "另外 1 步"
language.strings["< 1 min"] = "不足 1 分钟"
language.strings["A 1.5 second Frost cast that slows by 40% and uses your Frostbolt talents: a Frost staple, a kiting tool for the others."] = "1.5秒施法的冰霜法术，减速40%，并享受寒冰箭天赋；冰霜常用，其他天赋也可用于风筝。"
language.strings["A Destruction filler candidate; confirm it replaces another attack before maintaining both."] = "毁灭填充技能候选项；确认它是否取代另一攻击，避免同时升级两种不用的技能。"
language.strings["A Discipline option once unlocked; confirm Forever acquisition before advising paid upgrades."] = "戒律解锁后的可选技能；建议付费升级前，先确认时光服的获取方式。"
language.strings["A Feral damage cooldown candidate; prioritise only after its unlock and actual use are confirmed."] = "可能适合野性的爆发技能；先核实解锁方式和实际用途。"
language.strings["A Holy healing candidate; confirm its unlock and value in the actual healing route before buying upgrades."] = "可作为神圣治疗技能；升级前先确认解锁条件，以及当前治疗是否用得上。"
language.strings["A Marksmanship damage candidate; confirm unlock and whether the ranged rotation actually uses it."] = "可能适合射击输出；先确认解锁方式，以及远程攻击循环是否用得上。"
language.strings["A Restoration healing candidate; maintain it when unlocked and regularly used for healing."] = "恢复治疗候选技能；解锁且经常用于治疗时应及时升级。"
language.strings["A Retribution seal choice; only upgrade if unlocked and used rather than another seal."] = "惩戒可选的圣印；仅在已解锁并实际使用时升级。"
language.strings["A Subtlety combo builder when unlocked; defer Sinister Strike upgrades if this replaces it."] = "敏锐解锁后的连击点生成技能；若用它替代影袭，可暂缓升级影袭。"
language.strings["A bear-form stun buys time to heal or escape; damage upgrades are secondary."] = "熊形态昏迷可争取治疗或逃脱时间，伤害等级次要。"
language.strings["A buying limit is missing for %s. Refresh shuffles, then try again."] = "%s缺少买入上限。请刷新加工套利后重试。"
language.strings["A caster filler or proc attack; wand or drain routes need fewer upgrades."] = "法系填充或触发攻击；魔杖或吸取路线需要的升级较少。"
language.strings["A caster leveling opener for Holy or Discipline; later Shadow can defer it."] = "神圣或戒律任务升级的起手法术；后期暗影可暂缓升级。"
language.strings["A central Balance form once unlocked; other builds do not need its acquisition."] = "解锁后是平衡的核心形态，其他天赋无需专门获取。"
language.strings["A cheap safety and travel option; useful but not part of your damage rotation."] = "低耗的生存与赶路选择，实用但不属于伤害循环。"
language.strings["A common Affliction drain-tanking damage pet; alternative pet choices remain valid."] = "痛苦吸血坦怪常用的输出宠物；其他宠物选择同样可行。"
language.strings["A coordinated wipe tool can wait until organised group content."] = "需要团队配合的灭团应对技能，可等到参与固定团队活动时再学习。"
language.strings["A core Enhancement melee attack when unlocked; maintain damage ranks that the trainer actually offers."] = "增强解锁后的核心近战攻击；及时学习训练师实际提供的伤害等级。"
language.strings["A core tank attack after blocks or avoids; damage builds upgrade when tanking."] = "格挡或躲避后的核心坦克攻击；输出天赋承担坦克时再升级。"
language.strings["A dagger or talent builder can replace this later; do not require unused ranks."] = "后期可用匕首或天赋技能替代；无需购买不使用的等级。"
language.strings["A defensive or resource tool helps every route."] = "防御或资源恢复技能适用于各种路线。"
language.strings["A disenchant buying limit is missing for %s. Check Enchanting and material prices, then refresh the finder."] = "%s缺少分解买入上限。请检查附魔技能与材料价格，再刷新搜索器。"
language.strings["A fear escape can save a bad pull; fleeing targets may bring friends."] = "恐惧可用于脱离危险战斗；逃跑的敌人也可能引来更多敌人。"
language.strings["A free boosted cast supports Discipline; other builds only get it if they choose the talent."] = "免费强化一次施法，有助于戒律天赋；其他路线仅在选择对应天赋时获取。"
language.strings["A key pet burst tool once Beast Mastery unlocks it."] = "野兽控制天赋解锁后的重要宠物爆发技能。"
language.strings["A long-delay high-level attack is not needed on ordinary leveling pulls."] = "高等级、长延迟攻击，普通升级战斗并不需要。"
language.strings["A low-cost way past humanoids; useful on suitable routes rather than a mandatory combat spell."] = "低成本绕过人形敌人的手段；适合特定路线，并非必学战斗技能。"
language.strings["A main Shadow channel when unlocked and effective; early wand damage can still win."] = "解锁且收益合适时作为暗影主要引导技能；早期魔杖输出仍可能更高。"
language.strings["A proposed Feral attack needs a client check; use it only if it belongs in the actual cat rotation."] = "可能适合野性输出，需在客户端确认；猫形态攻击循环用得上时再考虑。"
language.strings["A racial rescue for an ally; useful in groups but cannot heal the caster."] = "用于救助队友的种族技能；组队有用，但无法治疗施法者自身。"
language.strings["A reliable emergency heal; upgrade when the old stone is too small for your health pool."] = "可靠的紧急治疗；旧石头的治疗量不足以匹配当前生命值时升级。"
language.strings["A reset strengthens Subtlety's emergency toolkit once unlocked."] = "解锁后可重置技能，强化敏锐的紧急应对能力。"
language.strings["A risky burst option; other core attacks and defensive tools come first."] = "存在风险的爆发选项；其他核心攻击和防御技能优先。"
language.strings["A scan is running: Search all can start when it's done."] = "正在扫描；扫描完成后才能开始全部搜索。"
language.strings["A short stop for healing, repositioning or escape; basic control needs no damage upgrade."] = "短暂控制可用于治疗、调整站位或逃脱；基础控制效果无需升级伤害等级。"
language.strings["A specialised party rescue or PvP tool; routine solo leveling can wait."] = "适用于特定团队救援或 PvP；常规单人升级可暂缓学习。"
language.strings["A strong Forever bear recovery tool; caster routes only need it for bear emergencies."] = "无限服强力熊形态恢复技能；施法路线仅需用于熊形态应急。"
language.strings["A strong Protection control tool once unlocked."] = "防护解锁后的强力控制技能。"
language.strings["A strong emergency self-heal when your race has it; do not apply it to every race."] = "适用种族可获得的强力紧急自疗；不要将此建议应用于所有种族。"
language.strings["A strong leveling imbue when you melee; prioritise the imbue you actually choose."] = "近战升级时有力的武器附魔；优先升级实际选用的附魔。"
language.strings["A stronger slow can help kiting or PvP; the first poison already controls runners."] = "更强的减速有助于风筝或 PvP；初级毒药已能控制逃跑目标。"
language.strings["A tank must recover loose enemies; buy before tanking in any build."] = "坦克必须能接回失控敌人，任何天赋坦怪前都应学习。"
language.strings["A useful Marksmanship control tool when unlocked; do not assume a baseline trainer purchase."] = "射击解锁后的实用控制，不要假定可直接向基础训练师购买。"
language.strings["A useful instant pack finisher; keep current for deliberate AoE, including Frost grinding."] = "各天赋可用的瞬发群体终结技能，有计划群攻时应升级，包括冰霜刷怪。"
language.strings["A useful passive safety option; not a damage or resource priority."] = "有用的被动安全保障；优先级低于伤害或资源相关技能。"
language.strings["A useful stealth stun; later damage ranks are optional outside opener-heavy play."] = "实用的潜行昏迷；不依赖起手伤害时，后续伤害等级可选。"
language.strings["A way to manage fleeing enemies; avoid it where its trade-off makes a pull unsafe."] = "可控制逃跑敌人；副作用会使战斗不安全时避免使用。"
language.strings["AH"] = "拍卖行"
language.strings["API check (send this to Claude if something isn't working):"] = "API 检查（功能异常时可提供此信息用于排查）："
language.strings["Absorption protects casts and emergencies; healing builds merit regular upgrades."] = "吸收效果可保护施法并应对紧急情况；治疗天赋值得定期升级。"
language.strings["Ad text. {professions} becomes your profession links; {water} and {food} your best conjured water and food; {portals} the cities you can portal to."] = "广告内容。{professions} 会替换为专业链接；{water} 和 {food} 为你能制造的最高级饮水与食物；{portals} 为你能开启传送门的城市。"
language.strings["Added %d %s for %s to shopping list \"%s\". Check Want and Up to there; the Buy queue buys from the list while Buy from this list in the Buy queue is ticked (/fl lists)."] = "已将 %d 个%s（用途：%s）加入购物清单“%s”。请检查需求数量与价格上限；在购买队列中勾选“按此清单购买”后才会按清单购买（/fl lists）。"
language.strings["Added %d %s to shopping list \"%s\" for disenchanting. Check Want and Up to there; the Buy queue buys from the list while Buy from this list in the Buy queue is ticked (/fl lists)."] = "已将 %d 个%s加入分解购物清单“%s”。请检查需求数量与价格上限；在购买队列中勾选“按此清单购买”后才会按清单购买（/fl lists）。"
language.strings["Added the materials for %d %s of %s to shopping list \"%s\". Check Want and Up to there (/fl lists)."] = "已将制作 %d %s（%s）所需的材料加入购物清单“%s”。请检查需求数量与价格上限（/fl lists）。"
language.strings["Advertise crafting"] = "发布制作广告"
language.strings["All characters"] = "所有角色"
language.strings["Alliance"] = "联盟"
language.strings["Already searching "] = "正在搜索 "
language.strings["Alterac Mountains"] = "奥特兰克山脉"
language.strings["Alterac Valley"] = "奥特兰克山谷"
language.strings["Always (turns the finder off)"] = "始终静音（关闭客户寻找）"
language.strings["An Affliction damage candidate; confirm current unlock and use before maintaining upgrades."] = "痛苦输出候选技能；及时升级前先确认当前解锁条件和用途。"
language.strings["An Arms attack candidate; buy upgrades only after confirming its unlock and place in the rotation."] = "可作为武器天赋攻击技能；确认解锁条件和循环用途后，再购买后续等级。"
language.strings["An Assassination attack candidate; confirm its unlock and whether it replaces an existing finisher."] = "可作为刺杀攻击技能；先确认解锁条件，以及是否替代已有终结技。"
language.strings["An Enhancement cooldown candidate; learn only after its current unlock and usefulness are confirmed."] = "可作为增强天赋的冷却技能；确认已解锁且实际有用后再学习。"
language.strings["An Enhancement imbue option; Classic guides disagree on its value versus Rockbiter while leveling."] = "增强可选武器附魔；经典旧世指南对升级时它与石化武器的价值存在分歧。"
language.strings["An alternative caster nuke; prioritise it when your talents and gear favor Arcane damage."] = "可替代的直接伤害法术；天赋和装备偏向奥术伤害时优先。"
language.strings["An alternative imbue; confirm Forever's effect and upgrade only if it is your choice."] = "可选武器附魔；确认时光服效果，并仅在实际选用时升级。"
language.strings["An announced Holy healing tool; group damage makes it valuable once the talent unlocks it."] = "已公布的神圣治疗技能；天赋解锁后，适合应对团队伤害。"
language.strings["An announced Survival interrupt supports melee pulls; confirm unlock and any paid upgrades."] = "已公布的生存打断技能有助于近战引怪，需核实解锁方式和是否存在付费升级。"
language.strings["An emergency instant cast for a healing build; learn it when the talent unlocks it."] = "治疗天赋的应急瞬发技能，解锁后学习。"
language.strings["An extra threat drop; useful with ranged pet play but not a replacement for Feign Death."] = "额外降低威胁的技能，远程带宠玩法有用，但不能替代假死。"
language.strings["An important Arms or Fury attack for single or multiple targets; tanks use it less."] = "武器或狂暴重要的单体及多目标攻击；坦克使用较少。"
language.strings["An important Frost emergency reset once unlocked."] = "冰霜解锁后的重要应急重置技能。"
language.strings["An important Protection emergency tool once unlocked."] = "防护解锁后的重要紧急技能。"
language.strings["An important escape and reset; the first rank already supplies the main safety tool."] = "重要的逃脱与重置技能；1 级已具备主要保命功能。"
language.strings["An instant finisher for every tree; buy upgrades if you use it regularly."] = "各天赋可用的瞬发终结技能，经常使用时购买升级。"
language.strings["An optional damage trap; buy ranks if it is part of your pulls."] = "可选伤害陷阱，用于你的引怪方式时再升级。"
language.strings["An optional emergency mana reserve for long or difficult pulls; drinking covers ordinary solo downtime."] = "长战斗或困难引怪的可选应急法力储备，普通单人恢复通常喝水即可。"
language.strings["An optional slowing imbue; a normal damage imbue and Frost Shock usually cover leveling."] = "可选减速武器附魔；普通伤害附魔与冰霜震击通常已足够升级使用。"
language.strings["Any tree regularly healing groups needs suitable heals; Restoration is the default priority context."] = "任何天赋只要经常治疗队伍，都需要合适的治疗技能；恢复天赋优先考虑。"
language.strings["Any tree regularly healing groups needs suitable support; Restoration is the default priority context."] = "任何天赋只要经常治疗队伍，都需要合适的治疗技能；默认优先推荐给恢复天赋。"
language.strings["Any tree tanking dungeons needs bear tools; tree labels do not forbid off-spec tanking."] = "任何天赋担任副本坦克都需要熊形态工具，不能仅按天赋名称排除。"
language.strings["Any tree tanking dungeons needs tank tools; tree labels do not forbid off-spec tanking."] = "任何天赋承担地下城坦克时都需要坦克技能；天赋分类不限制兼职坦克。"
language.strings["Appearance choice; ordinary Polymorph supplies the leveling control."] = "外观选择；普通变形术已能提供升级控制。"
language.strings["Arathi Highlands"] = "阿拉希高地"
language.strings["Arcane Salvager placed. Your buffs now:"] = "奥术回收装置已放置。当前增益："
language.strings["Arcane talents can support this channel; otherwise its Mana cost rarely justifies upgrades."] = "奥术天赋可能支持此引导技能，否则通常不值得为其法力消耗持续升级。"
language.strings["Area-pull playstyle can justify this in other trees; do not recommend AoE pulls solely from the category."] = "其他天赋采用群拉玩法也可能值得学习，不能仅凭分类就推荐群拉。"
language.strings["Arms turns paired targets into efficient pulls once unlocked."] = "武器解锁后可高效应对双目标战斗。"
language.strings["Arms' regular attack once unlocked; keep upgrades useful for your rotation."] = "武器解锁后的常规攻击；按当前循环需要升级。"
language.strings["Ashenvale"] = "灰谷"
language.strings["Auction house: couldn't find the rows on the"] = "拍卖行：未找到以下页面的条目："
language.strings["Auction house: couldn't read prices on the"] = "拍卖行：无法读取以下页面的价格："
language.strings["Azshara"] = "艾萨拉"
language.strings["Backup tank control when Taunt fails or is unavailable; learn before tanking."] = "嘲讽失败或不可用时的备用坦克控制；承担坦克前应学习。"
language.strings["Badlands"] = "荒芜之地"
language.strings["Bag item %d (%s), bag %d slot %d, tooltip:"] = "背包物品 %d（%s），背包 %d，格子 %d，提示："
language.strings["Balance and solo Restoration use it; Feral can stop upgrading once forms take over."] = "平衡及单人恢复会用到；野性转用形态后可停止升级。"
language.strings["Bear combat uses its Rage; caster and healing builds can wait unless tanking."] = "熊形态战斗需要怒气；施法和治疗路线不坦怪时可缓学。"
language.strings["Bear mobility and interruption help Feral pulls or tanking; talent unlock must be checked."] = "熊形态位移和打断有助于野性引怪或坦怪，但需核实天赋解锁。"
language.strings["Bear tanks need an emergency group taunt; non-tanks rarely use it."] = "熊坦需要应急群嘲，非坦克很少用到。"
language.strings["Bear tanks reduce incoming damage; occasional bear use needs fewer upgrades."] = "熊坦需降低承受伤害，偶尔用熊形态则不必频繁升级。"
language.strings["Before Frostbolt is learned, this is your starter damage even on a future Frost route. Classic Fire guide prioritises rank 5 at 24; later Frost builds can skip unused Fireball upgrades."] = "学会寒冰箭前，即使计划走冰霜路线也需用它输出。经典版火焰指南24级优先学5级；后续冰霜可跳过不用的火球术等级。"
language.strings["Best way: "] = "最佳用途："
language.strings["Best way: %s"] = "最佳用途：%s"
language.strings["Blackrock orcs in Redridge, then Hillsbrad"] = "赤脊山的黑石兽人，之后前往希尔斯布莱德"
language.strings["Blasted Lands"] = "诅咒之地"
language.strings["Burning Steppes"] = "燃烧平原"
language.strings["Buy %s"] = "购买%s"
language.strings["Buy for a known fire encounter rather than routine questing."] = "针对已知火焰伤害战斗购买；常规任务无需优先学习。"
language.strings["Buy for a known frost encounter rather than routine questing."] = "针对已知冰霜伤害战斗购买；常规任务无需优先学习。"
language.strings["Buy for a known nature encounter rather than routine questing."] = "针对已知自然伤害战斗购买；常规任务无需优先学习。"
language.strings["Buy for a known shadow-damage encounter; routine questing can skip."] = "针对已知暗影伤害战斗购买；常规任务可跳过。"
language.strings["Buy for troublesome diseases or group healing; do not train upgrades without a use."] = "疾病造成困扰或承担组队治疗时购买；无用途时无需升级。"
language.strings["Buy for troublesome poisons or group healing; do not train upgrades without a use."] = "毒药造成困扰或承担组队治疗时购买；无用途时无需升级。"
language.strings["Buy if its judgement supports your fights; it is not every build's active seal."] = "审判效果有助于当前战斗时再购买；并非所有天赋都会使用此圣印。"
language.strings["Buy only for known dangerous fire damage; routine leveling does not need it."] = "仅针对明确危险的火焰伤害购买，常规升级不需要。"
language.strings["Buy only for known dangerous frost damage; routine leveling does not need it."] = "仅针对明确危险的冰霜伤害购买，常规升级不需要。"
language.strings["Buy queue panel: moved to the profession window's layer,"] = "购买队列面板：已移到专业窗口的层级，"
language.strings["Buy queue: %s left the flips: %s (vendor pays %s, limit was %s)."] = "购买队列：%s已移出套利列表：%s（商店收购价%s，原上限%s）。"
language.strings["Buy queue: %s page has %d listings; cheapest %s each, %s; limit %s."] = "购买队列：%s页面有%d笔挂单；最低单价%s，%s；上限%s。"
language.strings["Buy queue: %s, the queue wanted %s, the list still wants %s."] = "购买队列：%s，队列计划%s，清单仍需%s。"
language.strings["Buy queue: browse failed"] = "购买队列：浏览失败"
language.strings["Buy queue: looking up %s: %d rows, %d of them this item, cheapest %s, limit %s."] = "购买队列：查询%s：共%d条，其中%d条为此物品，最低价%s，上限%s。"
language.strings["Buy queue: no versions found for"] = "购买队列：未找到以下物品的词缀版本："
language.strings["Buy queue: search failed"] = "购买队列：搜索失败"
language.strings["Buying is paused on %s (it crafts things): check its Want and tick Buy from this list again."] = "已暂停按 %s 购买（此清单用于制作）：请检查需求数量，再次勾选“按此清单购买”。"
language.strings["Caster control and dispels for suitable routes or PvP; ordinary pet leveling can wait."] = "适合特定路线或 PvP 的施法控制与驱散；普通宠物升级可暂缓。"
language.strings["Caster or healing pressure poisons can wait unless player combat is part of the route."] = "针对施法或治疗的毒药可暂缓，除非路线包括玩家对战。"
language.strings["Caster questing needs damage; Feral uses early ranks or cheap pulls, not every upgrade."] = "施法任务路线需要伤害；野性可用低等级引怪，不必每级都学。"
language.strings["Cat fights often end before a long bleed pays off; this finishes the target."] = "猫形态短战斗通常来不及发挥长流血收益，可用它终结目标。"
language.strings["Central pet-based Demonology defence once unlocked."] = "恶魔学识解锁后，依赖宠物的核心防御技能。"
language.strings["Central to pet-tanking Demonology; other builds can use a damage pet instead."] = "宠物坦怪恶魔学识的核心；其他天赋可改用输出宠物。"
language.strings["Chat channels (GetChannelName): %s"] = "聊天频道（GetChannelName）：%s"
language.strings["Chat channels (channel list window): %s"] = "聊天频道（频道列表窗口）：%s"
language.strings["Choose a regular list without Any price, or make a new one."] = "请选择未启用“不限价格”的普通清单，或新建清单。"
language.strings["Choose a regular shopping list, or make a new one."] = "请选择普通购物清单，或新建清单。"
language.strings["Choose a whole amount from 1 to 10000."] = "请输入 1 至 10000 的整数数量。"
language.strings["Choose a whole number of crafts from 1 to 10000."] = "请输入 1 至 10000 的整数制作次数。"
language.strings["Class travel convenience; buy when the trip is useful."] = "职业传送更方便，行程有需要时学习。"
language.strings["Classic AoE guide starts Blizzard at 20 and improves the slow through talents around 22; single-target Frost does not need every damage rank. Verify Forever talents before using this route."] = "经典版群攻指南20级开始用暴风雪，约22级通过天赋强化减速；单体冰霜不必学每个伤害等级。采用前请核实无限服天赋。"
language.strings["Classic Arms and Fury guides prioritise its level-36 unlock even for single targets; confirm Forever acquisition."] = "经典旧世武器和狂暴指南优先学习 36 级解锁的此技能，单体也适用；请确认时光服获取方式。"
language.strings["Classic Feral guide: stop caster upgrades after level 10 once bear combat takes over; keep them if you still quest as a caster. Forever Wrath was redesigned, so compare its current tooltip."] = "经典版野性指南在10级转熊后停止升级施法攻击；若仍靠施法做任务则应保留。无限服已重做愤怒，需对照当前提示。"
language.strings["Classic Feral guide: upgrades only through level 10 on the form route; a cheap pulling rank can remain useful later."] = "经典版野性变形路线仅在10级前升级；之后低耗引怪等级仍可能有用。"
language.strings["Classic Frost guide buys rank 2 at 46, rank 3 at 52 and rank 4 at 58. Forever paid services at those levels are observed, but their talent prerequisite and exact rank labels remain separate checks."] = "经典版冰霜指南46级学2级、52级学3级、58级学4级。无限服已观察到对应等级付费服务，但天赋前置与准确等级名称仍需分别核实。"
language.strings["Classic Frost guide prioritises rank 4 at 20 and rank 5 at 26; Fire can keep rank 1 for a quick slow: since October 8 a rank that low still slows but gets almost no spell power and never triggers Frost talents (Blizzard's own example)."] = "经典版冰霜指南20级学4级、26级学5级；火焰可保留1级快速减速。10月8日起，如此低的等级虽仍减速，但几乎不享受法术强度且不会触发冰霜天赋，这是暴雪给出的示例。"
language.strings["Classic Holy or Discipline guide can stop upgrades once Holy Fire is used as the opener; Shadow still prioritises Mind Blast."] = "经典旧世神圣或戒律路线可在改用神圣之火起手后停止升级；暗影仍优先升级心灵震爆。"
language.strings["Classic Sword route upgrades at 14/22/30/38/46/54; stop maintaining it if a confirmed Forever builder replaces it."] = "经典旧世剑路线在 14/22/30/38/46/54 级升级；确认时光服其他技能已取代它后，可停止升级。"
language.strings["Classic budget guide lists rank 1 only; later stun-duration upgrades can still be valuable for harder pulls. Learn does not mean all higher ranks are useless."] = "经典旧世省钱指南仅推荐学习 1 级；后续延长昏迷时间的等级在高难度战斗中仍有价值。“学习”不代表所有后续等级都无用。"
language.strings["Classic budget routes may stop around rank 4; Forever adds Attack Power scaling and Arms interactions, so that old stop rule is not adopted."] = "经典旧世省钱路线可能在约 4 级停止升级；时光服增加攻击强度加成及武器天赋联动，因此不采用旧版停止规则。"
language.strings["Classic dagger route upgrades at 12/20/28/36/44/52; sword users can defer these ranks. Weapon choice overrides the tree label."] = "经典旧世匕首路线在 12/20/28/36/44/52 级升级；剑类使用者可暂缓。武器选择优先于天赋标签。"
language.strings["Classic estimate"] = "经典旧世估算"
language.strings["Classic first learned at 34; the regeneration is useful for kiting, whereas contact-heavy AoE may prefer Ice Armor. Forever level-34 service is observed."] = "经典版34级首次学习，恢复适合风筝，近身群攻可能更适合冰甲术。已观察到无限服34级服务。"
language.strings["Classic first rank at 10 supplies shards; upgrade only if its damage is part of your chosen loop."] = "经典旧世 10 级的 1 级已能获取碎片；仅在其伤害属于常用循环时升级。"
language.strings["Classic gem upgrade at 38; buy if you actually use combat Mana reserves."] = "经典版38级宝石升级，实际使用战斗法力储备时再买。"
language.strings["Classic gem upgrade at 48; buy if you actually use combat Mana reserves."] = "经典版48级宝石升级，实际使用战斗法力储备时再买。"
language.strings["Classic gem upgrade at 58; buy if you actually use combat Mana reserves."] = "经典版58级宝石升级，实际使用战斗法力储备时再买。"
language.strings["Classic guide prioritises rank 5 at level 40 for better recovery. Forever offers a level-40 service; use observed client ranks and tooltips for its exact label."] = "经典版指南优先在40级学习5级以改善恢复。已观察到无限服40级服务，准确名称应以客户端等级和提示为准。"
language.strings["Classic guide: rank 2 at 26 and rank 3 at 42 are optional buys; the first rank already interrupts."] = "经典旧世指南：26 级的 2 级和 42 级的 3 级可选购；1 级已能打断。"
language.strings["Classic guide: rank 2 at 42 is optional on a budget; the first rank already provides the emergency reset."] = "经典旧世指南：预算紧张时 42 级的 2 级可选学；1 级已能紧急重置战斗。"
language.strings["Classic guides buy rank 2 at 22; repeated AoE use justifies upgrades, while a one-target route can defer them. This is not a mandate to AoE grind."] = "经典版指南在22级学习2级；经常群攻值得升级，单体路线可缓学。这不代表必须靠群怪升级。"
language.strings["Classic guides often defer this outside large packs; Forever makes it usable in Defensive Stance and adds scaling, so reassess for tanking instead of copying that skip rule."] = "经典旧世指南通常在非大规模群怪时暂缓学习；时光服允许防御姿态使用并增加成长加成，坦克应重新评估，不宜照搬跳过规则。"
language.strings["Classic mana gem at 28 is optional emergency Mana; ordinary solo leveling can delay it if gold is tight."] = "经典版28级法力宝石提供可选应急法力，金币紧张的单人升级可缓学。"
language.strings["Classic pet quest at level 10 changes the leveling loop; confirm the Forever quest and unlock in game."] = "经典版10级宠物任务会改变升级流程，需在游戏中确认无限服任务及解锁方式。"
language.strings["Classic physical armor becomes available at 30; choose it or Mage Armor at 34 by pull style instead of buying every alternative armor rank."] = "经典版30级可学此物理护甲；按引怪方式选择它或34级法师护甲，不必购买所有替代护甲等级。"
language.strings["Classic rank 2 at 20 gives longer control; level 40 is rank 3, not rank 2. The level-40 upgrade is useful when you need longer holds, not a verified higher-target-level requirement. Forever level-40 service observed; exact trainer rank API pending."] = "经典版20级2级可延长控制，40级为3级而非2级。40级升级适合需要更长控制的场景，尚未证实是提高可控目标等级的要求。无限服已观察到40级服务，准确训练师等级API仍待核实。"
language.strings["Classic rank 3 at level 40 reduces the movement penalty; useful if stealth travel is a regular part of your route."] = "经典旧世 40 级的 3 级可降低移动惩罚；经常潜行赶路时有用。"
language.strings["Classic travel unlock at 20 is a major speed gain before riding; confirm Forever trainer availability."] = "经典旧世 20 级解锁的移动技能，可在学习骑术前显著提速；请确认时光服训练师是否提供。"
language.strings["Classic unlock at level 20 is a major questing change; confirm Forever acquisition rather than assuming the quest or trainer is identical."] = "经典版20级解锁会明显改变任务体验；请核实无限服获取方式，不要假定任务和训练师相同。"
language.strings["Classic upgrade at 50 is optional for stronger slowing; buy when kiting or PvP makes it useful."] = "经典旧世 50 级升级可增强减速；需要风筝或 PvP 时再购买。"
language.strings["Cleansing and resurrection are class utility, not healer-only purchases."] = "净化和复活属于职业通用能力，并非只有治疗才需学习。"
language.strings["Cleansing, resurrection and offensive dispelling are not healer-only tools."] = "净化、复活和进攻驱散并非治疗专用技能。"
language.strings["Clear all"] = "全部清除"
language.strings["Click to post it in Trade. Right-click to change the text."] = "点击后发布到交易频道；右键修改内容。"
language.strings["Combat gains strong two-target damage once unlocked; use it for suitable pulls."] = "战斗天赋解锁后可提供强力双目标伤害；用于适合的战斗。"
language.strings["Combat parry responses improve solo fighting once unlocked."] = "战斗天赋解锁后的招架反击，可改善单人战斗。"
language.strings["Combat resurrection matters most in healing groups; solo play has no target for it."] = "战斗复活在组队治疗时更重要，纯单人玩法没有复活目标。"
language.strings["Combat traps strengthen Survival pack damage; other builds upgrade for deliberate AoE."] = "战斗中陷阱可增强生存群体伤害；其他天赋有计划群攻时再升级。"
language.strings["Combine into Greater Astral Essence"] = "合成强效星界精华"
language.strings["Combine into Greater Eternal Essence"] = "合成强效不灭精华"
language.strings["Combine into Greater Magic Essence"] = "合成强效魔法精华"
language.strings["Combine into Greater Mystic Essence"] = "合成强效秘法精华"
language.strings["Combine into Greater Nether Essence"] = "合成强效虚空精华"
language.strings["Commands: /fl (window), /fl scan, /fl scan full, /fl scan materials, /fl stop, /fl queue, /fl lists, /fl pull, /fl export, /fl csv, /fl import, /fl source <auto/own/auctionator>, /fl shuffles, /fl shuffles all, /fl cut <percent>, /fl margin <percent>, /fl seconds <n>, /fl deals, /fl deals settings, /fl minimap, /fl money, /fl session start, /fl session stop, /fl runs, /fl de, /fl pair <name>, /fl sync, /fl tooltip, /fl welcome, /fl new, /fl api, /fl debug"] = "命令：/fl（主窗口）；/fl scan；/fl scan full；/fl scan materials；/fl stop；/fl queue；/fl lists；/fl pull；/fl export；/fl csv；/fl import；/fl source <auto/own/auctionator>；/fl shuffles；/fl shuffles all；/fl cut <百分比>；/fl margin <百分比>；/fl seconds <秒数>；/fl deals；/fl deals settings；/fl minimap；/fl money；/fl session start；/fl session stop；/fl runs；/fl de；/fl pair <角色名>；/fl sync；/fl tooltip；/fl welcome；/fl new；/fl api；/fl debug"
language.strings["Conjured "] = "魔法制造的 "
language.strings["Control a dangerous pull before healing or escaping."] = "危险引怪后，先控制敌人再治疗或逃脱。"
language.strings["Control an extra enemy; Forever permits combat use, making this broadly useful."] = "控制额外敌人；无限服允许战斗中使用，因此适用范围较广。"
language.strings["Control and emergency recovery rescue dangerous pulls."] = "控制和紧急恢复可挽救危险战斗。"
language.strings["Control for beasts and dragonkin; buy for routes or groups that need it."] = "用于控制野兽和龙类，路线或队伍需要时学习。"
language.strings["Control undead on a route that needs it; skip extra ranks without a use."] = "路线需要控制亡灵时学习；没有用途时无需购买更高等级。"
language.strings["Control, fear removal and travel help every tree."] = "控制、解除恐惧和移动技能适合所有天赋。"
language.strings["Control, interruption and escape are useful in every tree."] = "控制、打断和逃脱适合所有天赋。"
language.strings["Control, interruption, cleansing and escape matter in every tree."] = "控制、打断、净化与逃脱对所有天赋都有用。"
language.strings["Core Affliction drain sustain; other builds buy ranks when draining is part of their fights."] = "痛苦核心吸取续航；其他天赋在战斗使用吸取时再购买等级。"
language.strings["Core Shadow burst; Holy or Discipline can save by using their chosen Holy damage spells."] = "暗影核心爆发技能；神圣或戒律可使用自己的神圣伤害法术节省开支。"
language.strings["Core Survival melee damage; ranged builds only need a fallback or weaving ranks."] = "生存近战核心伤害，远程路线仅需作为应急或穿插近战的技能。"
language.strings["Core bear pack threat; upgrade for tanking, not for cat-only combat."] = "熊形态群体仇恨核心技能；坦怪时升级，仅用猫形态可缓学。"
language.strings["Core group recovery for Restoration; other builds upgrade when they heal groups."] = "恢复的核心团队治疗；其他天赋承担组队治疗时再升级。"
language.strings["Core larger heals for healing builds; Shadow upgrades depend on group healing or recovery needs."] = "治疗天赋的主要大额治疗技能。暗影是否升级，取决于组队治疗或自身恢复的需要。"
language.strings["Core rogue travel and opener tool; later ranks improve access and movement."] = "盗贼移动和起手的核心技能；后续等级有助于接近目标与移动。"
language.strings["Core tank threat and useful solo armor reduction; upgrade when used in either role."] = "核心坦克仇恨技能，也可用于单人破甲；用于任一职责时应升级。"
language.strings["Couldn't start that purchase: %s"] = "无法开始购买：%s"
language.strings["Craft "] = "制作"
language.strings["Craft %s"] = "制作%s"
language.strings["Crates: tooltip reading isn't available."] = "箱子：物品提示读取接口不可用。"
language.strings["Customer alerts are back on (you logged out since silencing them)."] = "客户提醒已恢复（你在静音后退出过游戏）。"
language.strings["Customer alerts are on."] = "客户提醒已开启。"
language.strings["Customer alerts are quiet %s. Requests are still listed in the Customers window."] = "客户提醒已静音%s。需求仍会列在客户窗口中。"
language.strings["Customer finder off. Turn it back on in Settings, Customers, or with /fl customers on."] = "客户寻找已关闭。可在“设置→客户”中或输入 /fl customers on 重新开启。"
language.strings["Customer? |Hplayer:%s|h[%s]|h (%s, %s): %s"] = "潜在客户？|Hplayer:%s|h[%s]|h（%s，%s）：%s"
language.strings["Customers|r"] = "客户|r"
language.strings["Damage over time supports solo questing in every tree; use where enough ticks will land."] = "持续伤害可帮助所有天赋完成单人任务；目标存活时间足够时使用。"
language.strings["Darkshore"] = "黑海岸"
language.strings["Darnassus"] = "达纳苏斯"
language.strings["Deadwind Pass"] = "逆风小径"
language.strings["Deal alert sound "] = "市场机会提醒声音："
language.strings["Deals are now listings "] = "当前市场机会条件：挂单"
language.strings["Debug messages %s"] = "调试消息：%s"
language.strings["Deposit: item %d, quantity %d, %d hours: %s (%s); Classic estimate %s. Values allow for one unsold 8-hour listing."] = "保管费：物品 %d，数量 %d，%d 小时：%s（%s）；经典旧世估算 %s。估值计入一次 8 小时未售出挂单的费用。"
language.strings["Desolace"] = "凄凉之地"
language.strings["Destruction burst for a rotation that uses it; the talent unlock is separate from paid upgrades."] = "循环需要时可提供毁灭爆发；天赋解锁与付费升级分别考虑。"
language.strings["Disenchant (%s)"] = "分解（%s）"
language.strings["Dive does not make this mandatory for ordinary drain-tanking; long targets can justify it, short ones often die before enough ticks. Forever may change the balance."] = "Dive 未将其列为普通吸血坦怪必需技能；长时间目标值得使用，短时间目标通常在持续伤害充分生效前死亡。时光服可能改变其收益。"
language.strings["Dive identifies level 38 as an important Classic drain-tanking efficiency point; earlier wand or pet play remains valid. Forever coefficients and Mana costs can shift that point."] = "Dive 将 38 级列为经典旧世吸血坦怪的重要效率节点；更早使用魔杖或宠物仍然可行。时光服的系数和法力消耗可能改变此节点。"
language.strings["Draining ordinary enemies is rarely a better plan than killing them."] = "对普通敌人吸取法力，通常不如直接击杀。"
language.strings["Dun Morogh"] = "丹莫罗"
language.strings["Durotar"] = "杜隆塔尔"
language.strings["Durotar, Mulgore"] = "杜隆塔尔、莫高雷"
language.strings["Durotar, Mulgore, Tirisfal, then the Barrens and Silverpine"] = "杜隆塔尔、莫高雷、提瑞斯法林地，之后前往贫瘠之地和银松森林"
language.strings["Duskwood"] = "暮色森林"
language.strings["Dustwallow Marsh"] = "尘泥沼泽"
language.strings["Early combo builder for all; Combat swords keep it current, replacement builders can defer it."] = "所有天赋早期的连击点生成技能；战斗剑应及时升级，改用其他技能后可暂缓。"
language.strings["Early damage for all builds; later upgrades depend on which seal you actually use."] = "各类天赋早期都能使用的输出手段；后续按实际使用的圣印决定是否升级。"
language.strings["Early ranks support every route before specialising; later ranks follow actual use."] = "专精成型前，早期等级适合各类路线；后续按实际用途升级。"
language.strings["Eastern Plaguelands"] = "东瘟疫之地"
language.strings["Efficient damage when enemies hit you; repeated ranks matter less in heal-only groups."] = "敌人攻击自身时可高效造成伤害；纯治疗组队不必频繁升级。"
language.strings["Elemental and solo Restoration need ranged damage; Enhancement can keep a cheap pulling rank."] = "元素和单人恢复需要远程伤害；增强可保留低等级用于拉怪。"
language.strings["Elemental burst or efficiency once unlocked; confirm talent access separately."] = "解锁后用于元素爆发或提高效率；另行确认天赋获取条件。"
language.strings["Elemental uses sustained fire damage; other builds upgrade only if enough ticks pay off."] = "元素用于持续火焰伤害；其他天赋仅在能产生足够持续伤害时升级。"
language.strings["Elwynn Forest"] = "艾尔文森林"
language.strings["Elwynn Forest, Dun Morogh, Darkshore"] = "艾尔文森林、丹莫罗、黑海岸"
language.strings["Elwynn kobolds and gnolls, then the Defias in Westfall"] = "艾尔文森林的狗头人与豺狼人，之后是西部荒野的迪菲亚成员"
language.strings["Elwynn, Dun Morogh, Teldrassil, then Westfall and Darkshore"] = "艾尔文森林、丹莫罗、泰达希尔，之后前往西部荒野和黑海岸"
language.strings["Emergency durability for every build; essential for early Feral combat."] = "各天赋的应急生存手段，早期野性战斗尤其需要。"
language.strings["Emergency fast healing is essential for healers; solo Shadow can keep a cheaper recovery heal."] = "快速紧急治疗对治疗角色至关重要；单人暗影可保留较便宜的恢复技能。"
language.strings["Emergency group threat for a tank; solo questing can wait."] = "坦克的紧急群体仇恨技能；单人任务可暂缓。"
language.strings["Emergency protection spends Mana; upgrade if repeated hits or pack pulls make you use it."] = "应急防护消耗法力，经常挨打或群拉需要它时再升级。"
language.strings["Emergency survival and control help every tree."] = "紧急生存和控制技能适合所有天赋。"
language.strings["Enchanted "] = "附魔 "
language.strings["Encounter-specific healing trade-off; ordinary leveling can skip."] = "特定战斗中的治疗取舍，普通升级可跳过。"
language.strings["Engage, interrupt, slow and escape tools matter in every tree."] = "接敌、打断、减速和逃脱对所有天赋都重要。"
language.strings["Enhancement can pull with rank 1 once melee takes over: cheap, but its damage is small, and since October 8 low ranks get little spell power. Elemental or caster Restoration needs current damage ranks."] = "增强以近战为主后可用 1 级拉怪：消耗低，但伤害小，且 10 月 8 日后低等级技能获得的法术强度加成很少。元素或法术输出恢复需要及时升级。"
language.strings["Epic travel later; its quest and riding requirements are separate from combat spell priorities."] = "后期的史诗坐骑；相关任务和骑术要求应与战斗技能优先级分别考虑。"
language.strings["Essential access while leveling with a pet. A confirmed petless Lone Wolf route can defer unused pet services."] = "带宠物升级时必需；确认采用无宠独狼路线后，可缓学不用的宠物服务。"
language.strings["Essential before fighting in forms; keep current if casting is still your main damage route."] = "开始依赖形态前必需；若仍主要施法输出，应继续升级。"
language.strings["Essential before the chosen Shadow attacks become available; later Shadow can defer its damage ranks."] = "选定的暗影攻击技能解锁前，应保留此技能的有效等级；后期暗影可暂缓升级伤害等级。"
language.strings["Essential early damage and Fire play; dot-focused builds can defer later ranks if they omit it."] = "早期输出和火焰打法的重要技能；以持续伤害为主且不用它时，可暂缓后续等级。"
language.strings["Essential early recovery; later stronger heal families replace its role."] = "早期重要的恢复技能；后期更强的治疗系列会取代其用途。"
language.strings["Essential for a Blizzard AoE route; a single-target Frost build can defer damage ranks."] = "暴风雪群攻路线需要此技能，单体冰霜可缓升伤害等级。"
language.strings["Essential for bear play; other builds can defer it unless tanking."] = "熊形态战斗必需；其他天赋不坦怪时可缓学。"
language.strings["Essential for deliberate shield tanking; damage builds learn before taking that role."] = "明确使用盾牌坦怪时必需；输出天赋承担该职责前应学习。"
language.strings["Essential tank threat; damage or healing builds should not use it routinely."] = "坦克建立仇恨的关键技能；输出或治疗通常不应使用。"
language.strings["Essential when tanking in any tree; no routine solo damage value."] = "任何天赋承担坦克时都必需；常规单人输出无收益。"
language.strings["Extra armor when needed; do not maintain every aura rank ahead of your preferred one."] = "需要时可提高护甲；优先升级常用光环，无需维持所有光环的最新等级。"
language.strings["Extra damage while enemies hit you; Forever scaling improves it but core attacks come first."] = "敌人攻击你时提供额外伤害；无限服加成有所提高，但核心攻击优先。"
language.strings["Extra pack fear can save you but may pull more enemies; useful rather than routine."] = "额外群体恐惧可用于自救，但可能引来更多敌人；属于有用的应急技能。"
language.strings["Extra presets and relocation help frequent totem users; basics come first."] = "额外预设与图腾迁移方便经常使用图腾的玩家；优先学好基础技能。"
language.strings["Extra stun control for tough targets or PvP; routine solo kills can use other finishers."] = "用于强敌或 PvP 的额外昏迷控制；普通单人击杀可选择其他终结技。"
language.strings["Favor (currency %d): name \"%s\", you have %s, max %s."] = "商人的恩惠（货币 %d）：名称“%s”，持有 %s，上限 %s。"
language.strings["Favor (currency %d): nothing returned."] = "商人的恩惠（货币 %d）：未返回数据。"
language.strings["Favor: C_CurrencyInfo.GetCurrencyInfo is missing."] = "商人的恩惠：缺少 C_CurrencyInfo.GetCurrencyInfo 接口。"
language.strings["Fear and similar control can ruin a pull; learn this safety tool in every build."] = "恐惧等控制可能使战斗失控；所有天赋都应学习此保命技能。"
language.strings["Felwood"] = "费伍德森林"
language.strings["Feral damage and a useful travel or escape option for other builds."] = "提供野性伤害，其他天赋也可用于赶路或逃脱。"
language.strings["Feralas"] = "菲拉斯"
language.strings["Fire's main attack; Arcane hybrids may use it, while Frost can defer later ranks."] = "火焰主要攻击，奥术混合路线也可能使用，冰霜可缓升后期等级。"
language.strings["Forever Arcane trainer upgrades are observed; prioritise when unlocked as your regular attack."] = "已观察到无限服奥术训练师升级，解锁并作为常用攻击后优先。"
language.strings["Forever Arms talents support this attack; upgrade when it belongs in your rotation."] = "时光服武器天赋支持此攻击；属于当前循环时升级。"
language.strings["Forever Holy can heal both caster and ally; prioritise when unlocked and healing groups."] = "时光服神圣天赋可同时治疗施法者和队友；解锁后用于团队治疗时优先学习。"
language.strings["Forever Holy uses a short-cooldown heal or attack; unlock and upgrade for that rotation."] = "时光服神圣天赋使用的短冷却治疗或攻击技能；用于当前循环时应解锁并升级。"
language.strings["Forever Survival supports this melee attack through talents; ranged play uses it less."] = "无限服生存天赋支持此近战攻击，远程玩法使用较少。"
language.strings["Forever adds Attack Power scaling and Arms interactions; keep useful for targets that survive the bleed."] = "时光服增加了攻击强度加成和武器天赋联动。目标存活时间足以承受流血伤害时，应保持适用等级。"
language.strings["Forever adds Attack Power scaling; worth upgrading for sustained cat damage."] = "无限服增加攻击强度加成，持续猫形态输出值得升级。"
language.strings["Forever adds kill-triggered damage and healing; important for reducing solo downtime."] = "时光服增加击杀触发的伤害和治疗；有助于减少单人恢复时间。"
language.strings["Forever adds melee Attack Power; prioritise it for Survival melee play."] = "无限服增加近战攻击强度加成，生存近战玩法优先。"
language.strings["Forever adds scaling and Defensive Stance use; tanks need pack control, solo damage routes can defer."] = "时光服增加成长加成并允许防御姿态使用；坦克需要群体控制，单人输出可暂缓。"
language.strings["Forever adds this bear threat tool; upgrade for tanking, not cat-only questing."] = "无限服新增的熊形态仇恨技能；坦怪时升级，仅用猫形态做任务可缓学。"
language.strings["Forever adds this finisher; Shadow benefits most, and failed kills damage the caster."] = "时光服新增的斩杀技能；暗影受益最大，未击杀目标时会伤害自身。"
language.strings["Forever baseline at level 20 adds solo recovery that Classic leveling guides cannot account for."] = "时光服 20 级基础技能增加单人恢复能力，经典旧世升级指南未包含这一变化。"
language.strings["Forever baseline at level 20; the Classic Marksmanship-only talent restriction must not block the recommendation."] = "无限服20级基础技能，不应套用经典版仅射击天赋可用的限制。"
language.strings["Forever baseline at level 6; Classic guides have no counterpart for this weapon strike."] = "时光服在 6 级提供此基础技能；经典旧世指南没有对应的武器攻击。"
language.strings["Forever effects need confirmation; do not treat the Classic consumable as automatically essential."] = "时光服效果仍需确认；不要默认经典旧世消耗品在此版本同样必需。"
language.strings["Forever effects need confirmation; prioritise only when this stone suits your actual build."] = "时光服效果仍需确认；此类石头适合当前天赋时再优先考虑。"
language.strings["Forever gives all Druids group resurrection; learn before grouping in any tree."] = "无限服所有德鲁伊均有群体复活，任何天赋组队前都应学习。"
language.strings["Forever gives every Paladin this pack tool; tanks need it, others upgrade for regular AoE."] = "时光服将此群怪技能提供给所有圣骑士；坦克需要学习，其他路线经常进行范围攻击时再升级。"
language.strings["Forever gives it to every race; prioritise when your route or group faces fear."] = "时光服向所有种族开放；路线或队伍需要应对恐惧时优先学习。"
language.strings["Forever is baseline at level 20; do not follow a Classic route that waits for a Holy talent point."] = "时光服在 20 级提供此基础技能；不要照搬经典旧世中等待神圣天赋点的路线。"
language.strings["Forever makes it available to all races; Shadow uses it where its damage and sustain justify Mana."] = "时光服向所有种族开放；暗影天赋在伤害与续航收益值得消耗法力时使用。"
language.strings["Forever makes this baseline; a flexible stat buff for all builds."] = "时光服将其设为基础技能；各类天赋都能使用的灵活属性增益。"
language.strings["Forever makes this baseline; recovery helps caster questing and healing."] = "时光服将其设为基础技能；有助于法系任务升级和治疗续航。"
language.strings["Forever makes this escape root baseline and usable indoors or in form."] = "无限服将此逃脱定身技能设为基础技能，室内或形态中也可使用。"
language.strings["Forever makes this ranged attack baseline; melee Survival can defer repeated upgrades."] = "无限服将此远程攻击设为基础技能，近战生存可缓升后续等级。"
language.strings["Forever replaces the old cat resource tool; prioritise in cat play when its current unlock is confirmed."] = "无限服替换了旧版猫形态资源技能；核实当前解锁方式后，猫形态玩法优先学习。"
language.strings["Forever strengthens this racial defensive; learn if offered to your race."] = "时光服强化了此种族防御技能；所属种族可学习时值得获取。"
language.strings["Forever's baseline weapon strike helps every tree's solo questing; heal-only play can defer ranks."] = "时光服基础武器攻击适合所有天赋的单人任务；纯治疗玩法可暂缓升级。"
language.strings["Forever's tank seal enables the Judgement taunt; prioritise for tanking in any tree."] = "时光服坦克圣印可让审判产生嘲讽效果；任何天赋承担坦克职责时都应优先学习。"
language.strings["Free armor reduction in Forever forms; physical builds benefit most."] = "无限服形态下可免费降低护甲，物理路线受益最多。"
language.strings["Free casts or attacks improve resource use; do not reserve this baseline tool for Balance."] = "免费施法或攻击有助于资源利用，不应仅向平衡天赋推荐这一基础技能。"
language.strings["From disenchanting: item level %s %s. Uses the finder's disenchant buying limit after the safety margin, not this list's usual-price allowance. Refreshed when added again, on Buy again or by right-clicking Up to. Type a lower price for a bigger margin."] = "来自分解：物品等级 %s，%s。使用分解筛选扣除安全余量后的分解价格上限，不使用此清单的常见价浮动比例。再次添加、点击再次购买或右键价格上限时刷新。输入更低价格可增加安全余量。"
language.strings["Frost's main attack; Fire can keep a low rank just for the slow, Arcane hybrids may keep it current."] = "冰霜主攻技能；火焰可保留低等级用于减速，奥术混合路线可能需要持续升级。"
language.strings["Frost's prevention tool; observed Forever paid upgrades deserve priority when unlocked."] = "冰霜的预防性防护，已观察到无限服付费升级，解锁后值得优先。"
language.strings["Fury burst once unlocked; use with care because its defensive trade-off can hurt."] = "狂暴解锁后的爆发技能；谨慎使用，防御方面的代价可能导致危险。"
language.strings["Fury's regular attack once unlocked; keep upgrades useful for your rotation."] = "狂暴解锁后的常规攻击；按当前循环需要升级。"
language.strings["Gave "] = "给予 "
language.strings["Good against undead or demons; train for that route rather than every ordinary pull."] = "对亡灵或恶魔有效；遇到相关路线时学习，无需用于普通战斗。"
language.strings["Good beast-only control; buy when the route or opponent needs it."] = "仅对野兽有效的实用控制，路线或对手需要时学习。"
language.strings["Good when behind the target; solo frontal cat combat can defer it."] = "在目标背后有用；单人正面猫形态战斗可缓学。"
language.strings["Group buff convenience; Arcane Intellect is enough for solo or a small party."] = "群体增益更方便，单人或小队使用奥术智慧即可。"
language.strings["Group buff convenience; Mark of the Wild covers a small leveling party."] = "群体增益更方便；升级小队用野性印记通常已足够。"
language.strings["Group buff convenience; single-target Divine Spirit covers a small party."] = "方便施加团队增益；小队使用单体神圣之灵已足够。"
language.strings["Group buff convenience; single-target Fortitude covers a small party."] = "方便施加团队增益；小队使用单体真言术：韧已足够。"
language.strings["Group cleansing for disease-heavy content; ordinary routes can use individual cures."] = "针对疾病较多内容的群体净化；普通路线可使用单体治疗疾病。"
language.strings["Group cleansing for poison-heavy content; ordinary routes can use individual cures."] = "针对毒药较多内容的群体净化；普通路线可使用单体治疗中毒。"
language.strings["Group resistance convenience for specific encounters; skip ordinary leveling."] = "针对特定战斗的群体抗性便利技能；常规升级可跳过。"
language.strings["Group summoning helps parties rather than every solo pull."] = "团队召唤用于帮助队伍，并非每场单人战斗都需要。"
language.strings["Group transport saves or earns gold but is not required for solo questing."] = "群体传送可节省或赚取金币，但单人做任务并非必需。"
language.strings["Group travel is useful; turn it off before anyone takes damage."] = "群体赶路有用，有人即将受伤前应关闭。"
language.strings["Guard directions: map flag functions %s / %s; flag event %s. Ask a city guard for a profession trainer to test."] = "卫兵指路：地图旗标接口 %s / %s；旗标事件 %s。可询问主城卫兵专业训练师的位置进行测试。"
language.strings["Guard flag (%s): \"%s\" at %s, %s on %s. You asked %s for \"%s\"."] = "保护标记（%s）：“%s”，位置 %s，%s，页面 %s。你向 %s 请求了“%s”。"
language.strings["Healers need a threat escape in groups; solo Shadow can usually skip."] = "治疗组队时需要降低仇恨；单人暗影通常可跳过。"
language.strings["Healers need reliable casts when hit; melee builds usually choose another aura."] = "治疗受击时需要稳定施法；近战天赋通常可选择其他光环。"
language.strings["Healing groups need recovery from party damage; solo Shadow rarely casts it."] = "组队治疗需要应对全队受伤；单人暗影很少使用。"
language.strings["Hides every request in the list, like x on each. New ones still show up."] = "隐藏当前列表中的全部需求，效果与逐项点击 x 相同。新需求仍会显示。"
language.strings["High-level group convenience; ordinary blessings remain sufficient."] = "高等级团队便利技能；普通祝福已足够应付日常需要。"
language.strings["Hillsbrad Foothills"] = "希尔斯布莱德丘陵"
language.strings["Holy or Discipline questing uses this damage spell; Shadow can defer it after switching attacks."] = "神圣或戒律任务升级使用的输出法术；暗影改用其他攻击后可暂缓。"
language.strings["Holy protection from interruption once unlocked; valuable for pressured group healing."] = "神圣天赋解锁后可抵抗施法打断；高压团队治疗中有价值。"
language.strings["Holy's emergency burst-heal tool once unlocked."] = "解锁后可作为神圣天赋的紧急爆发治疗技能。"
language.strings["Holy's regular fast heal; other builds may prefer keeping one effective recovery heal."] = "神圣天赋常用的快速治疗；其他天赋可保留一种有效的恢复技能。"
language.strings["Horde"] = "部落"
language.strings["Hover for the full message. x hides a request."] = "悬停查看完整消息；点击 x 隐藏需求。"
language.strings["How the game names this character:"] = "游戏返回的当前角色姓名："
language.strings["Imported %d %s (%s) with %d items."] = "已导入 %d %s（%s），共 %d 件物品。"
language.strings["Imported list"] = "导入的清单"
language.strings["Inspection information can wait on a leveling budget."] = "升级预算紧张时，可缓学侦查信息技能。"
language.strings["Interrupt dangerous casts; damage-only rank upgrades can wait."] = "用于打断危险施法；仅提高伤害的等级可暂缓。"
language.strings["Interrupt dangerous casts; later damage-only ranks can wait."] = "用于打断危险施法；后续仅提高伤害的等级可暂缓。"
language.strings["Invite"] = "邀请"
language.strings["Ironforge"] = "铁炉堡"
language.strings["Is this your auction house character?\n\nForever Ledger can turn the game's sound off while the flip watch runs and play its chimes at full volume, even with the game in the background. You can change this later in Settings, Auction house, Alerts."] = "这是你的拍卖行角色吗？\n\n套利监控运行时，Forever Ledger 可关闭游戏声音，并以最大音量播放提示音，游戏处于后台时也有效。以后可在“设置 → 拍卖行 → 提醒”中更改。"
language.strings["Is this your own account?\n\nForever Ledger can share your gold, sales and purchases with it, so both Dashboards and Ledgers show the same. These include your buyers' names, so only say yes if it's yours. You can change this later in Settings, Global settings, Advanced."] = "这是你自己的账号吗？\n\nForever Ledger 可向该账号同步金币、出售和购买记录，使两边的总览与账本保持一致。记录包括买家姓名，请仅在确认是自己的账号时同意。以后可在“设置 → 全局设置 → 高级”中更改。"
language.strings["Item level %s green armor"] = "物品等级 %s 的绿色护甲"
language.strings["Item level %s green weapons"] = "物品等级 %s 的绿色武器"
language.strings["Judgement enables your seals regardless of tree."] = "无论选择何种天赋，审判都能触发圣印效果。"
language.strings["Keep a general combo builder and damage finisher useful."] = "保持通用连击点生成技能和伤害终结技适合当前等级。"
language.strings["Keep a heal suitable for your health pool; Holy group healing needs stronger ranks."] = "保留与自身生命值相匹配的治疗技能；神圣团队治疗需要更高等级。"
language.strings["Keep a heal that restores enough health; healing groups calls for stronger ranks."] = "保留足够恢复生命值的治疗技能；经常治疗队伍则需更高等级。"
language.strings["Keep an efficient heal during its useful level range; do not buy obsolete ranks merely to complete the book."] = "在适用等级范围内保留高效治疗；无需为了补齐技能书购买过时等级。"
language.strings["Keep current for dagger combat with rear access; sword or frontal builds can skip upgrades."] = "使用匕首且能从背后攻击时及时升级；剑或正面攻击路线可跳过后续等级。"
language.strings["Keep defensive buffs and your absorb useful at your level."] = "保持防御增益和吸收效果适合当前等级。"
language.strings["Keep early questing damage until the chosen Shadow attacks take over; do not apply a late Shadow skip rule before those attacks are learned."] = "在选定暗影攻击技能接替前保持早期任务输出；尚未学会替代技能时，不要套用后期暗影的跳过规则。"
language.strings["Keep enough healing for solo recovery; regular group healing requires stronger ranks."] = "保留足够的治疗满足单人恢复；经常组队治疗需要更高等级。"
language.strings["Keep enough healing for the pet you use; Lone Wolf builds can defer pet-only upgrades."] = "为常用宠物保留足够治疗量；独狼路线可缓升仅宠物使用的技能。"
language.strings["Keep one armor active. Do not buy obsolete Frost Armor ranks after replacing it with a suitable later armor."] = "保持一种护甲增益。已有合适后续护甲替代时，不必购买过时的霜甲术等级。"
language.strings["Keep one armor active. Frost Armor or Ice Armor remains a useful defensive choice; maintaining every alternative rank is optional."] = "保持一种护甲增益；霜甲术或冰甲术仍是有效防御，不必维持所有替代方案等级。"
language.strings["Keep one armor active; this replaces Frost Armor rather than stacking with it. Use Mage Armor instead when its mana recovery better suits the route."] = "保持一种护甲增益，它会替代霜甲术而非叠加；路线更需要法力恢复时可改用法师护甲。"
language.strings["Keep resource recovery, self healing and shard collection useful."] = "保持资源恢复、自疗和碎片获取能力有效。"
language.strings["Keep this bear attack useful when tanking; caster routes can defer upgrades."] = "坦怪时保持此熊形态攻击有效，施法路线可缓升。"
language.strings["Keep your chosen damage poison effective; short fights often suit Instant Poison, but a poison build may choose another recipe."] = "保持常用伤害毒药有效；短战斗通常适合速效毒药，毒药天赋也可选择其他配方。"
language.strings["Keep your main shadow damage current while used."] = "实际使用主要暗影伤害技能时，应及时升级。"
language.strings["Keep your self buff, drinking and food useful at your level."] = "让自身增益、饮水和食物保持适合当前等级。"
language.strings["Later travel goal; quest and riding requirements belong outside combat rank priorities."] = "后期移动目标；任务和骑术条件不计入战斗技能等级优先级。"
language.strings["Learn a cheap slow for runners or kiting; damage upgrades are optional."] = "学习低成本减速以控制逃跑目标或风筝；伤害升级可选。"
language.strings["Learn an early slow in every tree; upgrade damage ranks when frost is your main attack."] = "各天赋都应尽早学习减速；以冰霜为主要攻击时，再升级伤害等级。"
language.strings["Learn before grouping in any build; its first usable rank already revives allies."] = "任何天赋组队前都应学习；第一个可用等级已能复活队友。"
language.strings["Learn before grouping in any build; solo play has nobody to resurrect."] = "任何天赋在组队前都应学习；纯单人玩法没有复活目标。"
language.strings["Learn before grouping in any tree; pure solo questing has no resurrection target."] = "任何天赋组队前都应学习；纯单人任务没有复活目标。"
language.strings["Learn cooldowns for hard fights and understand their risks and equipment requirements."] = "学习冷却技能应对艰难战斗，并了解其风险和装备要求。"
language.strings["Learn crowd control in every build; upgrade for longer control when your pulls need it."] = "各天赋都应学习控制，需更长控制时间时再升级。"
language.strings["Learn for harmful diseases; ordinary routes without them can defer it."] = "遭遇有害疾病时学习；没有相关敌人的路线可暂缓。"
language.strings["Learn slowing for kiting or runners; later damage ranks are optional."] = "学习减速以风筝或控制逃跑目标；后续伤害等级可选。"
language.strings["Learn the early interrupt; later damage ranks do not improve its basic interrupt job."] = "早期学习打断；后续伤害等级不会强化基础打断功能。"
language.strings["Learn the form for travel, escape or emergency durability regardless of tree."] = "任何天赋都可为赶路、逃脱或应急生存学习该形态。"
language.strings["Learn the gem you expect to use. New gem tiers need not be bought solely to maintain every older option."] = "学习预计会使用的法力宝石，不必仅为凑齐旧选项购买每种新阶级。"
language.strings["Learn the interrupt; buy damage ranks when shocks are part of your regular rotation."] = "先学会打断；震击属于常规循环时再购买伤害等级。"
language.strings["Learn the root in every build; later damage ranks do not improve its basic control job."] = "各路线都应学习定身，后续伤害等级不会增强其基础控制作用。"
language.strings["Learned at level 20 in Forever since October 15 (22 in Classic)."] = "10月15日起，无限服20级可学，经典版为22级。"
language.strings["Ledger debug:"] = "账本调试："
language.strings["Legacy name only: reconcile with Forever trainer data before showing advice."] = "仅为旧版名称；展示建议前需核对无限服训练师数据。"
language.strings["Less threat for a group damage dealer, without using a Blessing slot; skip it solo and never put it on the tank."] = "为组队输出降低仇恨，且不占用祝福位置；单人无需使用，也不要施加给坦克。"
language.strings["Leveling help is switched off: Settings, Global settings, Modules."] = "升级辅助已关闭：设置 → 全局设置 → 模块。"
language.strings["Local"] = "本地"
language.strings["Loch Modan"] = "洛克莫丹"
language.strings["Loch Modan and Westfall, then Redridge"] = "洛克莫丹和西部荒野，之后前往赤脊山"
language.strings["Lockpicking"] = "开锁"
language.strings["Longer group buff convenience; the ordinary blessing is enough while leveling."] = "持续时间更长的团队增益，使用更方便；升级途中普通祝福已足够。"
language.strings["Mage portal"] = "法师传送门"
language.strings["Make a Lesser Magic Wand (later a Greater) for a caster who wants one. Vendors pay only a little for them (Lesser 1s 10c, Greater 2s since the October 8 patch), so sell to players; the vendor price is just a floor."] = "制作次级魔法杖（后期制作强效魔法杖），卖给有需要的法系玩家。商店收购价很低（10 月 8 日更新后，次级为 1 银 10 铜，强效为 2 银），建议卖给玩家；商店收购价仅作最低参考。"
language.strings["Make current if a dagger and positioning make this your main attack; a sword Combat route can skip it."] = "使用匕首且能满足站位要求、以此作为主要攻击时，应及时升级；战斗剑路线可跳过。"
language.strings["Make current if dagger openers are part of your route; other weapon routes can skip it."] = "路线使用匕首起手时及时升级；其他武器路线可跳过。"
language.strings["Mana pressure is mainly a player-combat tool, not a routine quest kill plan."] = "消耗敌方法力主要用于玩家对战，常规任务击杀通常不需要。"
language.strings["Mana pressure seldom solves ordinary quest pulls; reconsider for player combat."] = "普通任务引怪很少需要消耗敌方法力，对战玩家时再考虑。"
language.strings["Map: %s (map %s) at %s, %s. Map pins: %s, pin tracking: %s."] = "地图：%s（地图 %s），坐标 %s、%s。地图标记：%s，标记追踪：%s。"
language.strings["Marksmanship and physical groups value the buff; upgrade when unlocked and used."] = "射击和物理队伍重视此增益，解锁并实际使用后升级。"
language.strings["Marksmanship uses ranged burst; Forever shares its cooldown with Aimed Shot, so choose by pull."] = "射击使用远程爆发；无限服中它与瞄准射击共享冷却，需按引怪方式选择。"
language.strings["Master"] = "大师"
language.strings["Melee groups benefit; solo casters can defer a totem they seldom use."] = "近战队伍可受益；单人法系可暂缓升级很少使用的图腾。"
language.strings["Minimap detection can wait while gold is needed for combat tools."] = "金币需优先用于战斗技能时，小地图侦测可暂缓学习。"
language.strings["Movement and emergency control matter in every tree."] = "移动与应急控制对所有天赋都有价值。"
language.strings["Mulgore"] = "莫高雷"
language.strings["Narrow pull avoidance can wait on a tight training budget."] = "仅用于少数绕怪场景，金币紧张时可缓学。"
language.strings["Narrow ranged physical protection; routine leveling can skip."] = "针对远程物理伤害的特定防护；常规升级可跳过。"
language.strings["Narrow reactive caster pressure can wait during ordinary questing."] = "针对施法者的特定反制技能，普通任务升级可暂缓。"
language.strings["Nature resistance is encounter-specific; buy for a known need."] = "自然抗性针对特定战斗，明确需要时再学。"
language.strings["New level 24 spell on October 15; it can also trigger Missile Barrage (October 16 hotfix)."] = "10月15日新增的24级法术，也能触发飞弹速射（10月16日热修）。"
language.strings["New on October 15, with Salvation and Mass Salvation."] = "10 月 15 日新增，与拯救及群体拯救同时加入。"
language.strings["Niche humanoid control or dungeon tricks; normal solo fights do not require it."] = "特定人形控制或地下城技巧；普通单人战斗并不需要。"
language.strings["No Waylaid Crates or Writs in your bags. Put one in your bags and probe again."] = "背包中没有相应补给箱或凭证。放入一个后重新探测。"
language.strings["No items shown: choose filters and scan first."] = "未显示物品：请先选择过滤条件并扫描。"
language.strings["No jobs yet. Trades where you enchant something, get paid, or trade with someone from Requests are logged here."] = "暂无服务记录。附魔、收款或与需求列表中的玩家交易后，会记录在此。"
language.strings["No purchases found for this shuffle."] = "此加工套利方案没有需要购买的物品。"
language.strings["No recipe known for this item."] = "尚未掌握此物品的配方。"
language.strings["No requests in the last hour. They appear here as soon as someone asks for what you do."] = "最近一小时没有需求。有人寻求你的角色能提供的服务时，会显示在此。"
language.strings["No sell speed checks yet: they appear after two full scans."] = "暂无销售速度分析；完成两次完整扫描后显示。"
language.strings["No window, sound or chat line for new requests, for as long as you pick. They're still listed here."] = "在所选时间内，新需求不弹窗、不播放声音、不发送聊天提醒，但仍列在此处。"
language.strings["Not paired. Use /fl pair Charactername on both characters."] = "尚未配对。请在两个角色上分别输入 /fl pair Charactername（目标角色名）。"
language.strings["Nothing on that list to look up."] = "此清单中没有可查询的物品。"
language.strings["Nothing to import: paste a shared list (it starts with \"%s\"), or item names, one per line."] = "没有可导入的内容：请粘贴共享清单（以“%s”开头），或逐行填写物品名称。"
language.strings["Nothing under the mouse."] = "鼠标下没有内容。"
language.strings["Observed Forever Frost upgrades; prioritise if it is part of your frozen-target rotation."] = "已观察到无限服冰霜升级；属于冻结目标输出循环时优先。"
language.strings["Observed Forever upgrades; prioritise only when your build actually uses this hybrid nuke."] = "已观察到无限服升级；仅在实际使用这种混合直接伤害法术时优先。"
language.strings["Off"] = "关闭"
language.strings["Offer lockpicking"] = "提供开锁"
language.strings["Offer summons"] = "提供召唤"
language.strings["Official Forever Beast Mastery attack; shares Arcane Shot's cooldown, so choose the attack you use."] = "官方无限服野兽控制攻击，与奥术射击共享冷却，选择实际使用的一种。"
language.strings["Official Forever Protection defence; prioritise only after the talent unlock."] = "时光服官方防护防御技能；解锁天赋后再优先考虑。"
language.strings["Official Forever talent supports the tank taunt; the original Retribution label was misleading."] = "时光服官方天赋支持坦克嘲讽；原来的惩戒分类具有误导性。"
language.strings["On the auction house: |cffffd100%s|r %s"] = "拍卖行：|cffffd100%s|r %s"
language.strings["On: recipes you right-clicked keep the type you gave them. Off: every recipe uses the automatic type (your choices are kept for later)."] = "开启：保留右键指定的配方分类。关闭：所有配方使用自动分类（保留手动选择，供以后恢复）。"
language.strings["One Classic leveling guide names rank 3 at level 36 as its efficiency breakpoint versus Smite. Other guides use earlier Shadow; treat 36 as route-specific, and recheck Forever damage, Mana and wand gear."] = "一份经典旧世指南将 36 级的 3 级技能列为效率超过惩击的节点。其他指南更早转暗影；36 级仅适用于特定路线，还需复核时光服的伤害、法力和魔杖装备。"
language.strings["One-off deals (fewer than %d listed):"] = "零散机会（在售不足 %d 件）："
language.strings["Only %d %s of your own scans."] = "仅有你自行扫描的 %d %s数据。"
language.strings["Only buy for a planned magic-damage situation; it can also weaken incoming heals."] = "仅针对计划中的魔法伤害场景购买，它也可能削弱受到的治疗。"
language.strings["Only for a deliberate sacrifice build; ordinary leveling with a tanking pet should keep that pet."] = "仅适用于明确采用牺牲的天赋；普通宠物坦怪升级应保留宠物。"
language.strings["Only my professions"] = "仅我的专业"
language.strings["Only needed for traps you plan to tackle; ordinary quest combat can skip."] = "仅在计划处理陷阱时需要；普通任务战斗可跳过。"
language.strings["Only prioritise repeated ranks for planned pack damage."] = "仅在计划进行群怪输出时优先购买后续等级。"
language.strings["Only the %s can get this recipe. For you, the way is the neutral auction house (Booty Bay, Gadgetzan, Everlook)."] = "仅%s可直接获取此配方。你可以通过中立拍卖行获取（藏宝海湾、加基森、永望镇）。"
language.strings["Only while you use it, and you haven't cast it in the last week."] = "仅在实际使用时升级；你最近一周未施放此技能。"
language.strings["Only worth repeated upgrades for group or planned ranged AoE."] = "仅经常组队或有计划地远程群攻时，才值得持续升级。"
language.strings["Open a trainer first (class or riding); then /fl trainer lists what it teaches."] = "先打开职业或骑术训练师，再输入 /fl trainer 列出其教授的技能。"
language.strings["Optional Affliction curse support; not necessary for every short leveling fight."] = "可选痛苦诅咒辅助；并非每场短时间升级战斗都需要。"
language.strings["Optional Affliction kiting control; useful when that is your chosen method."] = "可选痛苦风筝控制；采用该打法时有用。"
language.strings["Optional Destruction finisher; repeated upgrades depend on regular use."] = "可选毁灭终结技；后续升级取决于使用频率。"
language.strings["Optional Fury pack slowing; learn when the chosen build and pulls use it."] = "可选狂暴群体减速；当前天赋和战斗需要时学习。"
language.strings["Optional Mana recovery for long fights; prioritise your actual seal and healing needs."] = "长时间战斗中可选择的法力恢复手段；优先满足常用圣印和治疗需求。"
language.strings["Optional Shadow interrupt once unlocked; buy for caster-heavy pulls or PvP."] = "解锁后可选的暗影打断；施法者较多的战斗或 PvP 值得学习。"
language.strings["Optional Subtlety attack or defence; buy only if unlocked and used."] = "可选敏锐攻击或防御技能；已解锁并实际使用时再购买。"
language.strings["Optional Survival control attack; prioritise when it fits your melee play."] = "可选生存控制攻击，适合你的近战玩法时优先。"
language.strings["Optional bleed opener; short fights or a different opener reduce its value."] = "可选流血起手；战斗过短或采用其他起手技能时价值较低。"
language.strings["Optional cat stealth burst; ordinary Claw combat does not require every rank."] = "可选的猫形态潜行爆发；普通爪击战斗不必每级都学。"
language.strings["Optional control against runners or dangerous targets; damage seals come first."] = "可选的控制技能，用于逃跑或危险目标；优先升级输出圣印。"
language.strings["Optional escape or distraction; upgrade if it reliably supports your pulls."] = "可选逃脱或分散注意力的技能；能稳定改善当前战斗时再升级。"
language.strings["Optional fast Fire damage or threat tool; routine pet or drain play can skip."] = "可选快速火焰伤害或仇恨技能；常规宠物或吸取打法可跳过。"
language.strings["Optional group healing if Forever offers it; the removed talent does not establish trainer access."] = "若时光服提供，可作为可选团队治疗；天赋被移除并不能证明训练师可教。"
language.strings["Optional hit reduction for dangerous melee targets; skip when damage is the better spend."] = "降低危险近战目标命中的可选技能；优先提升伤害时可跳过。"
language.strings["Optional income while using stealth; combat spells come first."] = "潜行时可选择的额外收入手段；战斗技能优先。"
language.strings["Optional longer Fire or group fights; short solo fights usually favor a damage bane."] = "可用于较长的火焰或团队战斗；短时间单人战斗通常更适合伤害灾祸。"
language.strings["Optional opener support; confirm Forever talent access before treating it as a trainer buy."] = "可选的起手辅助；列为训练师购买项前，先确认时光服天赋的获取方式。"
language.strings["Optional pack Rage spending; upgrade for regular multi-target fights rather than short solo kills."] = "可选群怪怒气消耗技能；经常进行多目标战斗时升级，短时间单人战斗可暂缓。"
language.strings["Optional pack burst; since October 15 it hits softer but costs much less mana, so upgrade it if you use it on packs."] = "可选群怪爆发；10 月 15 日后伤害降低，但法力消耗大幅减少，实际用于群怪时值得升级。"
language.strings["Optional party weapon support; prioritise the totem your actual party uses."] = "可选的队伍武器辅助；优先升级队伍实际使用的图腾。"
language.strings["Optional physical defence; core attacks and recovery come first."] = "可选物理防御；核心攻击和恢复技能优先。"
language.strings["Optional racial attack; prioritise your main damage spells unless you use it regularly."] = "可选种族攻击；除非经常使用，否则优先升级主要输出法术。"
language.strings["Optional racial control; verify race and Forever service before buying."] = "可选的种族控制技能；购买前确认种族及其在时光服的训练方式。"
language.strings["Optional racial damage while taking hits; upgrade if that fits your pulls."] = "受击时触发的可选种族伤害；符合当前战斗方式时再升级。"
language.strings["Optional racial defence or damage; only buy upgrades you use."] = "可选种族防御或伤害技能；只升级实际使用的等级。"
language.strings["Optional ranged burst costs Mana; do not upgrade an attack you rarely use."] = "可选远程爆发会消耗法力，不常用则无需升级。"
language.strings["Optional sustain for long fights; do not upgrade a seal you do not use."] = "长时间战斗中可提供续航；不要升级不使用的圣印。"
language.strings["Orgrimmar"] = "奥格瑞玛"
language.strings["Pack slowing helps trap or melee play; ranged single-target questing can defer it."] = "群体减速有助于陷阱和近战玩法，远程单体任务可缓学。"
language.strings["Pair first with /fl pair Charactername."] = "请先输入 /fl pair Charactername 配对（填写目标角色名）。"
language.strings["Paired with %s, %s. %d messages waiting to send."] = "已与%s配对，%s。%d 条消息等待发送。"
language.strings["Paired with %s. Do /fl pair %s on that character too. Syncing starts when both are online."] = "已与%s配对。请在对方角色上也输入 /fl pair %s。两个角色同时在线后开始同步。"
language.strings["Passive defence helps every build through repeated melee fights."] = "被动防御有助于所有天赋应对反复近战。"
language.strings["Passive defence helps repeated melee fights in every build."] = "被动防御有助于所有天赋应对反复近战。"
language.strings["Paused the flip watch's checks for Search all."] = "为执行全部搜索，已暂停套利监控检查。"
language.strings["Pet control helps Beast Mastery survive dangerous pulls once unlocked."] = "野兽控制解锁后，宠物控制有助于应对危险引怪。"
language.strings["Pet ownership and upkeep are central tools for every tree."] = "驯养与维护宠物是各种天赋的重要工具。"
language.strings["Pet scouting is a special-purpose tool; routine pet combat works without it."] = "宠物侦查用途较专，普通宠物战斗并不依赖。"
language.strings["Petless Lone Wolf routes can defer pet tools; pet routes need effective healing."] = "无宠独狼路线可缓学宠物工具；带宠路线需要有效的宠物治疗。"
language.strings["Physical melee play benefits; buy in any tree when supporting melee groups."] = "物理近战可受益；任何天赋支援近战队伍时均可购买。"
language.strings["Physical protection improves solo durability for all trees."] = "物理防护可提高所有天赋的单人生存能力。"
language.strings["Physical protection suits contact-heavy pulls; only one armor buff can be active."] = "经常近身引怪适合物理防护，同一时间只能维持一种护甲增益。"
language.strings["Physical questing values attack power; caster or healing routes choose another blessing."] = "物理系任务升级看重攻击强度；法术输出或治疗路线可选择其他祝福。"
language.strings["Posted to"] = "已发布到"
language.strings["Price helper error: "] = "价格助手错误："
language.strings["Price helper on %s: PriceInput %s, SetAmount %s."] = "%s的价格助手：PriceInput %s，SetAmount %s。"
language.strings["Price helper: "] = "价格助手："
language.strings["Price helper: no SetAmount on the price box"] = "价格助手：价格输入框没有 SetAmount 方法"
language.strings["Price helper: sell page showing: "] = "价格助手：当前出售页面："
language.strings["Prioritise Arcane burst when the talent is unlocked; it is not ordinary first-rank training."] = "天赋解锁后优先考虑奥术爆发，不属于普通基础技能学习。"
language.strings["Prioritise for a Fury two-weapon route; two-handed builds can defer it."] = "狂暴双持路线优先学习；双手武器路线可暂缓。"
language.strings["Prioritise when your Assassination build unlocks and uses its burst."] = "刺杀天赋已解锁且使用此爆发技能时优先升级。"
language.strings["Priority for Blizzard AoE grinding; single-target Frost can defer it. Check Forever talents before copying Classic AoE pulls."] = "暴风雪群怪升级优先，单体冰霜可缓学。照搬经典版群拉方式前，应检查无限服天赋。"
language.strings["Priority when regularly clearing packs this way; a single-target route can defer ranks."] = "经常如此清理怪群时优先，单体路线可缓升。"
language.strings["Probe: this vendor (%s) sells for currencies:"] = "探测：此商人（%s）接受以下货币："
language.strings["Probe: trade %s with %s."] = "探测：交易 %s，对方 %s。"
language.strings["Probe: what the game gives us for crafting ads, trades, Merchant's Favor, crates and the recipe book."] = "探测：记录游戏提供的制作广告、交易、商人的恩惠、箱子与配方书数据。"
language.strings["Profession link now: %s"] = "当前专业链接：%s"
language.strings["Protection's primary shield attack once unlocked; prioritise for tanking."] = "防护解锁后的主要盾牌攻击；承担坦克时优先升级。"
language.strings["Provisional Forever Assassination builder; confirm unlock, then keep current if it replaces Sinister Strike."] = "暂定为时光服刺杀连击点生成技能；确认解锁后，若取代影袭则应及时升级。"
language.strings["Provisional Forever cleave option; confirm the unlock and use before buying upgrades."] = "暂定为时光服顺劈可选技能；购买后续等级前先确认解锁和用途。"
language.strings["Provisional Forever group heal for Restoration; confirm its unlock and trainer first."] = "可能属于无限服恢复群体治疗，先核实解锁方式与训练师。"
language.strings["Provisional Forever melee option; verify the unlock and intended weapons first."] = "暂定为时光服近战可选技能；先核实解锁条件和适用武器。"
language.strings["Provisional Forever utility; confirm what the service grants rather than invent combat value."] = "暂定为无限服便利技能，应核实服务内容，不凭空估计战斗价值。"
language.strings["Provisional Gnome control tool; learn when its racial service is confirmed."] = "暂定为侏儒控制技能；确认可通过种族训练服务学习后再获取。"
language.strings["Provisional Gnome recovery tool; learn when its racial service is confirmed."] = "暂定为侏儒恢复技能；确认可通过种族训练服务学习后再获取。"
language.strings["Provisional Protection attack; only prioritise after its Forever unlock is confirmed."] = "暂定为防护攻击技能；确认其在时光服的解锁条件后再优先学习。"
language.strings["Provisional Restoration recovery; confirm Forever availability, then prioritise if used."] = "暂定为恢复续航技能；确认时光服可获取后，实际使用时优先学习。"
language.strings["Provisional racial emergency tool; confirm its service and race first."] = "暂定为种族紧急技能；先确认训练方式与适用种族。"
language.strings["Provisional scroll utility; verify the Forever service before deciding it is worth buying."] = "暂定为卷轴便利功能，判断是否值得购买前，先核实无限服实际服务。"
language.strings["Provisional totem convenience; verify Forever access before spending."] = "暂定为图腾便利技能；付费前确认时光服的获取方式。"
language.strings["Quick pet recovery is especially valuable for Demonology; only buy after its unlock."] = "快速恢复宠物对恶魔学识尤其有价值；解锁后再购买。"
language.strings["Quiet mode off: your sound settings are back."] = "安静模式已关闭，已恢复你的声音设置。"
language.strings["Quiet mode on for this character: game sound off, Forever Ledger's chimes at full volume. It stays on after a reload or logout; /fl quiet turns it off."] = "已为此角色开启安静模式：关闭游戏声音，Forever Ledger 提示音保持最大音量。重载或退出后仍保留；输入 /fl quiet 关闭。"
language.strings["Quiet mode will come on while the flip watch runs."] = "套利监控运行时将开启安静模式。"
language.strings["Ranged builds use its sustained damage; Survival's choice depends on melee talents and Mana."] = "远程路线使用其持续伤害，生存则需结合近战天赋和法力决定。"
language.strings["Ranged builds want attack power; melee Survival usually values its melee aspect."] = "远程路线需要攻击强度；近战生存通常更重视近战守护。"
language.strings["Ranged burst speeds tough fights; mostly-melee Survival gets less from it."] = "远程爆发可加快困难战斗，以近战为主的生存受益较少。"
language.strings["Ratchet, Barrens oases, Silverpine"] = "棘齿城、贫瘠之地的绿洲、银松森林"
language.strings["Razormane camps in Durotar, then the pirates south of Ratchet"] = "杜隆塔尔的钢鬃营地，之后是棘齿城以南的海盗"
language.strings["Recall prevents abandoned totems; a preset eases routine deployment."] = "回收可避免遗留图腾；预设方便日常放置。"
language.strings["Recipe book so far:"] = "当前配方书："
language.strings["Recipe book:"] = "配方书："
language.strings["Recipe book: recipe drop"] = "配方书：配方掉落"
language.strings["Recipes in %s: %d learned, %d not learned, %d of those have source text. GetRecipeSourceText: %s."] = "%s配方：已学 %d 个，未学 %d 个，其中 %d 个有来源说明。GetRecipeSourceText：%s。"
language.strings["Recipes: open a profession window and probe again."] = "配方：请打开专业窗口后重新探测。"
language.strings["Redridge Mountains"] = "赤脊山"
language.strings["Reflective damage suits tank or pack pulls; single-target routes may prefer another aura."] = "反伤适合坦克或群怪战斗；单体路线可选择其他光环。"
language.strings["Regeneration helps caster kiting; choose it instead of physical armor when that fits your pulls."] = "恢复有助于施法风筝，适合这种引怪方式时可替代物理护甲。"
language.strings["Regular casting and healing value Mana recovery; melee routes may prefer Might."] = "频繁施法和治疗需要法力恢复；近战路线可能更适合力量祝福。"
language.strings["Regular healing merits upgrades; damage builds can keep a usable recovery rank."] = "经常治疗值得升级；伤害路线可保留够用的恢复等级。"
language.strings["Remote scouting is optional and does not improve routine fights."] = "远程侦查属于可选功能，不能改善常规战斗。"
language.strings["Remove dangerous friendly debuffs or enemy buffs; broadly useful even for damage builds."] = "移除友方危险减益或敌方增益；输出天赋也广泛适用。"
language.strings["Remove harmful effects without needing to be the party healer."] = "无需担任队伍治疗，也能移除有害效果。"
language.strings["Replaced Blessing of Salvation on October 15; it no longer takes a Blessing slot."] = "10 月 15 日替代了拯救祝福；不再占用祝福位置。"
language.strings["Replaced Greater Blessing of Salvation on October 15; it no longer takes a Blessing slot."] = "10 月 15 日替代了强效拯救祝福；不再占用祝福位置。"
language.strings["Requests"] = "需求"
language.strings["Reset Frost safety and control tools once unlocked; useful for difficult pulls."] = "解锁后可重置冰霜生存和控制技能，困难引怪时有用。"
language.strings["Resistance for a known shadow encounter; routine leveling can skip."] = "用于已知暗影伤害战斗的抗性；常规升级可跳过。"
language.strings["Resistance for a specific fire encounter; not routine leveling."] = "针对特定火焰伤害战斗的抗性技能；常规升级无需优先学习。"
language.strings["Resistance for a specific frost encounter; not routine leveling."] = "针对特定冰霜伤害战斗的抗性技能；常规升级无需优先学习。"
language.strings["Resistance for a specific shadow encounter; not routine leveling."] = "针对特定暗影伤害战斗的抗性技能；常规升级无需优先学习。"
language.strings["Restoration groups value recovery; questing builds upgrade if they stay near it long enough."] = "恢复队伍看重续航；任务路线在附近停留足够久时才值得升级。"
language.strings["Restoration needs a fast emergency heal; damage builds may prefer a cheaper recovery heal."] = "恢复需要快速紧急治疗；输出天赋可选择较便宜的恢复技能。"
language.strings["Restoration needs a quick heal; cheaper Forever Regrowth also helps other builds recover."] = "恢复需要快速治疗；无限服低耗愈合也有助于其他天赋恢复。"
language.strings["Restoration's instant emergency cast once unlocked."] = "恢复解锁后的瞬发紧急施法技能。"
language.strings["Restoration's instant recovery matters in healing; only upgrade if unlocked and used."] = "恢复的瞬间恢复技能适合治疗，解锁且实际使用后再升级。"
language.strings["Reveal stealth for PvP or a specific enemy; routine Normal questing can skip."] = "对战玩家或特定敌人时可侦测潜行，普通任务可跳过。"
language.strings["Riding fund shown on this character's Dashboard again."] = "已在当前角色的总览中重新显示骑术储备金。"
language.strings["Rogue lockpicking: bring your lockboxes, tips welcome. Whisper me!"] = "潜行者开锁：请带上你的锁箱，欢迎小费。需要请私聊！"
language.strings["Routine leveling usually values a damage curse more; revisit dangerous physical encounters."] = "常规升级通常更看重伤害诅咒；危险物理战斗再考虑。"
language.strings["Salvation for the whole group at once; a raid convenience, the single one does for dungeons."] = "一次为全团施加拯救效果，方便团队副本使用；地下城中单体版本已足够。"
language.strings["Save"] = "保存"
language.strings["Say"] = "说"
language.strings["Scouting and hidden-target detection can wait unless a quest or player combat needs them."] = "除非任务或玩家对战需要，否则侦察与隐藏目标侦测可暂缓。"
language.strings["Scouting conveniences can wait on a combat training budget."] = "战斗训练预算紧张时，可暂缓学习侦察便利技能。"
language.strings["Search all stopped: the auction house closed."] = "全部搜索已停止：拍卖行已关闭。"
