language.strings["Sell"] = "出售"
language.strings["Sell food and water"] = "出售食物和饮水"
language.strings["Sell on the auction house, after %g%% cut"] = "在拍卖行出售，扣除 %g%% 手续费后"
language.strings["Sell portals"] = "出售传送门"
language.strings["Sell protection on %s: PostButton %s, GetItem %s, price from %s."] = "已为%s启用上架保护：上架按钮%s，GetItem %s，价格来自%s。"
language.strings["Sell protection: Post anyway for"] = "上架保护：仍然上架，物品"
language.strings["Sell speed: compared with the full scan %d minutes ago. Bought (or cancelled) for sure: %d units; reposted cheaper: %d; might have expired, not counted: %d."] = "销售速度：与 %d 分钟前的完整扫描比较。确定已被购买或撤拍：%d 件；降价重新上架：%d 件；可能到期，未计入：%d 件。"
language.strings["Sell speed: nothing to compare with yet (%s). This scan is saved for next time."] = "销售速度：暂无可比较的扫描（%s）。此次扫描已保存，供下次比较。"
language.strings["SendChatMessage: %s. C_TradeSkillUI.GetTradeSkillListLink: %s."] = "SendChatMessage：%s。C_TradeSkillUI.GetTradeSkillListLink：%s。"
language.strings["Sending everything to "] = "正在发送全部数据给 "
language.strings["Server channels: %s"] = "服务器频道：%s"
language.strings["Set by you. This price is never changed automatically. Automatic: %s. Right-click Up to to use the automatic price."] = "由你设定，不会自动修改。自动价格为%s。右键点击价格上限可恢复自动定价。"
language.strings["Shadow damage stance; learn when unlocked. Forever allows non-healing spells within it."] = "暗影输出形态；解锁后学习。时光服允许在此形态中使用非治疗法术。"
language.strings["Sharing gold, sales, bags and bank is off too. Your next link starts fresh."] = "金币、销售、背包和银行共享也已关闭。下次关联将重新开始。"
language.strings["Shield-based tank damage and defence suit Protection; talent acquisition still gates it."] = "依赖盾牌的坦克伤害和防御适合防护天赋；仍需先获得对应天赋。"
language.strings["Shopping lists are one kind now: tick Buy from this list in the Buy queue to buy from one. Want is how many to buy; Have shows what you own. What you already had counts as bought, so nothing extra gets bought."] = "购物清单现已统一：在购买队列中勾选“按此清单购买”即可使用。“需求”为目标数量，“已有”为持有数量。已有数量会计入已购数量，避免重复购买。"
language.strings["Short solo targets often die before armor reduction pays back; revisit for sustained group fights."] = "短时间单人战斗中，目标可能在破甲发挥作用前就已死亡；长时间团队战斗再考虑。"
language.strings["Silence customer alerts"] = "静音客户提醒"
language.strings["Silenced"] = "已静音"
language.strings["Silithus"] = "希利苏斯"
language.strings["Silverpine Forest"] = "银松森林"
language.strings["Since October 8 a rank far below your level gets much less from your spell power, so an old low rank heals little: keep the rank you heal with current. Classic's rank 1 small-heal habit no longer pays in Forever."] = "10月8日起，远低于人物等级的技能从法术强度中获得的收益大幅减少，低等级治疗恢复很少，应及时升级常用治疗。经典版常用1级小治疗的习惯不再适合无限服。"
language.strings["Situational control and traversal can avoid dangerous fights."] = "情境控制与移动工具，可用于避开危险战斗。"
language.strings["Situational undead or demon packs; Forever Retribution talents can improve it."] = "适用于成群亡灵或恶魔；时光服惩戒天赋可以强化此技能。"
language.strings["Situational weakening against dangerous enemies; not every ordinary pull needs it."] = "用于削弱危险敌人的情境技能；普通战斗无需每次使用。"
language.strings["Slowing runners or kiting is useful in all builds; damage poisons still suit ordinary kills."] = "减速逃跑目标或风筝适合所有天赋；普通击杀仍可使用伤害毒药。"
language.strings["Special demon rituals can wait until their group or endgame use matters."] = "特殊恶魔仪式可等到有团队或满级用途时再学习。"
language.strings["Special enrage removal; acquire when your group or route needs it."] = "用于特定激怒效果，队伍或路线需要时获取。"
language.strings["Special trap routes or PvP; ordinary quest combat can skip."] = "特定陷阱路线或 PvP 使用；普通任务战斗可跳过。"
language.strings["Special-purpose demon control; buy only when you plan to use it."] = "特定用途的恶魔控制；计划使用时再购买。"
language.strings["Spells cast saved"] = "已保存施法记录"
language.strings["Spend excess Rage, not every swing; damage ranks are secondary to your main attacks."] = "用于消耗多余怒气，无需每次挥击都使用；伤害升级次于主要攻击。"
language.strings["Split into Lesser Astral Essence"] = "分解为次级星界精华"
language.strings["Split into Lesser Eternal Essence"] = "分解为次级不灭精华"
language.strings["Split into Lesser Magic Essence"] = "分解为次级魔法精华"
language.strings["Split into Lesser Mystic Essence"] = "分解为次级秘法精华"
language.strings["Split into Lesser Nether Essence"] = "分解为次级虚空精华"
language.strings["Stances and transitions support movement, interruption and defence in every tree."] = "姿态及切换有助于所有天赋的移动、打断和防御。"
language.strings["Stonetalon Mountains"] = "石爪山脉"
language.strings["Stormwind"] = "暴风城"
language.strings["Stormwind City"] = "暴风城"
language.strings["Stranglethorn Vale"] = "荆棘谷"
language.strings["Strong Arms response to dodges; other builds buy upgrades according to use."] = "武器应对闪避的强力攻击；其他天赋按实际使用情况升级。"
language.strings["Strong Restoration recovery once unlocked; only upgrade the active build's tool."] = "恢复解锁后的强力续航；仅升级当前天赋实际使用的技能。"
language.strings["Strong but self-damaging group AoE; only prioritise for that leveling method."] = "强力但会伤害自身的团队范围攻击；仅在采用此升级方式时优先学习。"
language.strings["Strong melee group support; learn in any tree before supporting those groups."] = "强力近战队伍辅助；任何天赋支援此类队伍前都应学习。"
language.strings["Survival's melee defence matters once unlocked; ranged builds may also value the safety."] = "解锁后的生存近战防御很重要，远程路线也可能受益于额外安全性。"
language.strings["Swamp of Sorrows"] = "悲伤沼泽"
language.strings["Sync ping: \"%s\" %s."] = "同步连通性：“%s”%s。"
language.strings["Sync ping: neither form reached %s. Check they're online and the name is spelled exactly."] = "同步连通性：两种姓名格式均未能联系到%s。请确认对方在线且姓名完全正确。"
language.strings["Sync ping: sending one hidden message to %s, in two forms, 3 seconds apart."] = "同步连通性：向%s发送隐藏消息，尝试两种姓名格式，间隔 3 秒。"
language.strings["Sync ping: whispers to \"%s\" work. Sync will use that form."] = "同步连通性：发往“%s”的私聊正常，将使用此姓名格式同步。"
language.strings["Sync test passed: %d characters, %d prices and %d vendor prices came back intact in %d messages, %.0f seconds."] = "同步测试通过：%d 个角色、%d 条价格和 %d 条商店价格已通过 %d 条消息完整回传，耗时 %.0f 秒。"
language.strings["Sync test stopped: the game says there's no player named %s, so addon whispers to %s don't arrive."] = "同步测试已停止：游戏提示不存在名为 %s 的玩家，因此发往 %s 的插件私聊无法送达。"
language.strings["Sync test: sending %d characters, %d prices and %d vendor prices to yourself in %d messages. This takes about %d seconds."] = "同步测试：将 %d 个角色、%d 条价格和 %d 条商店价格通过 %d 条消息发送给自己，预计 %d 秒。"
language.strings["Sync turned off."] = "同步已关闭。"
language.strings["Sync turned off. Removed %d %s from %s; the auction prices stay."] = "同步已关闭。已移除 %d %s，来源%s；拍卖价格会保留。"
language.strings["Sync: %s went offline."] = "同步：%s已离线。"
language.strings["Sync: connected to %s."] = "同步：已连接%s。"
language.strings["Sync: filled in %d %s of price history from %s."] = "同步：已补充 %d %s的价格历史，来源%s。"
language.strings["Syndicate camps and farms in Hillsbrad"] = "希尔斯布莱德的辛迪加营地和农场"
language.strings["Tab art"] = "标签页图像"
language.strings["Take the class mount route; confirm acquisition and riding requirements."] = "按职业坐骑路线获取；先确认获取和骑术条件。"
language.strings["Take the class mount route; confirm riding and acquisition requirements."] = "按职业坐骑路线获取；先确认骑术和获取条件。"
language.strings["Takes Salvation back off a party or raid member, such as a tank who got it by mistake."] = "移除队伍或团队成员身上的拯救效果，例如误加给坦克时。"
language.strings["Tanaris"] = "塔纳利斯"
language.strings["Tanks want physical damage reduction; solo damage routes can defer surplus ranks."] = "坦克需要降低物理伤害；单人输出路线可暂缓多余等级。"
language.strings["That ad is too long for chat (255 letters). Right-click the button to shorten it."] = "广告超过聊天的255字限制。右键点击按钮可缩短文字。"
language.strings["That list was removed. Choose another one."] = "该清单已移除，请选择其他清单。"
language.strings["That would alert: "] = "这条消息会触发提醒："
language.strings["That wouldn't alert (not a request for something this character does)."] = "这条消息不会触发提醒（并非寻求此角色可提供的服务）。"
language.strings["That's this character: link a character on your other account."] = "这是当前角色；请关联另一个账号上的角色。"
language.strings["The 21-point Elemental talent since October 15, so Elemental gets it by level 30; once you have it, buy each new rank."] = "10 月 15 日后为元素的 21 点天赋，元素可在 30 级获得；获得后应购买每个新等级。"
language.strings["The Barrens"] = "贫瘠之地"
language.strings["The Barrens and Silverpine, then Ashenvale"] = "贫瘠之地和银松森林，之后前往灰谷"
language.strings["The Hinterlands"] = "辛特兰"
language.strings["The alternative to Succubus for damage-pet play; you do not need both acquisitions."] = "输出宠物玩法中魅魔的替代选择；无需两者都获取。"
language.strings["The first soulstone supplies wipe insurance; upgrade for recovery size when useful."] = "第一个灵魂石已能应对灭团；需要提高恢复量时再升级。"
language.strings["The first usable rank already revives a group member; later recovery-size upgrades are optional on a tight budget."] = "第一个可用等级已能复活队友；预算紧张时，后续提高恢复量的等级可选学。"
language.strings["The first usable rank supplies shards; damage ranks can wait unless you deliberately channel it."] = "第一个可用等级已能获取碎片；除非有意持续引导输出，否则伤害等级可暂缓。"
language.strings["The first usable rank supplies the interrupt; higher ranks are worthwhile for regular shock damage, not for the interrupt alone. Verify Forever tooltip changes."] = "第一个可用等级已能打断；经常用震击输出时才值得升级，单为打断无需升级。请核实时光服技能说明的变化。"
language.strings["The official Survival change names Lacerating Strikes; this old spell candidate needs verification."] = "官方无限服生存改动提到的是撕裂打击，这个旧技能候选仍需核实。"
language.strings["The regular cat combo builder; other builds need it only when fighting as a cat."] = "猫形态常用连击点技能；其他天赋仅在用猫形态战斗时需要。"
language.strings["The riding fund is switched off everywhere: Settings, Global settings, Modules."] = "骑术储备金已全局关闭：设置 → 全局设置 → 模块。"
language.strings["The root works from rank 1. Since October 8 a low rank gets less from your spell power and triggers talents like Frostbite less often, so a Frost build leaning on those should keep it current."] = "1级即可定身。10月8日起，低等级的法术强度收益及寒霜刺骨等天赋触发率降低，依赖这些机制的冰霜路线应及时升级。"
language.strings["They gave: %s; gold %s"] = "对方给予：%s；金币 %s"
language.strings["This is a single-target option. Defer unused ranks if another attack replaces it."] = "这是单体选择；若已被另一攻击替代，可缓升不用的等级。"
language.strings["This list crafts one of these items. Choose another list, or make a new one."] = "此清单会制作其中一种物品。请选择其他清单，或新建清单。"
language.strings["This list crafts one of these materials. Choose another list, or make a new one."] = "此清单会制作其中一种材料。请选择其他清单，或新建清单。"
language.strings["Thousand Needles"] = "千针石林"
language.strings["Threat reduction helps cats in groups; skip for solo questing."] = "组队时可降低猫形态威胁，单人任务可跳过。"
language.strings["Thunder Bluff"] = "雷霆崖"
language.strings["Time used by Forever Ledger over the last %d seconds, slowest single moment first:"] = "Forever Ledger 最近 %d 秒的耗时，按单次最大耗时排序："
language.strings["Timing reset. Play for a minute, then /fl perf."] = "计时已重置。游玩一分钟后输入 /fl perf。"
language.strings["Tirisfal Glades"] = "提瑞斯法林地"
language.strings["Today: %s from %d jobs.   Last 7 days: %s from %d jobs."] = "今天：%s，完成%d次服务。   最近7天：%s，完成%d次服务。"
language.strings["Tooltip version:"] = "提示中的词缀版本："
language.strings["Tracking saves searching time but does not improve every fight."] = "追踪能节省寻找时间，但并非每场战斗都受益。"
language.strings["Trade"] = "交易"
language.strings["Train destinations you visit; every city need not be bought at once."] = "学习常去目的地的传送，不必一次买齐所有城市。"
language.strings["Training: %s teaches %d %s spells (%d services)."] = "训练：%s 教授 %d 个%s法术（共 %d 项服务）。"
language.strings["Training: couldn't read the trainer:"] = "训练：无法读取训练师："
language.strings["Travel and escape save repeated journeys and deaths."] = "赶路和逃脱可减少往返与死亡。"
language.strings["Turn alerts back on"] = "恢复提醒"
language.strings["Turn off Any price on that list, or make a new one, to keep the shuffle's limits."] = "请关闭该清单的“不限价格”，或新建清单，以保留加工套利的买入上限。"
language.strings["Un'Goro Crater"] = "安戈洛环形山"
language.strings["Unconfirmed Forever candidate; do not assume a Classic trainer or SoD unlock."] = "尚未核实的无限服候选技能，不要假定沿用经典版训练师或探索赛季解锁。"
language.strings["Undercity"] = "幽暗城"
language.strings["Undercut alert for %s: %s"] = "%s被压价：%s"
language.strings["Unlock armor upgrades when offered; compare the item's useful stats as well as armor."] = "训练师提供护甲类型升级时可学习；选择装备时也要比较有用属性。"
language.strings["Unlock better armor choices when available; use whichever item is actually an upgrade."] = "有条件时解锁更高护甲类型，但仍应选择实际提升的装备。"
language.strings["Unlock better armor choices; compare useful stats as well as armor."] = "解锁更好的护甲选择；同时比较有用属性。"
language.strings["Unlock poison use; confirm trainer versus quest acquisition."] = "解锁毒药使用；先确认通过训练师还是任务获取。"
language.strings["Unlock useful armor upgrades; choose stats suited to the build."] = "解锁有用的护甲类型升级；选择适合当前天赋的属性。"
language.strings["Until I log out"] = "直到退出游戏"
language.strings["Until I reload"] = "直到重载界面"
language.strings["Until I'm next in a city"] = "直到下次进入主城"
language.strings["Up to for disenchanting: "] = "分解价格上限："
language.strings["Up to for disenchanting: %s"] = "分解价格上限：%s"
language.strings["Up to: "] = "价格上限："
language.strings["Up to: %s"] = "价格上限：%s"
language.strings["Upgrade a poison used in your build; avoid paying for unused recipes."] = "升级当前天赋使用的毒药；避免为不用的配方付费。"
language.strings["Upgrade for a pet that regularly needs healing; other pet or sacrifice routes can defer it."] = "宠物经常需要治疗时升级；使用其他宠物或牺牲路线可暂缓。"
language.strings["Upgrade for deliberate AoE or close-range group healing; single-target questing can defer it."] = "明确用于范围攻击或近距离团队治疗时升级；单体任务可暂缓。"
language.strings["Upgrade for planned Fire or Arcane area damage; ordinary single-target Frost can skip."] = "计划使用火焰或奥术范围伤害时升级，普通单体冰霜可跳过。"
language.strings["Upgrade when this unlocked Fire attack is your regular opener or proc spender."] = "解锁后的火焰攻击若用于常规起手或消耗触发效果，应升级。"
language.strings["Upgrade while using it to finish targets; its Fire school is not a Fire-tree learning or recommendation restriction."] = "用于终结目标时应升级；属于火焰法术，不代表仅火焰天赋能学或值得推荐。"
language.strings["Use /fl deposit <item ID or shift-clicked item> [quantity] [2/8/24 hours]."] = "用法：/fl deposit <物品ID或Shift点击插入的物品> [数量] [2/8/24小时]。"
language.strings["Use /fl pair First Last, on both characters."] = "在两个角色上分别输入 /fl pair First Last（使用目标角色的完整姓名）。"
language.strings["Use /fl sync ping First Last, with someone who's online."] = "使用 /fl sync ping First Last 测试一名在线角色（填写完整姓名）。"
language.strings["Use a current defence buff; Demon Armor eventually replaces Demon Skin."] = "保持防御增益适合当前等级；恶魔护甲最终会取代恶魔皮肤。"
language.strings["Use an armor buff; avoid spending on an old family once your chosen armor replaces it."] = "保持一种护甲增益，选定后续护甲替代旧系列后，不必继续为旧系列花钱。"
language.strings["Use in a caster damage rotation when the target survives its duration."] = "目标能活到效果结束时，可用于施法伤害循环。"
language.strings["Use on longer fights; ordinary short pulls often favor Eviscerate instead."] = "适合长时间战斗；普通短战斗通常更适合剔骨。"
language.strings["Use on targets that survive the bleed; short cat fights favor a direct finisher."] = "用于能承受完整流血的目标，短暂猫形态战斗更适合直接伤害终结技。"
language.strings["Use the character's first and last name."] = "请使用角色的完整姓名。"
language.strings["Useful Arcane instant-cast burst or rescue once the chosen talents unlock it."] = "选定天赋解锁后，提供实用的奥术瞬发爆发或救场。"
language.strings["Useful Discipline burst once unlocked; not an ordinary baseline trainer purchase."] = "戒律解锁后可提供爆发；并非普通训练师基础技能。"
language.strings["Useful Fire burst once unlocked; its talent acquisition is separate from paid ranks."] = "解锁后的实用火焰爆发；天赋获取与付费技能等级需分别考虑。"
language.strings["Useful Fire pack control and damage once unlocked; single-target play can defer upgrades."] = "解锁后可提供火焰群体控制与伤害，单体玩法可缓升。"
language.strings["Useful Retribution control once unlocked; its first talent acquisition is separate from training."] = "解锁后可作为惩戒控制技能；首次通过天赋获取与后续训练是两回事。"
language.strings["Useful Shadow recovery in sustained fights; do not assume the Classic permanent effect in Forever."] = "持久战中有用的暗影恢复技能；不要假定时光服沿用经典旧世的永久效果。"
language.strings["Useful against dangerous caster spells; buy for those routes or PvP."] = "可应对危险法术；相关路线或 PvP 值得购买。"
language.strings["Useful against dangerous enemy buffs; routine enemies without buffs do not need it."] = "可移除敌人的危险增益；没有增益的普通敌人无需使用。"
language.strings["Useful against dangerous weapon users; not a routine damage priority."] = "可应对危险武器使用者；并非常规输出优先项。"
language.strings["Useful against melee packs but infrequent; not part of every pull."] = "对近战群怪有用，但使用频率较低；并非每次战斗都使用。"
language.strings["Useful attack target marking; Forever Survival talents also interact with it."] = "标记攻击目标很实用，也与无限服生存天赋联动。"
language.strings["Useful caster control; learn for caster-heavy routes, upgrades are secondary."] = "有用的施法者控制；施法者较多的路线值得学习，升级优先级较低。"
language.strings["Useful dagger stealth burst; weapon choice and opener play matter more than the tree label."] = "适合匕首潜行爆发；武器选择和起手方式比天赋分类更重要。"
language.strings["Useful damage while fighting nearby; keep current if it is part of your regular pulls."] = "在附近战斗时提供有效伤害；常规战斗使用时应及时升级。"
language.strings["Useful early before a pet and a ranged rotation; later ranks follow melee use."] = "无宠物、远程循环未成形的早期阶段有用，之后按近战使用情况升级。"
language.strings["Useful early damage before forms; a melee route can later defer damage ranks."] = "变形前的早期伤害有用；改为近战后可缓升伤害等级。"
language.strings["Useful finishing damage; buy ranks if you routinely have Rage to spend at low target health."] = "有效的斩杀伤害；目标低血量时经常有怒气可用，才值得购买等级。"
language.strings["Useful for deliberate caster packs; keep current if AoE is your leveling method."] = "有计划地群拉施法怪时有用；若靠范围伤害升级，应及时升级。"
language.strings["Useful for group-wide injury; not a routine solo or single-target heal."] = "适合全队受伤，不是常规单人或单体治疗。"
language.strings["Useful for harmful curses or groups; a route without curses can delay it."] = "面对有害诅咒或组队时有用，无诅咒路线可缓学。"
language.strings["Useful for planned Destruction or dungeon AoE; solo single-target fights can defer it."] = "计划进行毁灭或地下城范围输出时有用；单人单体战斗可暂缓。"
language.strings["Useful for stealth routes and facing control; optional for ordinary open combat."] = "有助于潜行路线和调整敌人朝向；普通正面战斗可选学。"
language.strings["Useful for threat-sensitive groups; no meaningful solo leveling value."] = "对需要控制仇恨的队伍有用；单人升级基本无收益。"
language.strings["Useful for water routes; ordinary land leveling can wait."] = "水路行程中有用；普通陆地升级可以缓学。"
language.strings["Useful if group damage draws threat; skip for solo leveling."] = "组队输出引来仇恨时有用；单人升级可跳过。"
language.strings["Useful if your melee route uses two-handers; acquisition is separate from a spell rank."] = "近战路线使用双手武器时有用；获取方式与法术等级训练不同。"
language.strings["Useful moving or follow-up healing; solo Shadow can defer ranks when direct heals suffice."] = "适合移动中或后续补充治疗；单人暗影在直接治疗足够时可暂缓升级。"
language.strings["Useful on longer fights or chained targets; short solo kills need not buy every rank."] = "适合长时间战斗或连续战斗；短时间单人击杀无需购买所有等级。"
language.strings["Useful on sufficiently long fights; even drain-tanking guides do not require it on every target."] = "战斗足够长时有用；吸血坦怪指南也不要求每个目标都使用。"
language.strings["Useful pack slow and burst; upgrade for regular Frost AoE, not just occasional control."] = "实用群体减速和爆发；经常冰霜群攻时升级，偶尔控制则不必。"
language.strings["Useful quick Fire casts or a chosen debuff rotation; ordinary Fireball questing does not need every rank."] = "适合快速火焰施法或指定减益循环，普通火球术任务路线不必学每个等级。"
language.strings["Useful ranged finishing damage; upgrade if you regularly spend Mana on it."] = "可用于远程斩杀；如果经常为此消耗法力，则值得升级。"
language.strings["Useful recurring disease removal; buy for disease-heavy routes or group healing."] = "可持续移除疾病；疾病较多的路线或团队治疗值得学习。"
language.strings["Useful rescue or pulling tool in groups; not needed for ordinary pet tanking."] = "组队中可救场或引怪，普通宠物坦怪通常不需要。"
language.strings["Useful treasure and group utility; not required for basic combat leveling."] = "用于宝箱和团队辅助；基础战斗升级并不要求学习。"
language.strings["Useful undead control; buy or upgrade when that route or dungeon needs it."] = "有用的亡灵控制；相关路线或地下城需要时再学习、升级。"
language.strings["Useful when fights last or talents support poison; short kills may favor Instant Poison."] = "长时间战斗或天赋强化毒药时有用；短战斗可能更适合速效毒药。"
language.strings["Useful when you or the pet take hits; not the usual ranged damage aspect."] = "你或宠物承受攻击时有用，不是常规远程输出守护。"
language.strings["Useful when your healing uses Holy Light or Flash of Light; not a routine solo damage buff."] = "使用圣光术或圣光闪现治疗时有用；单人输出时通常无需使用。"
language.strings["Useful while fighting in one place; repeated upgrades depend on your actual totem use."] = "在固定位置战斗时有用；后续升级取决于实际图腾使用情况。"
language.strings["Useful while tanking repeated hits; ordinary solo damage builds can spend on their main blessing."] = "坦克连续承受攻击时有用；普通单人输出可优先升级主要祝福。"
language.strings["Valuable demon or elemental control; ordinary targets outside those types do not need it."] = "有价值的恶魔或元素控制；其他类型普通目标无需使用。"
language.strings["Vendor it instead (deposit risk)"] = "改卖商店（有保管费风险）"
language.strings["Version %s is available (you have %s). Update on CurseForge or Wago."] = "新版本 %s 已发布（当前 %s）。可通过 CurseForge 或 Wago 更新。"
language.strings["WTS Mage water and food {water} {food}. Whisper me!"] = "出售法师水和食物 {water} {food}。欢迎私聊！"
language.strings["WTS portals to {portals}. Whisper me!"] = "出售前往 {portals} 的传送门。欢迎私聊！"
language.strings["Wait %d seconds before posting again."] = "请等待%d秒后再次发布。"
language.strings["Waiting for your next trade and the next vendor that sells for a currency; those will be reported too."] = "等待下一次交易及下一位使用特殊货币的商人；也会报告相关数据。"
language.strings["Warlock summon"] = "术士召唤"
language.strings["Warlock summons available, whisper me where you are and who's coming!"] = "术士可拉人，请私聊你的位置及需要召唤的人！"
language.strings["Water breathing and demon control suit particular quests."] = "水下呼吸和恶魔控制适合特定任务。"
language.strings["Water travel saves some journeys; not every route needs it."] = "水上移动可节省部分路程；并非每条路线都需要。"
language.strings["Western Plaguelands"] = "西瘟疫之地"
language.strings["Westfall"] = "西部荒野"
language.strings["Westfall and Darkshore coasts, Loch Modan"] = "西部荒野与黑海岸的海岸、洛克莫丹"
language.strings["Wetlands"] = "湿地"
language.strings["Whisper"] = "私聊"
language.strings["Winterspring"] = "冬泉谷"
language.strings["Work log: %s for %s%s."] = "服务记录：%s，为%s%s。"
language.strings["Worth upgrading for regular caster burst or packs; occasional melee pulls can defer it."] = "经常用于法术爆发或群怪时值得升级；偶尔近战拉怪可暂缓。"
language.strings["Yell"] = "大喊"
language.strings["Yes, share"] = "是，共享"
language.strings["Yes, turn it on"] = "是，开启"
language.strings["You gave: %s; gold %s"] = "你给予：%s；金币 %s"
language.strings["You're in a city again: customer alerts are back on."] = "你已进入主城：客户提醒已恢复。"
language.strings["You're not in the Trade or Services channel. Join it in a city first."] = "你尚未加入交易或服务频道。请先在主城加入。"
language.strings["Your auctions: %d listed, %d before, %d newly sold, %d waiting to be told (auction house %s)."] = "我的拍卖：当前%d笔，之前%d笔，新售出%d笔，待确认%d笔（拍卖行%s）。"
language.strings["Your auctions: entering the world, login %s, reload %s, %d undercut alerts remembered."] = "我的拍卖：进入世界，登录%s，重载%s，已记录%d条压价提醒。"
language.strings["Your auctions: the list came back empty; asking again before believing it."] = "我的拍卖：返回的列表为空；再次查询后再确认。"
language.strings["Your gold and sales will be shared with your sync partner."] = "你的金币与销售记录将与同步对象共享。"
language.strings["Your starting attack is essential before Frostbolt or another main attack is available; keep whichever filler you actually use current."] = "学会寒冰箭或其他主攻技能前，初始攻击不可少；常用填充攻击应及时升级。"
