language.strings["hidden, no prices for item %d (cheapest %s, usual from %s days)"] = "已隐藏，物品%d无价格（最低价%s，历史价格来自%s天）"
language.strings["hidden, switched off in Settings"] = "已隐藏，设置中已关闭"
