language.strings["purchase failed event, state "] = "购买失败事件，状态 "
language.strings["recipes recorded"] = "个配方已记录"
language.strings["recipes sold by"] = "个配方出售于"
language.strings["route cap"] = "方案买入上限"
language.strings["scan has:"] = "扫描记录："
language.strings["sell on the auction house"] = "在拍卖行出售"
language.strings["sells the Expert First Aid book"] = "出售中级急救教材"
language.strings["sells the Expert Fishing book"] = "出售中级钓鱼教材"
language.strings["shown for item %d at %s,%s (page %s,%s), visible %s, layer %s %d over the page's %d"] = "物品%d显示价格%s，%s（页面%s，%s），可见%s，窗口层级%s %d，页面层级%d"
language.strings["shuffle %s"] = "加工套利%s"
language.strings["slot %d: %s x%s%s"] = "栏位 %d：%s ×%s%s"
language.strings["still off"] = "仍不可用"
language.strings["the last one was %d hours ago"] = "上次扫描距今 %d 小时"
language.strings["the last one was for %s"] = "上次扫描属于%s"
language.strings["the last one was under a minute ago"] = "上次扫描距今不足一分钟"
language.strings["through his quests"] = "通过他的任务获取"
language.strings["tier %d; spells (player/known): %s; spellbook: %s"] = "层级 %d；法术（玩家/已知）：%s；技能书：%s"
language.strings["trainer recipes from"] = "个训练师配方，来自"
language.strings["until you log out"] = "直到退出游戏"
language.strings["until you reload or log out"] = "直到重载界面或退出游戏"
language.strings["until you're next in a capital city"] = "直到你下次进入主城"
language.strings["usual + %g%%: %s"] = "常见价加 %g%%：%s"
language.strings["was accepted"] = "已被接受"
language.strings["with Arcane Salvager"] = "有奥术回收装置"
language.strings["with Arcane Salvager (placed nearby, no buff seen)"] = "有奥术回收装置（已在附近放置，未检测到增益）"
language.strings["{professions} looking for work, your mats or mine. Whisper me!"] = "{professions} 代工，可自带材料或由我提供。欢迎私聊！"
language.strings["|cff%s%s|r, %s (%s listed)"] = "|cff%s%s|r，%s（在售 %s）"
language.strings["|cff888888no gold|r"] = "|cff888888无金币|r"
language.strings["|cffee8597Customer finder off.|r Silence > Turn alerts back on, or /fl customers on."] = "|cffee8597客户寻找已关闭。|r 可选“静音→恢复提醒”或输入 /fl customers on。"
language.strings["|cffffd100Quiet %s.|r New requests still show here."] = "|cffffd100已静音%s。|r 新需求仍会显示在此。"
language.strings["Qty"] = "数量"
language.strings["Affordable: %d, cost %s, estimated profit %s."] = "当前可买 %d 件，成本%s，预计利润%s。"
language.strings["  Auction house value is below today's cheapest: with few listed it uses this month's usual price, so a sudden rise doesn't count yet."] = "  拍卖估值低于当前最低价：挂单较少时采用本月常见价格，暂不计入突然上涨的价格。"
language.strings[" and %d more"] = "，另有%d项"
language.strings[" in Forever"] = "（时光服）"
language.strings["%s a day"] = "日均%s"
language.strings["%s%s at %s  %s"] = "%s%s，单价%s  %s"
language.strings["%s. From shuffle: %s. Uses the route's buying cap; the lower cap when two shuffles use this item. Refreshed when added again or on Buy again."] = "%s。加工套利来源：%s。价格上限取自该方案；两个方案共用此物品时取较低上限。重新添加或点击“再次购买”时刷新。"
language.strings["%s: Up to refreshed from usual prices and this list's allowance for %d %s. Change any you like; \"off\" means don't buy it."] = "%s：已按常见价格和清单允许的溢价更新 %d 个 %s 的价格上限。可自行修改；输入 off 表示不购买。"
language.strings["%sProfit %s %s (%d%%)%s."] = "%s利润%s（%s，利润率%d%%）%s。"
language.strings["(this one)"] = "（当前角色）"
language.strings[", about %s an hour"] = "，预计每小时%s"
language.strings["3 months"] = "三个月"
language.strings["A Holy healing candidate; confirm its unlock and value in the actual healing route before buying upgrades."] = "可作为神圣治疗技能；升级前先确认解锁条件，以及当前治疗是否用得上。"
language.strings["A Marksmanship damage candidate; confirm unlock and whether the ranged rotation actually uses it."] = "可能适合射击输出；先确认解锁方式，以及远程攻击循环是否用得上。"
language.strings["A bag's tooltip shows what one slot costs at today's cheapest price (auction house or vendor), and which bag is the cheapest per slot right now, so you buy the cheapest space first."] = "背包的物品提示会按当前最低拍卖价或商店售价计算每格成本，并列出当前每格成本最低的背包，方便购买。"
language.strings["A deal needs an item's usual price, so at least 4 days of your scans (or TSM). Keep scanning; they fill in."] = "判断低价机会需要物品的常见价格，至少要积累 4 天扫描数据，或使用 TSM 数据。继续扫描后会逐步补全。"
language.strings["A new profile starts as a copy of the settings this character has now, and this character switches to it. Rename renames the profile this character uses."] = "新配置方案会复制当前角色的设置，并立即切换到该方案。“重命名”会修改当前角色所用方案的名称。"
language.strings["A panel beside the auction house. The buy queue lines up everything worth buying; each mouse wheel tick (or click) buys the next one."] = "拍卖行旁的购买面板会列出值得购买的物品。每向下滚动一格或点击一次，就购买下一项。"
language.strings["A proposed Feral attack needs a client check; use it only if it belongs in the actual cat rotation."] = "可能适合野性输出，需在客户端确认；猫形态攻击循环用得上时再考虑。"
language.strings["A sidebar like EllesmereUI's: Global settings first (the same for every character: the auction house cut, safety margin, price source and what counts as a flip or a deal), then Profiles, then a page per part of the addon, with tabs across the top for its parts."] = "设置侧栏与 EllesmereUI 类似。顶部是所有角色共用的全局设置，包括手续费、安全余量、价格来源和套利判断条件。下方是配置方案和各项功能，每项顶部可切换标签页。"
language.strings["A strip on the Dashboard until this character knows riding (then epic riding): what it costs (from the riding trainer once you've seen one, else about 100g and 1,000g), your gold toward it and about how many days at your pace. Off everywhere in Settings, Global settings, Modules; Hide here on one character, /fl fund to show it again."] = "总览会显示尚未学会的骑术目标，学会后改为高级骑术。费用优先采用访问过的骑术训练师报价，否则按约 100 金和 1,000 金估算，并显示已备金币及按当前赚钱速度预计还需几天。可在“设置→全局设置→模块”中对所有角色关闭；条上的“隐藏”只影响当前角色，输入 /fl fund 可恢复显示。"
language.strings["A strip under the tiles: the riding this character doesn't know yet (then epic riding), what it costs, how much gold you have toward it and about how many days at your pace. It goes away once learned. Hide here (on the strip) hides it on one character; /fl fund shows it again."] = "金币卡片下方显示下一阶段骑术的费用、已备金币及按当前赚钱速度预计还需几天，学会后隐藏。“隐藏”只影响当前角色；输入 /fl fund 可恢复显示。"
language.strings["Added %d %s for %s to shopping list \"%s\". Check Want and Up to there; the Buy queue buys from the list while Buy from this list in the Buy queue is ticked (/fl lists)."] = "已将 %d 个%s（用途：%s）加入购物清单“%s”。请检查需求数量与价格上限；在购买队列中勾选“按此清单购买”后才会按清单购买（/fl lists）。"
language.strings["Added %d %s to shopping list \"%s\" for disenchanting. Check Want and Up to there; the Buy queue buys from the list while Buy from this list in the Buy queue is ticked (/fl lists)."] = "已将 %d 个%s加入分解购物清单“%s”。请检查需求数量与价格上限；在购买队列中勾选“按此清单购买”后才会按清单购买（/fl lists）。"
language.strings["Added the materials for %d %s of %s to shopping list \"%s\". Check Want and Up to there (/fl lists)."] = "已将制作 %d %s（%s）所需的材料加入购物清单“%s”。请检查需求数量与价格上限（/fl lists）。"
language.strings["After an update, chat lists what's new in that version, once. The What's new button (bottom right of Help and the Dashboard) or /fl new shows it as a card."] = "更新后首次登录，聊天中会列出本版本的变化。点击帮助或总览右下方的“更新内容”，或输入 /fl new，可再次查看。"
language.strings["An Arms attack candidate; buy upgrades only after confirming its unlock and place in the rotation."] = "可作为武器天赋攻击技能；确认解锁条件和循环用途后，再购买后续等级。"
language.strings["An Assassination attack candidate; confirm its unlock and whether it replaces an existing finisher."] = "可作为刺杀攻击技能；先确认解锁条件，以及是否替代已有终结技。"
language.strings["An Enhancement cooldown candidate; learn only after its current unlock and usefulness are confirmed."] = "可作为增强天赋的冷却技能；确认已解锁且实际有用后再学习。"
language.strings["Any tree regularly healing groups needs suitable heals; Restoration is the default priority context."] = "任何天赋只要经常治疗队伍，都需要合适的治疗技能；恢复天赋优先考虑。"
language.strings["Any tree regularly healing groups needs suitable support; Restoration is the default priority context."] = "任何天赋只要经常治疗队伍，都需要合适的治疗技能；默认优先推荐给恢复天赋。"
language.strings["At the auction house, click Buy queue: a panel beside it lists things selling for less than a vendor pays, with Watch flips to keep scanning while you're there. Click Buy to buy the next one, or scroll down over its top strip."] = "在拍卖行点击“购买队列”，侧栏会列出低于商店收购价的物品。点击“监测套利机会”可持续扫描；点击“购买”或在顶部栏向下滚动，可购买下一项。"
language.strings["At the auction house, click Full scan. It reads every listing in a few seconds; the game allows one about every 15 minutes. Prices and flips work from the first scan; deals and sell speed get sharper as a few days of scans build up."] = "在拍卖行点击“全量扫描”，几秒内读取全部挂单。游戏约每 15 分钟允许扫描一次。首次扫描后即可查看价格和卖店套利；低价转售与销售速度会随着扫描数据积累而更准确。"
language.strings["Below level 20: ways to make gold while leveling, best first, each priced from your scans (skinning, mining, herbs, cloth, bags, wands for casters, disenchanting and more). Lines for a profession you don't have are dimmed (tick Only my professions to hide them; other classes' lines never show), and (Classic) means not yet confirmed in Forever. Hover a line for what to do and why; click to search the auction house. Part of Leveling help: Settings, Global settings, Modules."] = "20 级以下角色可查看按扫描价格估算、从高收益到低收益排列的赚钱方式，包括剥皮、采矿、采药、布料、背包、法杖和分解等。未学专业的条目会变灰，勾选“仅我的专业”可隐藏；其他职业的条目不会显示。“经典旧世”表示尚未在无限服确认。悬停查看做法和理由，点击搜索拍卖行。可在“设置→全局设置→模块”中关闭升级赚钱建议。"
language.strings["Beside the auction house (Buy queue button, Disenchant finder tab): green armor and weapons in the item levels you pick (the Item levels dropdown, with Select all and Deselect all), with what each is worth to disenchant, on average, if you sell the materials. Hover a row to see each material's price and how that adds up. Hover a level in that list for the odds and what a bad and a good roll would bring (Settings, Auction house can hide the rolls). Pick a regular shopping list or New list, then Add to shopping list for one of every shown row your Enchanting can disenchant; right-click a row to add only it. Up to uses the disenchant value less the safety margin, refreshed when added again, on Buy again or by right-clicking Up to. Type a lower price for a bigger margin; typed prices stay yours. New lists start with buying off. Any stat version of each item will do."] = "在拍卖行旁的“购买队列→分解筛选”中选择装等，查看绿装武器和护甲分解后材料的平均转售价值。装等可全选或取消全选。悬停物品可查看材料价格和合计，悬停装等可查看产出概率及最低、最高价值，也可在设置中隐藏产出范围。选择普通清单或新建清单后，点击“加入购物清单”，会为附魔技能足够分解的每个条目各加一件；右键只添加当前条目。价格上限按分解价值扣除安全余量，重新添加、点击“再次购买”或右键价格上限可刷新。手动输入的更低价格会保留。新清单默认不启用购买；物品的任意随机属性版本均可。"
language.strings["Between full scans, the likeliest to turn into flips: items priced near what a vendor pays, weighed by how many get posted and bought each day (Linen Cloth before a rare item), with crafted items counting extra since crafters post them in bulk. Gear is left out."] = "全量扫描间隔期间，优先复查价格接近商店收购价、每天上架和买入数量较多的物品，例如亚麻布会先于稀有物品检查。制成品常被批量上架，因此额外提高复查优先级；不包含装备。"
language.strings["Buy at up to %s. "] = "买入上限%s。"
language.strings["Buy from this list in the Buy queue"] = "按此清单购买"
language.strings["Buy materials, craft, disenchant or convert, and sell, ranked by profit per hour. Click a row for every step. Blizzard nerfed most vendor shuffles, so Sells to a vendor may often be empty."] = "购买材料后制作、分解或转换，再出售，按预计每小时利润排序。点击条目查看步骤。暴雪已削弱多数加工卖店收益，“卖给商店”页可能经常为空。"
language.strings["Checks the auction house for everything on the list at once. Each item shows when it was checked (checking... and in line while it runs), how many are listed and the cheapest. Click an item to look at it on the auction house."] = "一次检查清单中的全部物品，显示查询时间、挂单量和最低价。查询期间会标注“查询中”或“排队中”。点击物品可在拍卖行查看。"
language.strings["Checks the auction house for everything on your lists ticked \"Buy from this list in the Buy queue\" (and the materials you're short of), one item at a time. What's at or under your price shows up here."] = "逐项检查已勾选“按此清单购买”的清单物品及短缺材料。价格不超过上限的挂单会出现在这里。"
language.strings["Click twice: the items come back by mail and the deposit is lost. Cancel next undercut at the bottom does them one after another."] = "点击两次确认撤拍：物品会退回邮箱，保管费不会退还。下方“取消下一项被压价拍卖”可逐笔撤拍。"
language.strings["Core larger heals for healing builds; Shadow upgrades depend on group healing or recovery needs."] = "治疗天赋的主要大额治疗技能。暗影是否升级，取决于组队治疗或自身恢复的需要。"
language.strings["Cost to craft: for items your recipes make, the materials at today's prices, the profit, and the materials to a shopping list for any number of crafts."] = "可制作的物品会显示按当前材料价格计算的制作成本和利润。选择制作次数后，可将所需材料加入购物清单。"
language.strings["Counted as you go, session or not: each dungeon's runs, time, coin and what dropped for you (going back in within 5 minutes is the same run). /fl runs lists them; item tooltips say \"Dropped for you: Deadmines, 2 in 14 runs\"."] = "无论是否开始收益统计，都会记录各副本的次数、耗时、金币和个人掉落。5 分钟内重新进入算同一次。输入 /fl runs 可查看；物品提示也会显示掉落记录，例如“死亡矿井：14 次中掉落 2 个”。"
language.strings["Deals tab, Booty Bay (top right): the neutral auction house against yours, each after its own cut (15% there, 5% here) and one unsold listing. Sells for more there: items worth at least 10% more sold at Booty Bay. Cheaper there: buy at Booty Bay, sell here. Its prices come from scanning there and are kept apart from yours; a tooltip line for big differences is in Settings, Tooltips."] = "“低价机会”页右上方的藏宝海湾视图会比较中立与本阵营拍卖行，分别扣除 15% 和 5% 手续费，并预留一次未售出挂单的保管费。“那里卖得更高”列出在藏宝海湾出售至少多赚 10% 的物品；“那里更便宜”列出可在中立拍卖行买入、回本阵营出售的物品。中立价格需到当地扫描，单独保存。价差较大的物品可显示额外提示，在“设置→物品提示”中开启。"
language.strings["Default: %d%s."] = "默认：%d%s。"
language.strings["Default: %g%s."] = "默认：%g%s。"
language.strings["Default: %s."] = "默认：%s。"
language.strings["Default: Auto."] = "默认：自动。"
language.strings["Doing something else while you wait for a chime? /fl quiet turns the game's sound off and plays Forever Ledger's chimes at full volume, even with the game in the background, plus a chime when you win an auction. It stays on for that character, through reloads and logins, until you type /fl quiet again. Quiet mode while the flip watch runs (Settings, Auction house, Alerts) does it by itself, and /fl pair offers to turn that on. Your sound settings come back afterward."] = "/fl quiet 会关闭游戏声音，以最大音量播放 Forever Ledger 提示音，游戏在后台时也生效，购买成功也有提示。对当前角色持续生效，重载和重登后保留，直到再次输入命令。也可在“设置→拍卖行→提醒”中设置为监测时自动启用；/fl pair 也会提示此选项。关闭后恢复声音设置。"
language.strings["Essential before the chosen Shadow attacks become available; later Shadow can defer its damage ranks."] = "选定的暗影攻击技能解锁前，应保留此技能的有效等级；后期暗影可暂缓升级伤害等级。"
language.strings["Everything Forever Ledger records is kept in its saved file on your computer. Nothing is sent to the author or anyone else."] = "Forever Ledger 记录的数据保存在你电脑上的插件存档中，不会发送给作者或其他人。"
language.strings["Everything this many crafts need, added to what the list already wants. Up to starts at your usual price plus the list's allowance; prices you typed stay. What you already have isn't taken off: check Want on the list."] = "将指定制作次数所需的材料追加到清单。价格上限初始按常见价格加清单溢价设置；手动输入的价格会保留。不会扣除已有材料，请检查清单中的需求数量。"
language.strings["Export copies this character's profile as text, with only the parts you tick. Import makes a new profile from someone's text. Only settings travel: never Global settings, gold or any of your data."] = "“导出”会把当前配置方案中勾选的设置复制为文本；“导入”会根据收到的文本创建新方案。只包含设置，不包含全局设置、金币或其他数据。"
language.strings["FL Clean: flat and quiet. FL Bronze: a bronze edge, gold titles, sections as cards, switches. FL Gilded: a bronze frame and gold serif titles. Looks based on WoW Forever's and Blizzard's own windows are coming."] = "简洁：扁平界面，减少装饰。青铜：铜色边缘、金色标题、卡片分区和开关。鎏金：铜色边框和金色衬线标题。以后将加入参考无限服及游戏原有窗口设计的主题。"
language.strings["Flip watch on: a full scan every 15 minutes, and items near vendor price re-checked in between. "] = "套利监测已开启：每 15 分钟进行一次全量扫描，其间复查价格接近商店收购价的物品。"
language.strings["For items added by hand. Each list starts at 10%; choose 0, 5, 10, 25 or another percentage. Applied when you switch buying on or click Buy again. Typed prices and shuffle caps stay as they are."] = "适用于手动添加的物品。每张清单默认允许高于常见价格 10%，可改为 0、5、10、25 或其他百分比。启用购买或点击“再次购买”时应用；手动价格和加工套利的价格上限会保留。"
language.strings["Forever Ledger hears it from guildmates and group members who have a newer version, and says so in chat once a session. It only shares the version number."] = "公会或队伍成员使用较新版本时，每次登录期间在聊天中提醒一次。只交换版本号。"
language.strings["Forever adds Attack Power scaling and Arms interactions; keep useful for targets that survive the bleed."] = "时光服增加了攻击强度加成和武器天赋联动。目标存活时间足以承受流血伤害时，应保持适用等级。"
language.strings["From disenchanting: item level %s %s. Uses the finder's disenchant buying limit after the safety margin, not this list's usual-price allowance. Refreshed when added again, on Buy again or by right-clicking Up to. Type a lower price for a bigger margin."] = "来自分解：物品等级 %s，%s。使用分解筛选扣除安全余量后的分解价格上限，不使用此清单的常见价浮动比例。再次添加、点击再次购买或右键价格上限时刷新。输入更低价格可增加安全余量。"
language.strings["Gold over %s"] = "金币变化（%s）"
language.strings["Hover Up to for its source. From a shuffle: its buying cap, not today's price; if two shuffles use an item, the lower cap wins. Add the shuffle again or use Buy again to refresh it. Added by hand: usual price plus this list's allowance (Pay up to X% over the usual price, starting at 10%); change the percentage on each list, then switch buying on or use Buy again to fill it. Type any price yourself, including off: it always wins and is never changed automatically. Existing limits are treated as yours. A shuffle route that can no longer be valued turns off until refreshed with known prices."] = "悬停价格上限可查看定价来源。加工套利使用方案的买入上限，多个方案共用材料时取较低值；重新添加方案或点击“再次购买”可刷新。手动添加的物品按常见价格加清单溢价设置，默认溢价为 10%；修改清单比例后，启用购买或点击“再次购买”即可更新。手动输入的价格（包括 off）始终优先，不会自动覆盖；已有上限也按手动价格保留。加工方案无法估值时会暂停，直到用有效价格刷新。"
language.strings["How many times you could do it profitably with what's listed now: only listings cheap enough count, and the scarcest thing you buy on the auction house sets the limit. \"no limit\" when everything comes from vendors."] = "按当前挂单估算还能盈利制作多少次。只计入价格足够低的挂单，以最短缺的拍卖材料为限；全部材料均可从商店购买时显示“不限”。"
language.strings["If Auctionator or another addon runs a full scan, Forever Ledger reads it too. With Auctionator, TSM or ForeverForge installed, features they already cover (like auction prices in tooltips, or a sound when an auction sells) are switched off once, with a message; turn them back on in Settings."] = "Auctionator 或其他插件完成全量扫描后，Forever Ledger 也会读取结果。检测到 Auctionator、TSM 或 ForeverForge 后，会关闭一次重复功能，例如拍卖价格提示和售出提示音，并在聊天中说明。可在设置中重新开启。"
language.strings["Items from your shopping lists ticked \"Buy from this list in the Buy queue\", at or under your price."] = "已勾选“按此清单购买”的购物清单物品，仅购买价格不超过上限的挂单。"
language.strings["Ledger, Sessions (or See all sessions on the Dashboard): every session with when, length, gold, what you looted, gold an hour and the character; sort by any column. Hover one for where its gold came from and the best loot."] = "账本的“游玩统计”页，或总览的“查看全部统计时段”，会列出每次统计的开始时间、时长、金币、拾取、每小时收益和角色。点击表头排序，悬停查看金币来源和价值最高的掉落。"
language.strings["Listings well below the price an item is usually cheapest at, to buy and resell: price now, usual low, how many are worth buying, profit after the cut and one unsold listing, and how sure it is (Good, Fair or Thin)."] = "列出明显低于常见最低价、可买入转售的挂单，显示当前价格、常见最低价、可买数量，以及扣除手续费和一次未售出保管费后的预计利润。另列出数据可靠程度：较可靠、一般或数据不足。"
language.strings["Listings well below the price they're usually cheapest at, to buy and resell. Hover a deal for why it's one; "] = "明显低于常见最低价、可买入转售的挂单。悬停查看判断依据；"
language.strings["Loot counts at the better of the auction house (after the cut) and a vendor; Settings can make it vendor only."] = "拾取物品按拍卖行扣除手续费后的价格与商店收购价中的较高者估值，也可在设置中改为只用商店收购价。"
language.strings["Make current if a dagger and positioning make this your main attack; a sword Combat route can skip it."] = "使用匕首且能满足站位要求、以此作为主要攻击时，应及时升级；战斗剑路线可跳过。"
language.strings["New list: %s"] = "新建清单：%s"
language.strings["No lists here yet: on the Shopping lists tab, tick Buy from this list in the Buy queue."] = "暂无可购买的清单。请在“购物清单”中勾选“按此清单购买”。"
language.strings["No sales for these filters yet. Auction sales are logged when you take the money from the mailbox; vendor sales as you sell."] = "当前筛选条件下暂无出售记录。领取拍卖邮件中的金币时记录拍卖收入，卖给商店时立即记录。"
language.strings["No shopping lists are bought from yet: on the Shopping lists tab, tick Buy from this list in the Buy queue."] = "尚未启用任何购物清单：请在“购物清单”中勾选“按此清单购买”。"
language.strings["No. Every purchase and auction is your own click (or wheel tick), as Blizzard requires. Forever Ledger finds, suggests and queues."] = "不会。游戏要求每次购买和上架都由你点击或滚动一次。Forever Ledger 只查找机会、提供建议并排好队列。"
language.strings["On the Sell tab, if a vendor pays more than your listing would bring after the auction house cut, a red line under Post says so and Post is grayed out until you click Post anyway. Settings, Auction house: untick Stop posts below vendor price to keep just the warning."] = "出售页中，若商店收购价高于拍卖扣除手续费后的收入，“上架”下方会出现红字，并暂停上架，直到你点击“仍然上架”。只想保留提示时，可在拍卖行设置中取消“阻止低于商店收购价上架”。"
language.strings["On the Sell tab, under the Create Auction button: your usual price and the cheapest now, with Undercut (1 copper under the cheapest) and Usual buttons that fill in the price. When the cheapest is well below usual it says so, so you can wait. You still click Post (Settings, Auction house)."] = "出售页的“创建拍卖”按钮下会显示常见价格和当前最低价。“压价”填入比最低价低 1 铜的价格，“常见价格”填入常见价格。最低价明显低于常见价格时会提示，供你决定是否稍后出售。仍需手动点击“上架”；可在拍卖行设置中调整此功能。"
language.strings["Open a shuffle or vendor flip, pick a regular list or New list, choose how many crafts (or items), then Add to shopping list. Its purchases and price limits are added; an existing item keeps its bought count and any price you typed. A disenchant group uses its cheapest item. Crate lists and lists with Any price are left out. New lists start with buying off: check Want and Up to and tick Buy from this list when ready."] = "打开加工套利或卖店套利条目，选择普通购物清单或新建清单，设置制作次数或物品数量，再点击“加入购物清单”。会添加采购物品和价格上限；已有条目保留已购数量及手动价格。分解组使用其中最便宜的物品，不使用补给箱清单或“不限价格”清单。新清单默认不启用购买，请先检查需求数量和价格上限，再勾选“按此清单购买”。"
language.strings["Open your class trainer: a panel beside it sorts what you can learn now into Must have, Nice to have and Skip while leveling (Dampen Magic, say), with the gold each costs and what you'd save. Spells for another tree than the one your talent points are in go to Skip; a spell you know but haven't cast in a week to Nice to have. Hover a spell for why and when to upgrade. It shows at class and portal trainers, not riding ones, and not once you're 60. Advice only: you train in Blizzard's window. Settings, Global settings, Modules."] = "打开职业训练师时，侧栏会将当前可学法术分为“必学”“可选”和“升级期间可暂缓”，并显示费用及可节省的金币。其他天赋系的法术归为可暂缓，已学但一周未施放的法术归为可选。悬停查看理由和升级时机。仅在职业和传送门训练师处显示，骑术训练师不显示，60 级后停止。这些仅为建议，学习仍在游戏原有窗口进行。可在“设置→全局设置→模块”中调整。"
language.strings["Post your crafting (with profession links) to Trade, and on those classes your food and water, portals, summons or lockpicking. Right-click a button to change the text."] = "在交易频道发布制作服务广告，并附上专业链接。相应职业还可提供食物饮水、传送门、召唤或开锁服务。右键按钮可修改广告内容。"
language.strings["Price history: every item keeps 90 days of daily prices, and full scans keep each version of random-stat gear (\"of the Eagle\") on its own."] = "价格历史：每件物品保存 90 天逐日价格，全量扫描会分别记录随机属性装备（如“雄鹰之”）的各个属性版本。"
language.strings["Price lookup: look any item up by name, even one you don't have, or Alt-click a listing at the auction house for that exact version."] = "价格查询：输入名称可查询尚未拥有的物品；Alt 点击拍卖挂单可查看该物品的具体属性版本。"
language.strings["Prices and their history, vendor and trainer locations you've seen, your characters' recipes, gold, sales and purchases, bags and bank, chat requests it spotted, and your work log."] = "保存价格历史、访问过的商人和训练师位置，以及角色的配方、金币、买卖记录、背包和银行数据。还会保存识别到的聊天需求和服务记录。"
language.strings["Profit %s"] = "%s利润"
language.strings["Profit: what a vendor pays for what you bought, less what it cost. Items a vendor won't buy are left out."] = "利润按已购物品的商店收购总价减去买入成本计算；商店不收购的物品不计入。"
language.strings["Quiet mode on this character, until you type it again: game sound off, chimes at full volume."] = "为当前角色切换安静模式：关闭游戏声音，以最大音量播放提示音，直到再次输入此命令。"
language.strings["Return"] = "利润率"
language.strings["Selling an item on the auction house (its Worth to you line), resale deals and the Booty Bay view allow for one 8-hour listing that doesn't sell (its deposit is lost). The deposit comes back when a listing sells. Materials further down a chain (dust from disenchanting, a craft's output) don't count it, so the Disenchant finder, shuffles, vendor flips and shopping-list limits are unchanged. If this makes selling to a vendor better, the option says Vendor it instead. Deposits use the auction house's quote when available, otherwise Classic's formula, which matches Forever: 5% of the vendor price per 2 hours (25% at Booty Bay), so 20% for 8 hours. Without a known vendor price, it's zero."] = "拍卖出售估值、低价转售和藏宝海湾比较都会预留一次 8 小时挂单未售出时损失的保管费；成交后保管费会退还。后续加工步骤中的材料不扣此项，分解筛选、加工套利、卖店套利和购物清单价格上限不受影响。若扣费后卖商店更划算，会建议卖商店。保管费优先采用拍卖行报价，否则按与无限服相符的经典公式估算：每 2 小时为商店收购价的 5%（藏宝海湾为 25%），8 小时为 20%。商店收购价未知时按 0 计算。"
language.strings["Sends your characters' gold, money in and out, Ledger entries and sessions to the character you linked (Settings, Characters), so both accounts' Dashboards and Ledgers show the same. These include your buyers' names, so leave it off if you linked a friend. Unlinking removes what you got from them."] = "将角色金币、收支、账本和统计时段记录发送给已配对角色，使两个账号显示相同的总览和账本。数据包含买家姓名；与朋友配对时请保持关闭。解除配对后，会删除从对方收到的数据。"
language.strings["Set by you. This price is never changed automatically. Automatic: %s. Right-click Up to to use the automatic price."] = "由你设定，不会自动修改。自动价格为%s。右键点击价格上限可恢复自动定价。"
language.strings["Short solo targets often die before armor reduction pays back; revisit for sustained group fights."] = "短时间单人战斗中，目标可能在破甲发挥作用前就已死亡；长时间团队战斗再考虑。"
language.strings["Sold since you were last here: %s. About %s with deposits back, in your mail or on the way (the Auctions tab, Sold)."] = "离开期间已售出：%s。加上退回的保管费约 %s，已到邮箱或正在寄送。可在“我的拍卖→已售出”查看。"
language.strings["Start one (Start a session at the top of the Dashboard, Ctrl-click on the minimap button, or /fl session start) and a small tracker you can drag counts what your time is worth: gold an hour, gold in and out, and what you loot (at the better of auction and vendor price; Settings can make it vendor only). Right-click the tracker to fold it to one line. Stop it to get a summary in chat; it joins the Dashboard's sessions. A session carries on through a logout on the same character."] = "在总览角色列表旁点击“开始统计”，或 Ctrl 点击小地图按钮、输入 /fl session start。可拖动的小窗口会记录金币收支、拾取价值和每小时收益。拾取默认按拍卖与商店价格中的较高者估值，也可改为只按商店收购价。右键可折叠为一行。停止后在聊天中汇总，并加入总览记录。退出游戏后记录会保留，下次登录同一角色时继续统计。"
language.strings["The Leveling tab (ways to make gold while leveling, under level 20), training advice at the class trainer and the riding fund on the Dashboard. Off: none of it runs, and the spells you cast aren't counted. It switches itself off on level 60 characters."] = "包含 20 级以下角色的赚钱建议、职业技能训练建议和总览中的骑术储备金。关闭后，这些功能会停止运行，也不再统计施放的法术。角色达到 60 级后自动关闭。"
language.strings["The auction house shows what's listed, not what sold. \"Sells\" counts listings that vanished before they could have expired (bought, or cancelled): a low estimate that gets better the more full scans you run, fastest with Watch flips."] = "拍卖行提供挂单数据，不提供真实成交记录。“售出”统计到期前消失的挂单，其中可能包含撤拍，只能用于粗略估计。全量扫描越多，数据越有参考价值；开启套利监测可更快积累数据。"
language.strings["The best of selling on the auction house, selling to a vendor, disenchanting, or crafting it into something, with the best few ways listed. Disenchanting counts what the materials sell for, as an average: each disenchant gives one result, and the tooltip shows the chance of each. Settings, Tooltips chooses which ways it counts (turn off crafting to leave out what your alts could make); shuffles and the Buy queue still count every way."] = "比较拍卖出售、卖给商店、分解和加工的收益，列出收益最高与次高的用途。分解按材料转售的平均收入估值，并显示各类产出的概率。可在“设置→物品提示”中选择计入哪些用途；加工套利和购买队列仍会考虑全部用途。"
language.strings["The color of what's active: the chosen tab, switches that are on, highlights. Auto uses EllesmereUI's color when it's installed."] = "用于选中的标签页、开启的开关和高亮内容。选择“自动”后，若已安装 EllesmereUI，会使用其配色。"
language.strings["The same for every character and profile: they decide what items are worth and what counts as a flip or a deal."] = "所有角色和配置方案共用，用来设置物品估值方式和套利判断条件。"
language.strings["Type \"Soldier's Armor of the Monkey\", or shift-click a link of that version, to keep just that version on a list. Search all looks up every version of gear; hover an item for each version's price, yours first."] = "输入带随机属性的装备全名（如“灵猴之士兵护甲”），或 Shift 点击对应链接，可只保留该属性版本。“搜索全部”会查询所有属性版本；悬停查看价格时，会优先显示你选定的版本。"
language.strings["Under the Create Auction button: the usual price and the cheapest now, and buttons to fill in 1 copper under the cheapest or the usual price. Says when the cheapest is well below usual."] = "在“创建拍卖”按钮下显示常见价格与当前最低价，并提供“压价”和“常见价格”按钮：前者填入比最低价低 1 铜的价格，后者填入常见价格。最低价明显低于常见价格时会提示。"
language.strings["Up to for disenchanting: "] = "分解价格上限："
language.strings["Up to for disenchanting: %s"] = "分解价格上限：%s"
language.strings["Up to: "] = "价格上限："
language.strings["Up to: %s"] = "价格上限：%s"
language.strings["Usual price + %g%% (this list's allowance). Refreshed when buying is switched on or on Buy again."] = "常见价格 + %g%%（本清单允许的溢价）。启用购买或点击“再次购买”时更新。"
language.strings["Vendor flip: %s at %s (vendor pays %s)"] = "卖店套利：%s，买价%s，商店收购价%s"
language.strings["What a session counts each looted item as worth. Auction house prices are after the cut; items that bind when picked up always count at vendor price. Start a session with /fl session start or on the Dashboard."] = "设置统计拾取物品时的估值方式。拍卖价格会扣除手续费，拾取绑定物品始终按商店收购价。可在总览点击“开始统计”，或输入 /fl session start。"
language.strings["What one is worth to you: the best of selling it on the auction house (after the cut), to a vendor, disenchanting it or crafting it into something."] = "比较拍卖出售（扣除手续费）、卖给商店、分解或加工的预计收益，取单件物品的最高价值。"
language.strings["While the flip watch runs: the game's music, effects, ambience and voices go off, and Forever Ledger's chimes play at full volume, even with the game in the background, plus a chime when you win an auction. Your sound settings come back when the watch stops. /fl quiet turns it on for one character until you type it again."] = "监测期间关闭游戏音乐、音效、环境音和语音，Forever Ledger 提示音以最大音量播放，游戏在后台时也生效；买到拍卖物品时也会提示。停止监测后恢复声音设置。/fl quiet 可为当前角色切换安静模式。"
language.strings["Worth to you and Buy at or below include crafting it into something (any of your characters' recipes) or converting it, like splitting an essence. Turn off if you'd rather not count what your alts could make."] = "“对你的价值”和价格上限会计入任意角色已学配方的制作收益，以及拆分精华等转换收益。不想计入其他角色能制作的物品时，可关闭。"
language.strings["Worth to you and Buy at or below include selling it on the auction house. Shuffles, the Buy queue and shopping lists always count every way."] = "“对你的价值”和价格上限会计入拍卖出售收益。加工套利、购买队列和购物清单仍会考虑全部用途。"
language.strings["You can afford %d of the %d cheap ones with %s%s, so the profit shown is for those. All %d would make %s."] = "当前可买 %d 个，共有 %d 个低价物品，可用金币 %s%s。利润按可买数量计算；买下全部 %d 个可获利 %s。"
language.strings["Your gold now and how it changed, profit, sales and expenses for the range you pick (Day to All time), the gold graph (hover it for any moment), the most profitable item and the biggest sale and purchase, how much you trade a day, and your sessions as a table. Start a session is next to the character list."] = "总览显示当前金币及变化、所选时段的利润、销售与支出。还可查看金币曲线、利润最高的物品、最大买卖记录、每日交易量和统计时段。角色列表旁可开始收益统计。"
language.strings["all time"] = "全部时间"
language.strings["at %s"] = "单价%s"
language.strings["click Buy, or tick Scroll to buy"] = "点击购买，或勾选滚轮购买"
language.strings["each"] = "每件"
language.strings["no limit"] = "不限"
language.strings["over 3 months"] = "近三个月"
language.strings["per craft"] = "每次制作"
language.strings["scroll down here to buy"] = "在此向下滚动滚轮购买"
language.strings["second"] = "秒"
language.strings["seconds"] = "秒"
language.strings["the day"] = "今日"
language.strings["the month"] = "本月"
language.strings["the week"] = "本周"
language.strings["the year"] = "本年"
language.strings["this month"] = "本月"
language.strings["this week"] = "本周"
language.strings["this year"] = "本年"
language.strings["today"] = "今日"
language.strings["top: %s"] = "最多：%s"
language.strings["trainer, or new in Forever"] = "训练师传授，或时光服新增配方（来源待确认）"
language.strings["|cffffd100Cancel your %d undercut %s? Each loses its deposit.|r Click again to start; then each click cancels the next."] = "|cffffd100撤下 %d 项被压价的 %s？每项都会损失保管费。|r再次点击开始，随后每次点击撤下一项。"
language.strings["(Classic)"] = "（经典服资料）"
language.strings["%dm ago"] = "%d分钟前"
language.strings["%dh ago"] = "%d小时前"
language.strings["%dd ago"] = "%d天前"
language.strings["%dm %02ds"] = "%d分%02d秒"
language.strings["%dh %02dm"] = "%d小时%02d分"
language.strings["%d seconds"] = "%d秒"
language.strings["%d minutes %d seconds"] = "%d分%d秒"
language.strings["Highest affordable profit first."] = "按当前可买数量的总利润从高到低排列。"
language.strings["Used by: %s"] = "使用角色：%s"
language.strings["last seen %s"] = "最后登录：%s"
language.strings["%d you can't afford yet (grayed below)."] = "%d 项金币不足，已显示为灰色。"
language.strings["%d over your limit (grayed below)."] = "%d 项超出花费上限，已显示为灰色。"
-- BEGIN upstream feca7a2 translations
language.strings["Watch paused while an item's page is open"] = "物品买卖页面打开时，暂停套利监测"
language.strings["Watch waits while you search"] = "正在搜索，套利监测暂缓"
language.strings["%d new %s below the usual price: see the Deals tab (/fl deals)"] = "发现 %d 个%s，价格低于常见价格。查看“低价机会”页（/fl deals）。"
language.strings["deal"] = "低价机会"
language.strings["deals"] = "低价机会"
language.strings["On the auction house: keeps scanning while it stays open and chimes when a new vendor flip turns up. It can only scan with the auction house open: it pauses when you close it and picks up again when you come back (Settings, Auction house: Resume the flip watch). It also waits while you're on one item's buy or sell page, so it doesn't change what the page shows; the status line says so, and it carries on when you go back to the list."] = "拍卖行打开时持续扫描，发现卖店套利机会时提示。关闭拍卖行后暂停，返回时可继续（设置→拍卖行→恢复套利监测）。查看单件物品的买卖页面或自行搜索时会暂缓查询，避免替换当前页面；状态栏会显示暂停原因。返回列表后继续。"
language.strings["Passive defense helps repeated melee fights in every build."] = "被动防御有助于所有天赋应对反复近战。"
language.strings["Forever adds melee Attack Power; prioritize it for Survival melee play."] = "无限服增加近战攻击强度加成，生存近战玩法优先。"
language.strings["Optional Mana recovery for long fights; prioritize your actual seal and healing needs."] = "长时间战斗中可选择的法力恢复手段；优先满足常用圣印和治疗需求。"
language.strings["Forever gives it to every race; prioritize when your route or group faces fear."] = "时光服向所有种族开放；路线或队伍需要应对恐惧时优先学习。"
language.strings["Observed Forever upgrades; prioritize only when your build actually uses this hybrid nuke."] = "已观察到无限服升级；仅在实际使用这种混合直接伤害法术时优先。"
language.strings["Shield-based tank damage and defense suit Protection; talent acquisition still gates it."] = "依赖盾牌的坦克伤害和防御适合防护天赋；仍需先获得对应天赋。"
language.strings["Optional racial attack; prioritize your main damage spells unless you use it regularly."] = "可选种族攻击；除非经常使用，否则优先升级主要输出法术。"
language.strings["Classic guide prioritizes rank 5 at level 40 for better recovery. Forever offers a level-40 service; use observed client ranks and tooltips for its exact label."] = "经典版指南优先在40级学习5级以改善恢复。已观察到无限服40级服务，准确名称应以客户端等级和提示为准。"
language.strings["Use a current defense buff; Demon Armor eventually replaces Demon Skin."] = "保持防御增益适合当前等级；恶魔护甲最终会取代恶魔皮肤。"
language.strings["A Feral damage cooldown candidate; prioritize only after its unlock and actual use are confirmed."] = "可能适合野性的爆发技能；先核实解锁方式和实际用途。"
language.strings["Forever effects need confirmation; prioritize only when this stone suits your actual build."] = "时光服效果仍需确认；此类石头适合当前天赋时再优先考虑。"
language.strings["Survival's melee defense matters once unlocked; ranged builds may also value the safety."] = "解锁后的生存近战防御很重要，远程路线也可能受益于额外安全性。"
language.strings["Central pet-based Demonology defense once unlocked."] = "恶魔学识解锁后，依赖宠物的核心防御技能。"
language.strings["Prioritize Arcane burst when the talent is unlocked; it is not ordinary first-rank training."] = "天赋解锁后优先考虑奥术爆发，不属于普通基础技能学习。"
language.strings["Hover any item to see what it's worth to you. Settings can make it short (today's cheapest price and what it's worth to you), with Shift for more. With 20 or more listed, selling on the auction house is valued from today's prices; with fewer, from this month's usual price if that's lower, so a few hopeful listings don't fool it, and a gray line says so."] = "悬停物品可查看对你的价值。设置中可选择精简提示（今日最低价与物品价值），按 Shift 查看更多。拍卖挂单至少有 20 件时按今日价格估值；更少时，若本月常见价更低则采用常见价，并以灰字说明，避免少量高价挂单影响判断。"
language.strings["Classic Arms and Fury guides prioritize its level-36 unlock even for single targets; confirm Forever acquisition."] = "经典旧世武器和狂暴指南优先学习 36 级解锁的此技能，单体也适用；请确认时光服获取方式。"
language.strings["Passive defense helps every build through repeated melee fights."] = "被动防御有助于所有天赋应对反复近战。"
language.strings["Provisional Protection attack; only prioritize after its Forever unlock is confirmed."] = "暂定为防护攻击技能；确认其在时光服的解锁条件后再优先学习。"
language.strings["Strong but self-damaging group AoE; only prioritize for that leveling method."] = "强力但会伤害自身的团队范围攻击；仅在采用此升级方式时优先学习。"
language.strings["Observed Forever Frost upgrades; prioritize if it is part of your frozen-target rotation."] = "已观察到无限服冰霜升级；属于冻结目标输出循环时优先。"
language.strings["Stances and transitions support movement, interruption and defense in every tree."] = "姿态及切换有助于所有天赋的移动、打断和防御。"
language.strings["Protection's primary shield attack once unlocked; prioritize for tanking."] = "防护解锁后的主要盾牌攻击；承担坦克时优先升级。"
language.strings["Provisional Restoration recovery; confirm Forever availability, then prioritize if used."] = "暂定为恢复续航技能；确认时光服可获取后，实际使用时优先学习。"
language.strings["Prioritize when your Assassination build unlocks and uses its burst."] = "刺杀天赋已解锁且使用此爆发技能时优先升级。"
language.strings["Prioritize for a Fury two-weapon route; two-handed builds can defer it."] = "狂暴双持路线优先学习；双手武器路线可暂缓。"
language.strings["Only prioritize repeated ranks for planned pack damage."] = "仅在计划进行群怪输出时优先购买后续等级。"
language.strings["Optional physical defense; core attacks and recovery come first."] = "可选物理防御；核心攻击和恢复技能优先。"
language.strings["Optional party weapon support; prioritize the totem your actual party uses."] = "可选的队伍武器辅助；优先升级队伍实际使用的图腾。"
language.strings["Optional Subtlety attack or defense; buy only if unlocked and used."] = "可选敏锐攻击或防御技能；已解锁并实际使用时再购买。"
language.strings["Official Forever Protection defense; prioritize only after the talent unlock."] = "时光服官方防护防御技能；解锁天赋后再优先考虑。"
language.strings["An alternative caster nuke; prioritize it when your talents and gear favor Arcane damage."] = "可替代的直接伤害法术；天赋和装备偏向奥术伤害时优先。"
language.strings["Forever's tank seal enables the Judgement taunt; prioritize for tanking in any tree."] = "时光服坦克圣印可让审判产生嘲讽效果；任何天赋承担坦克职责时都应优先学习。"
language.strings["Forever replaces the old cat resource tool; prioritize in cat play when its current unlock is confirmed."] = "无限服替换了旧版猫形态资源技能；核实当前解锁方式后，猫形态玩法优先学习。"
language.strings["Forever Holy can heal both caster and ally; prioritize when unlocked and healing groups."] = "时光服神圣天赋可同时治疗施法者和队友；解锁后用于团队治疗时优先学习。"
language.strings["Forever Arcane trainer upgrades are observed; prioritize when unlocked as your regular attack."] = "已观察到无限服奥术训练师升级，解锁并作为常用攻击后优先。"
language.strings["Optional Survival control attack; prioritize when it fits your melee play."] = "可选生存控制攻击，适合你的近战玩法时优先。"
language.strings["Classic Holy or Discipline guide can stop upgrades once Holy Fire is used as the opener; Shadow still prioritizes Mind Blast."] = "经典旧世神圣或戒律路线可在改用神圣之火起手后停止升级；暗影仍优先升级心灵震爆。"
language.strings["Classic Frost guide prioritizes rank 4 at 20 and rank 5 at 26; Fire can keep rank 1 for a quick slow: since October 8 a rank that low still slows but gets almost no spell power and never triggers Frost talents (Blizzard's own example)."] = "经典版冰霜指南20级学4级、26级学5级；火焰可保留1级快速减速。10月8日起，如此低的等级虽仍减速，但几乎不享受法术强度且不会触发冰霜天赋，这是暴雪给出的示例。"
language.strings["Before Frostbolt is learned, this is your starter damage even on a future Frost route. Classic Fire guide prioritizes rank 5 at 24; later Frost builds can skip unused Fireball upgrades."] = "学会寒冰箭前，即使计划走冰霜路线也需用它输出。经典版火焰指南24级优先学5级；后续冰霜可跳过不用的火球术等级。"
language.strings["A strong leveling imbue when you melee; prioritize the imbue you actually choose."] = "近战升级时有力的武器附魔；优先升级实际选用的附魔。"
language.strings["Optional racial defense or damage; only buy upgrades you use."] = "可选种族防御或伤害技能；只升级实际使用的等级。"
language.strings["The first time you open the window, a short welcome lists the five things to start with. Show it again with the button at the bottom left of this tab, or /fl welcome."] = "首次打开窗口会显示五项入门操作。可点击本页左下角按钮，或输入 /fl welcome，再次查看。"
language.strings["The best of selling on the auction house, selling to a vendor, disenchanting, or crafting it into something, with the best few ways listed. Disenchanting counts what the materials sell for, as an average: each disenchant gives one result, and the tooltip shows the chance of each. Hover damaged gear and the vendor way counts what a vendor pays for it as it is. Settings, Tooltips chooses which ways it counts (turn off crafting to leave out what your alts could make); shuffles and the Buy queue still count every way."] = "比较拍卖出售、卖给商店、分解和加工后的价值，并列出较优方案。分解价值按各结果的概率估算，物品提示会显示概率。查看受损装备时，商店价值按它当前状态下的卖价计算。可在“设置→物品提示”选择计入哪些用途；关闭加工可排除其他角色的配方。加工套利和购买队列仍会比较所有用途。"
language.strings["Click Buy queue on the auction house: a panel beside it lines up vendor flips and your shopping lists. It finds the next one by itself, and a click on Buy (or, with Scroll to buy ticked, a tick of the mouse wheel down over its top strip) buys it. Stacks of materials take a second tick to confirm the final price. Bottom right: what you bought this visit, what it cost and the profit if you vendored it (hover for the numbers). /fl queue."] = "点击拍卖行的“购买队列”，即可在侧栏查看卖店套利和购物清单。队列会自动寻找下一项，点击“购买”或在顶部提示区域向下滚轮购买。材料购买需要再确认一次最终价格。右下角显示本次买入数量、花费及卖店利润，悬停查看详情。也可输入 /fl queue 打开。"
language.strings["The panel's bottom row has Watch flips, Full scan and Scan materials (Stop watching and Stop scan while they run), with the scan's progress just above. While the panel is open beside the auction house, the same buttons under the auction house window are hidden."] = "侧栏底部提供套利监测、全量扫描和专业材料扫描，运行时可点击停止，进度显示在按钮上方。侧栏打开时，拍卖行窗口下方的同类按钮会隐藏。"
language.strings["Vendor flips or Shopping lists, switched at the top of the panel, one at a time; the one you're on is the one that buys, so a list never buys a flip by accident. Each has its own buttons at the bottom. When there is something to buy, the strip at the top glows (gold for Vendor flips, purple for Shopping lists); with Scroll to buy ticked it also shows a mouse wheel: that's where to scroll. A new flip that chimes switches the panel to Vendor flips, unless you're using a shopping list (something on it being looked up or bought, or a click or scroll there in the last 30 seconds); then a gold count on the Vendor flips button (and on the Buy queue tab) says it's there."] = "侧栏顶部可切换“卖店套利”和“购物清单”，只会购买当前视图中的物品。有可买物品时，顶部提示区域会发光：套利为金色，清单为紫色；开启滚轮购买后，此处会显示滚轮图标。新的套利提示会切到卖店套利视图；若购物清单正在查询、购买，或最近30秒内有点击或滚动，则保持清单视图，并在套利按钮及购买队列标签上显示金色数量。"
language.strings["Unlimited-stock vendor items show vendor under Up to on lists and stay out of the auction house queue, including hand-added items. Settings > Auction house > Buying: Buy vendor items on the auction house too (off by default) permits buying at the vendor price; a lower price or off that you typed is still respected. Your stored price is kept. Right-click an item's Up to box to use its automatic price again; the hover shows the underlying shuffle cap or usual price plus the list allowance while a typed price is in force. Limited-stock vendor items remain ordinary auction house items."] = "不限量的商店物品会在购物清单的价格上限下标为“商店”，默认不进拍卖购买队列，手动添加的物品也一样。可在“设置→拍卖行→购买”开启从拍卖行购买商店物品，以商店价格为上限；手动填的更低价格或 off 仍有效。右键价格框可恢复自动价格，悬停可查看加工套利上限或常见价格加清单溢价。限量商店物品仍按普通拍卖物品处理。"
language.strings["When most of what's listed is that cheap, the price has dropped and it's no bargain: rated Thin. Deals need at least 4 days of scans (or TSM). Thin data (few days, jumpy prices, usually only one listed) is hidden unless you tick Show doubtful deals too."] = "若多数挂单都已降到这个价格，通常说明市场价下跌，不能视为低价机会，可靠程度会标为“数据不足”。判断低价机会需要至少四天的扫描记录，或安装 TSM。扫描天数少、价格波动大、通常只有一件挂单的机会默认隐藏；勾选“显示存疑机会”可查看。"
language.strings["Sales and purchases one by one for 30 days, then as one line per item per month for a year. Gold and money in and out per day for a year, then per month. Prices per day for 90 days, then weekly for a year. Recipes, vendors, items and your characters are kept for good. Nothing is lost at a reload: only data past these ages is summed up or dropped."] = "买卖明细保存30天，之后按物品汇总为月记录，保留一年。金币及每日收支保存一年，之后按月汇总。每日价格保存90天，之后按周保存一年。配方、商店、物品及角色资料长期保留。重载不会清空数据，仅会汇总或清理超过保存期限的记录。"
language.strings["Type /idea on the Discord. You'll get updates in your post."] = "在 Discord 输入 /idea 提交建议，后续进展会回复在你的帖子中。"
language.strings["Only live sync to your own paired character (off until /fl pair), ads in Trade when you click an ad button, and your Forever Ledger version number to your guild and group, which can be turned off (Settings, Minimap and updates)."] = "仅会向你配对的角色实时同步数据（输入 /fl pair 前默认关闭）、在点击广告按钮后向交易频道发广告，以及向公会和队伍发送 Forever Ledger 版本号。版本广播可在“设置→小地图与更新”关闭。"
language.strings["The Price window: look up any item's price history."] = "价格窗口：查询任意物品的价格历史。"
language.strings["The Buy queue or shopping lists."] = "打开购买队列或购物清单。"
language.strings["Sessions: /fl session start or stop."] = "游玩统计：/fl session start 开始，/fl session stop 停止。"
language.strings["Your dungeon runs."] = "查看地下城记录。"
language.strings["Link or unlink your other account."] = "配对或解除配对自己的另一个账号。"
language.strings["The welcome card; what's new in this version."] = "查看欢迎页和当前版本更新内容。"
language.strings["Someone else bought them first, or their price is too old: finds over 15 minutes old are left out until a scan finds them again."] = "可能已被别人买走，或扫描结果已过期。超过15分钟的套利机会会暂时隐藏，下次扫描再次发现后恢复。"
language.strings["Shows new flips and deals in large text at the top of the screen, where raid warnings go. Turn it off if it covers your windows."] = "在屏幕顶部的团队警告位置显示新的套利与低价机会。若遮挡窗口，可关闭。"
language.strings["Chat line for new flips and deals"] = "在聊天中提示新的套利与低价机会"
language.strings["Lists each new vendor flip and deal in chat."] = "在聊天中逐项提示新的卖店套利与低价机会。"
language.strings["Reads every listing at once. The game allows one about every 15 minutes."] = "一次读取全部挂单，通常每15分钟允许一次。"
language.strings["Looks up the materials your recipes use, one item at a time."] = "逐项查询已知配方所需的材料。"
language.strings["No characters are ticked: pick some with the characters button above."] = "未勾选角色，请点击上方角色按钮选择。"
language.strings["No recipes saved yet. Open each profession's window once, then click Refresh."] = "尚未保存配方。打开一次各专业窗口，再点击“刷新”。"
language.strings["Press Ctrl+A, then Ctrl+C to copy. Paste it into Import on your other account."] = "按 Ctrl+A 全选、Ctrl+C 复制，再粘贴到另一个账号的“导入”窗口。"
language.strings["Press Ctrl+A, then Ctrl+C. Paste this into a spreadsheet to work with today's prices."] = "按 Ctrl+A 全选、Ctrl+C 复制，可粘贴到电子表格中分析当前价格。"
language.strings["A coordinated wipe tool can wait until organized group content."] = "团队灭团时使用的协作技能，可等开始有组织的团队活动后再学。"
language.strings["Search recipes"] = "搜索配方"
language.strings["The auction house shows what's listed, not what sold. \"Sells\" counts listings that vanished before they could have expired (bought, or canceled): a low estimate that gets better the more full scans you run, fastest with Watch flips."] = "拍卖行提供挂单数据，不提供成交数据。“售出速度”按到期前消失的挂单估算，其中也可能包括撤拍，因此只能作为参考。全量扫描越多，估算通常越准确，开启套利监测可更快积累数据。"
language.strings["New vendor flip: %s, %d at %s or less (vendor pays %s). It's in the Buy queue, under Vendor flips."] = "新的卖店套利：%s，共 %d 个，买价不高于 %s（商店收购价 %s）。请查看购买队列的“卖店套利”。"
language.strings["Nothing at these item levels is worth disenchanting right now. Untick Only worth disenchanting, or run a full scan."] = "这些物品等级内暂无适合分解的挂单。可取消“仅显示值得分解的物品”，或执行全量扫描。"
language.strings["Nothing listed at these item levels. Run a full scan, or pick other levels."] = "这些物品等级内暂无挂单。可执行全量扫描，或选择其他等级。"
language.strings["The cheapest one listed right now."] = "当前最低挂单价。"
language.strings["What it's usually cheapest at, from your scans."] = "根据扫描记录估算的常见最低价。"
language.strings["How far today's price is under the usual low."] = "当前价格低于常见最低价的幅度。"
language.strings["How many are listed at the deal price."] = "当前低价挂单中的物品数量。"
language.strings["How quickly it sells, from your scans."] = "根据扫描记录估算的售出速度。"
language.strings["What one brings after the cut and deposit, less what it costs."] = "每件卖出后，扣除手续费、保证金和买入成本的利润。"
language.strings["The same for every one at the deal price."] = "以当前低价买下全部物品后的预计总利润。"
language.strings["How far to trust it: Good, Fair or Thin. Hover a deal for why."] = "可靠程度分为可靠、一般和数据不足。悬停挂单可查看原因。"
language.strings["Show doubtful deals too"] = "显示存疑机会"
language.strings["Also lists deals with few days of prices, or prices that jump around, so the usual price is more of a guess."] = "也显示扫描天数较少或价格波动较大的机会；这些物品的常见价格估算不够可靠。"
language.strings["No deals that pass the checks right now. Tick \"Show doubtful deals too\" to see them."] = "当前没有通过检查的低价机会。勾选“显示存疑机会”可查看其余结果。"
language.strings["Quiet mode is on for this character. /fl quiet turns it off."] = "此角色已开启静音模式。输入 /fl quiet 可关闭。"
language.strings["Price window|r"] = "价格窗口|r"
language.strings["the list has all it wants, counting %d still waiting for an answer."] = "已达到清单数量，其中 %d 件仍在等待购买结果。"
language.strings["the list has all it wants."] = "已达到清单所需数量。"
language.strings["Checking how many the list still wants."] = "正在核对清单还需购买的数量。"
language.strings["Open the auction house to scan and buy."] = "打开拍卖行后可扫描和购买。"
language.strings["Click to buy this one next. Right-click to skip it until you reload."] = "点击后优先购买此物品。右键跳过，重载后恢复。"
language.strings["API check (include this in a bug report if something isn't working):"] = "API 检查（反馈功能异常时可附上此输出）："
language.strings["Sure?"] = "确认？"
language.strings["canceling..."] = "正在撤拍…"
language.strings["check prices"] = "请刷新价格"
language.strings["not priced"] = "尚无价格"
language.strings["auction"] = "挂单"
language.strings["auctions"] = "挂单"
language.strings["its deposit"] = "该挂单的保证金"
language.strings["their deposits"] = "这些挂单的保证金"
language.strings["|cffffd100Cancel %d undercut %s and lose %s?|r Click again."] = "|cffffd100撤下 %d 个被压价的%s，将损失%s？|r 再次点击确认。"
language.strings["Sell speed: compared with the full scan %d minutes ago. Bought (or canceled) for sure: %d units; reposted cheaper: %d; might have expired, not counted: %d."] = "售出速度：对比 %d 分钟前的全量扫描。确定成交或撤拍：%d 件；低价重新上架：%d 件；可能到期、未计入：%d 件。"
language.strings["Commands: /fl (window), /fl scan, /fl scan full, /fl scan materials, /fl stop, /fl watch, /fl quiet, /fl price, /fl queue, /fl lists, /fl pull, /fl export, /fl csv, /fl import, /fl source <auto/own/auctionator>, /fl shuffles, /fl shuffles all, /fl cut <percent>, /fl margin <percent>, /fl seconds <n>, /fl deals, /fl deals settings, /fl minimap, /fl money, /fl session start, /fl session stop, /fl runs, /fl de, /fl pair <name>, /fl sync, /fl tooltip, /fl welcome, /fl new, /fl api, /fl debug"] = "命令：/fl （主窗口）, /fl scan, /fl scan full, /fl scan materials, /fl stop, /fl watch, /fl quiet, /fl price, /fl queue, /fl lists, /fl pull, /fl export, /fl csv, /fl import, /fl source <auto/own/auctionator>, /fl shuffles, /fl shuffles all, /fl cut <percent>, /fl margin <percent>, /fl seconds <n>, /fl deals, /fl deals settings, /fl minimap, /fl money, /fl session start, /fl session stop, /fl runs, /fl de, /fl pair <name>, /fl sync, /fl tooltip, /fl welcome, /fl new, /fl api, /fl debug"
-- END upstream feca7a2 translations
-- BEGIN upstream e06486d translations
language.strings["The auction house won't sell that listing at its price, so it's skipped from now on."] = "该挂单无法按一口价购买，本次访问期间将跳过。"
language.strings["|cffff7070Vendor pays: %s%s|r"] = "|cffff7070商店收购价：%s%s|r"
language.strings[" for %d"] = "（共 %d 件）"
language.strings["Listing details: seller name on %d of %d; time left %s; a bid at the buyout on %d (left out), a starting bid at it on %d."] = "挂单详情：%d/%d 条有卖家名称；剩余时间 %s；%d 条竞价已达一口价（已排除），%d 条起拍价等于一口价。"
language.strings["Sell protection on %s: PostButton %s, GetItem %s, price from %s, quantity from %s."] = "上架保护 %s：上架按钮 %s，物品接口 %s，价格来源 %s，数量来源 %s。"
language.strings["auction %s at %d: bid %s, next bid %s, %s: passed over"] = "挂单 %s，价格 %d，竞价 %s，下次竞价 %s，%s：已跳过"
language.strings["auction %s at %d: bid %s, next bid %s, %s"] = "挂单 %s，价格 %d，竞价 %s，下次竞价 %s，%s"
language.strings["has a bidder"] = "已有竞价"
language.strings["no bidder"] = "暂无竞价"
language.strings["auction %s can't be bought at its price (code %s): passed over"] = "挂单 %s 无法按一口价购买（代码 %s）：已跳过"
-- END upstream e06486d translations
-- BEGIN upstream 04373e3 translations
language.strings["Watched items"] = "关注物品"
language.strings["Watched"] = "关注列表"
language.strings["watched"] = "已关注"
language.strings["Watched (%d)"] = "关注列表（%d）"
language.strings["Watch"] = "关注"
language.strings["Watch this item"] = "关注此物品"
language.strings["Watch, up to"] = "关注，最高价"
language.strings["Stop watching"] = "停止监控"
language.strings["Back to the queue"] = "返回购买队列"
language.strings["Shift-click, drag or type an item"] = "Shift 点击、拖入或输入物品"
language.strings["up to: vendor"] = "最高价：商店价"
language.strings["Couldn't find that item. Shift-click it from your bags or a chat link, drag it here, or type its name."] = "未找到该物品。请 Shift 点击背包物品或聊天链接、拖入物品，或输入物品名称。"
language.strings["Couldn't read that price. Try 2s, 1g 50s, 75c or a plain number for gold; leave it empty for the vendor price."] = "价格格式无法识别。可输入 2s、1g 50s、75c，纯数字按金币计算；留空使用商店价。"
language.strings["Watching %s, %s. The flip watch checks it every pass."] = "已关注%s，%s。每轮监控都会检查此物品。"
language.strings["up to "] = "最高价 "
language.strings["at the vendor price"] = "按商店价"
language.strings["Bought at %s or less, your price."] = "按你设置的最高价 %s 购买。"
language.strings["Bought at %s or less: a vendor pays %s, less your vendor flip margin."] = "最高买入价 %s，按商店收购价 %s 扣除卖店套利余量计算。"
language.strings["Not bought yet: vendors don't buy it, so type the most you'd pay in Up to."] = "尚未加入购买队列。商店不收购此物品，请填写最高买入价。"
language.strings["Gear is checked by the full scan (about every 15 minutes), not between them."] = "装备仅在全量扫描时检查，约每 15 分钟一次。"
language.strings["Click to search for it on the auction house."] = "点击在拍卖行搜索此物品。"
language.strings["Open the auction house, then click an item to search for it."] = "打开拍卖行后，点击物品即可搜索。"
language.strings["The most the Buy queue pays for it. \"vendor\": only when a vendor pays more (a vendor flip). A price of yours that's lower than that still buys vendor flips."] = "购买队列的最高买入价。vendor 表示仅购买卖店有利润的挂单。你设置的价格低于卖店套利上限时，仍会购买符合卖店套利条件的挂单。"
language.strings["Takes it off the list. Nothing you've bought is affected."] = "从关注列表移除此物品，已购买的物品不受影响。"
language.strings["%d watched. Green: at or under Up to right now."] = "已关注 %d 项。绿色表示当前价格未超过最高买入价。"
language.strings["Watch flips checks these every pass, on top of the items it picks. Anything at or under Up to joins Vendor flips, first in the list, and chimes. Up to \"vendor\": only when a vendor pays more."] = "每轮套利监控都会额外检查关注物品。达到最高买入价的挂单优先进入卖店套利队列，并发出提示音。最高价为 vendor 时，仅购买卖店有利润的挂单。"
language.strings["Adds the item. Leave the price empty to buy it only as a vendor flip, or type the most you'd pay: 2s, 1g 50s, or a plain number for gold."] = "添加关注物品。价格留空时仅做卖店套利，也可设置最高买入价，如 2s、1g 50s，纯数字按金币计算。"
language.strings["Nothing watched yet. Add an item above, or tick Watch in an item's price window."] = "暂无关注物品。可在上方添加，或在物品价格窗口勾选“关注”。"
language.strings["Watching %s at the vendor price. Type a price in Up to to buy it for more."] = "已按商店价关注%s。如需提高买入价，请填写最高价。"
language.strings["Items you always want checked, each with the most you'd pay. Watch flips checks them every pass, and they're bought here, first in the list. Add one here or with Watch in its price window."] = "设置需要持续检查的物品及最高买入价。每轮套利监控都会检查，符合价格的挂单在此优先购买。可在此添加，或在物品价格窗口勾选“关注”。"
language.strings["Watch flips checks it every pass, and the Buy queue buys it, first under Vendor flips, at or under the price here. \"vendor\": only when a vendor pays more. All of them: the Watched button on the Buy queue."] = "每轮套利监控都会检查此物品，价格达标后在卖店套利队列中优先购买。vendor 表示仅购买卖店有利润的挂单。点击购买队列的“关注列表”可管理全部物品。"
language.strings["Gear is checked by the full scan (about every 15 minutes), any version."] = "装备的各个版本仅在全量扫描时检查，约每 15 分钟一次。"
language.strings["The most to pay for it went down: checking again."] = "最高买入价已降低，正在重新检查。"
language.strings["Not buying %s: it's no longer watched or a vendor flip."] = "已停止购买%s，当前既未关注，也不符合卖店套利条件。"
language.strings["Watched item: up to %s, your price%s."] = "关注物品：你设置的最高价为 %s%s。"
language.strings[" (a vendor pays "] = " (商店收购价 "
language.strings["a watched item"] = "关注物品"
language.strings["a vendor flip"] = "卖店套利物品"
language.strings["vendor pays "] = "商店收购价 "
language.strings["Found %s: %s (%s), but you can't afford it yet: %s each, you have %s."] = "发现%s：%s（%s）。金币不足，单价 %s，现有 %s。"
language.strings["Watched item: %s at %s (up to %s)"] = "关注物品：%s，价格 %s（最高价 %s）"
language.strings["Watched item: %s, %d at %s or less. It's in the Buy queue, first under Vendor flips."] = "关注物品：%s，%d 件价格不高于 %s。已优先加入卖店套利购买队列。"
language.strings["Items you always want checked, each with the most you'd pay (Silk Cloth up to 2s for bandages, say). Watch flips checks them every pass, on top of the items it picks, and anything at or under your price joins Vendor flips, first in the list, and chimes. Leave the price at vendor to buy one only when a vendor pays more. Add one with Watch in its price window, or with the Watched button at the top of Vendor flips (shift-click, drag or type it); change Up to or remove it there. Gear is checked by the full scan, not between scans."] = "持续检查指定物品及最高买入价，例如以不高于 2 银的价格买丝绸制作绷带。每轮套利监控都会检查这些物品，价格达标后优先加入卖店套利队列并提示。最高价设为 vendor 时，仅购买卖店有利润的挂单。可在价格窗口勾选“关注”，也可点击卖店套利上方的“关注列表”，Shift 点击、拖入或输入物品，再修改最高价或移除。装备仅在全量扫描时检查。"
language.strings["Watched items: pick items to always check, each with the most you'd pay (or \"vendor\"). Watch flips checks them every pass, and they go first in the Buy queue's Vendor flips. Add one with Watch in its price window."] = "关注物品：指定物品及最高买入价，也可填 vendor 仅做卖店套利。每轮监控都会检查，价格达标后优先加入卖店套利购买队列。可在物品价格窗口勾选“关注”。"
language.strings["Buy queue: a row of several (bags) is bought one at a time, and buying goes on after a purchase that got no answer, as in the beta."] = "购买队列：同一挂单中的多件物品（如背包）逐件购买。某次购买未收到结果后，也能继续处理队列。"
language.strings["Vendor flips: items vendors buy are no longer marked \"vendors won't buy it\" partway through a session, which hid their flips until a reload."] = "卖店套利：修复商店可收购物品被误标为“不收购”，导致套利机会直到重载界面才恢复的问题。"
language.strings["Refused listings: one the auction house won't sell at its price is skipped, and a flip found gone stays off the list until a newer price comes in."] = "无效挂单：跳过无法按一口价购买的挂单。查询后已无货的套利物品，等待新价格后再显示。"
language.strings["Sell protection: on the stacks page the cut is worked out on the whole listing, so 20 at 19c no longer slips under a vendor's price."] = "上架保护：堆叠物品按整组计算手续费，修复逐件计算时漏报亏损的问题。"
language.strings["Undercuts: they need a price from the last 30 minutes, so a listing that's since sold can't get a fine auction canceled."] = "压价判断：仅采用最近 30 分钟的价格，减少过期低价导致的误撤拍。"
language.strings["Damaged gear: Worth to you uses what a vendor pays for it as it is."] = "受损装备：物品估值采用当前耐久度下的商店收购价。"
language.strings["You can afford %d of the %d cheap ones with %s%s, so the profit shown is for those. All %d would make %s."] = "可购买 %d/%d 件低价物品，可用金额为 %s%s。显示利润按可购买数量计算，全部 %d 件的利润为 %s。"
language.strings[" left to spend"] = "剩余额度"
language.strings["most to pay went down: %s to %s"] = "最高买入价降低：%s → %s"
language.strings["showed Vendor flips"] = "已切换到卖店套利"
language.strings["view left alone"] = "保持当前视图"
language.strings["flip chime, %d new: %s (panel %s, tab %s, view %s, state %s, current %s, list used %s)"] = "套利提示音，新增 %d 项：%s（面板 %s，标签 %s，视图 %s，状态 %s，当前项 %s，清单使用 %s）"
language.strings["Read the whole auction house between full scans"] = "全量扫描间隔中读取全部拍卖物品"
language.strings["The flip watch reads the auction house's whole list about every half minute (the same as a search with no name on the Buy page, whose list then shows every item, cheapest first) and looks closely at items that just got cheap enough. It waits while you're on an item's page and for a minute after your own search. Off: it checks about 120 likely items each time instead."] = "套利监控约每半分钟读取全部拍卖物品，再详细查询刚达到买入价的物品。购买页会显示全部物品，按最低价排序。打开单件物品页面时暂停，手动搜索后等待一分钟再继续。关闭后，每轮仅检查约 120 种可能有利润的物品。"
language.strings["On the auction house: keeps scanning while it stays open and chimes when a new vendor flip turns up. Between full scans (about every 15 minutes) it reads the auction house's whole list about every half minute, as a search with no name on the Buy page does, and looks closely at anything that just got cheap enough. So the Buy page's list shows every item, cheapest first; after your own search it waits a minute before replacing your results (Settings, Auction house: Read the whole auction house between full scans; off, it checks about 120 likely items each time instead). It can only scan with the auction house open: it pauses when you close it and picks up again when you come back (Settings, Auction house: Resume the flip watch). It also waits while you're on one item's buy or sell page, so it doesn't change what the page shows; the status line says so, and it carries on when you go back to the list."] = "拍卖行打开时持续扫描，发现新的卖店套利机会便提示。约每 15 分钟进行一次全量扫描，间隔中约每半分钟读取全部拍卖物品，再详细查询刚达到买入价的物品。购买页因此会显示全部物品并按最低价排序，手动搜索后会等待一分钟再替换结果。可在拍卖行设置中关闭“全量扫描间隔中读取全部拍卖物品”，改为每轮检查约 120 种可能有利润的物品。关闭拍卖行后暂停，返回时可按“恢复套利监控”设置继续。在单件物品的购买或出售页面也会暂停，并显示状态提示，返回列表后继续。"
language.strings["Watching flips: reading the auction house list, part %d"] = "套利监控：正在读取拍卖物品列表，第 %d 批"
language.strings["Flip watch on: a full scan every 15 minutes, and "] = "套利监控已开启，每 15 分钟全量扫描一次，"
language.strings["the whole auction house list read about every half minute in between. "] = "间隔中约每半分钟读取全部拍卖物品。"
language.strings["items near vendor price re-checked in between. "] = "间隔中复查接近商店收购价的物品。"
language.strings["A chime means a new flip. It pauses when you close the auction house and picks up when you come back."] = "提示音表示发现新的套利机会。关闭拍卖行时暂停，返回后继续。"
language.strings["Flip watch on: a full scan every 15 minutes, and the whole auction house list read about every half minute in between. A chime means a new flip. It pauses when you close the auction house and picks up when you come back."] = "套利监控已开启，每 15 分钟全量扫描一次，间隔中约每半分钟读取全部拍卖物品。提示音表示发现新的套利机会。关闭拍卖行时暂停，返回后继续。"
language.strings["Flip watch on: a full scan every 15 minutes, and items near vendor price re-checked in between. A chime means a new flip. It pauses when you close the auction house and picks up when you come back."] = "套利监控已开启，每 15 分钟全量扫描一次，间隔中复查接近商店收购价的物品。提示音表示发现新的套利机会。关闭拍卖行时暂停，返回后继续。"
language.strings["Couldn't read the whole auction house list "] = "连续读取全部拍卖物品列表失败 "
language.strings[" times in a row, so the flip watch checks likely items instead until you next open the auction house."] = " 次，本次访问改为检查可能有利润的物品，下次打开拍卖行后重新尝试。"
language.strings["Couldn't read the whole auction house list 3 times in a row, so the flip watch checks likely items instead until you next open the auction house."] = "连续 3 次读取全部拍卖物品列表失败，本次访问改为检查可能有利润的物品，下次打开拍卖行后重新尝试。"
language.strings["%d rows, %d items, in %d parts, %.1f s"] = "%d 条记录，%d 种物品，分 %d 批，耗时 %.1f 秒"
language.strings["Auction house list: %s. Cheaper listings gone on %d items (%d units); %d to look at closely%s; gear added %d, still listed %d."] = "拍卖物品列表：%s。%d 种物品的低价挂单已消失（%d 件），需详细查询 %d 种%s，新增装备 %d 种，仍在售 %d 种。"
