function language.TransformVisible(s, text)
  local inputSyntax = text:find("输入",1,true) or text:find("填写",1,true) or text:find("填入",1,true) or text:find("/fl ",1,true)
    if inputSyntax then return s end
    s=s:gsub("(%d+)h%s+(%d+)m", "%1小时%2分"):gsub("(%d+)m%s+(%d+)s", "%1分%2秒")
    local units={g="金",s="银",c="铜"}
    local out,at,previous={},1,0
    while true do
      local a,b,number,unit=s:find("(%d+%.?%d*)([gsc])",at)
      if not a then out[#out+1]=s:sub(at);break end
      local left,right=s:sub(a-1,a-1),s:sub(b+1,b+1)
      local allowed=(a==1 or not left:find("[%w_:.\\/]") or a==previous+1) and not right:find("[%a_]")
      out[#out+1]=s:sub(at,a-1)..number..(allowed and units[unit] or unit)
      if allowed then previous=b end
      at=b+1
    end
    s=table.concat(out)
    local months={Jan=1,Feb=2,Mar=3,Apr=4,May=5,Jun=6,Jul=7,Aug=8,Sep=9,Oct=10,Nov=11,Dec=12}
    s=s:gsub("%f[%a](%a%a%a) (%d%d)%f[^%d]",function(m,d)
      return months[m] and (months[m].."月"..tonumber(d).."日") or (m.." "..d)
    end)
    return s
  end

language.strings["Paused."] = "已暂停。"
language.strings["Click Resume below to carry on, or Go now to look this one up."] = "点击下方“继续”恢复监控，或点击“立即查询”检查此物品。"
language.strings["The game wants your click to confirm a stack of materials, so the Buy queue asks for a second tick again."] = "游戏要求手动确认堆叠物品，后续购买将恢复为两次点击或滚轮操作。"
language.strings["The game wants your click to confirm: one more tick buys them."] = "游戏要求手动确认，再点击一次或滚动一次即可购买。"
language.strings["Scroll anywhere over Vendor flips, or click Buy."] = "在卖店套利区域内滚动鼠标，或点击“购买”。"
language.strings["Scroll over this strip, or click Buy."] = "在此提示条上滚动鼠标，或点击“购买”。"
language.strings["Bought as soon as the final price comes back within your limit."] = "最终价格未超过你的上限时即会购买。"
language.strings["Pause"] = "暂停"
language.strings["scroll anywhere here to buy|r"] = "在此区域内滚动即可购买|r"
language.strings["Resume"] = "继续"
language.strings["Confirm stacks with a second click"] = "堆叠物品需再次点击确认"
language.strings["Watching flips: reading the AH list, part %d"] = "套利监控：正在读取拍卖物品列表，第 %d 批"
language.strings["The auction house hasn't sent the full scan yet; keep it open and it's read if it arrives. Paused, so nothing else is scanned meanwhile."] = "尚未收到拍卖行全量扫描结果。请保持拍卖行打开，收到后会继续读取。当前已暂停其他扫描。"
language.strings["watched items (the whole list is read once you've finished searching)"] = "关注物品（手动搜索结束后读取全部列表）"
language.strings["Scan paused."] = "扫描已暂停。"
language.strings["Paused: click Resume to carry on."] = "已暂停，点击“继续”恢复。"
language.strings["Each tick of the mouse wheel, up or down, buys the next item: anywhere over Vendor flips (drag the bar on the right to scroll its list), or over the top strip of Shopping lists. A stack of materials is confirmed in the same tick (unless Confirm stacks with a second click is ticked in Settings, Auction house). It keeps working while the list is empty, so new flips can be bought the moment they show up. Off: only clicking Buy buys."] = "向上或向下滚动一次鼠标即可购买下一项。可在卖店套利区域内滚动，购物清单则在顶部提示条上滚动。拖动右侧滚动条可浏览列表。堆叠物品在同次操作中确认，若需手动确认，可在拍卖行设置中开启“堆叠物品需再次点击确认”。列表为空时仍可操作，新物品出现后即可购买。关闭滚轮购买后，仅点击“购买”才会购买。"
language.strings["Keeps looking for flips while the auction house stays open: a full scan whenever the game allows one (about every 15 minutes), and the whole auction house list read about every 20 seconds in between. New flips chime and join the queue as soon as the part of the list they're in arrives. Click again to stop."] = "拍卖行打开时持续寻找套利机会，约每 15 分钟进行一次全量扫描，间隔中约每 20 秒读取全部拍卖物品。每批列表中发现的套利物品会立即提示并加入队列。再次点击停止监控。"
language.strings["Holds the flip watch and the Buy queue's own lookups, so your searches and the page you're on stay as you leave them. Buy, Go now and clicking a row still work. Click Resume to carry on; closing the auction house ends it too."] = "暂停套利监控和购买队列的自动查询，便于手动搜索和浏览。仍可点击“购买”“立即查询”或物品行操作。点击“继续”恢复，关闭拍卖行也会结束暂停。"
language.strings["Hover any item to see what it's worth to you. Settings can make it short (today's cheapest price and what it's worth to you), with Shift for more. With 20 or more listed, selling on the auction house is valued from today's prices; with fewer, from this month's usual price if that's lower, so a few hopeful listings don't fool it, and a gray line says so. What a disenchant or craft gives is valued at no more than its usual price this week, so a buyout that spikes a material's price doesn't make a disenchant look profitable."] = "鼠标悬停物品可查看估值。可设置简洁提示，仅显示今日最低价和物品价值，按住 Shift 查看更多。在售数量不少于 20 件时按今日价格估算拍卖收益，数量不足时采用今日价格与本月常见价格中的较低者，并显示灰色说明。分解产物和制作成品的估值最高采用本周常见价格，避免材料价格短时上涨造成虚假利润。"
language.strings["Holds the flip watch and the Buy queue's own lookups, so your searches and the page you're on stay as you leave them; Buy, Go now and clicking a row still work. Resume carries on, and closing the auction house ends it too. To check just what your recipes use, type /fl scan materials."] = "暂停套利监控和购买队列的自动查询，便于手动搜索和浏览。仍可点击“购买”“立即查询”或物品行操作。点击“继续”恢复，关闭拍卖行也会结束暂停。如需只扫描配方材料，可输入 /fl scan materials。"
language.strings["On the auction house: keeps scanning while it stays open and chimes when a new vendor flip turns up. Between full scans (about every 15 minutes) it reads the auction house's whole list about every 20 seconds, as a search with no name on the Buy page does, and looks closely at anything that just got cheap enough. The list comes cheapest first, in parts: a new flip chimes and goes to the Buy queue as soon as its part arrives, without waiting for the rest. So the Buy page's list shows every item, cheapest first; after your own search it waits half a minute before replacing your results (Settings, Auction house: Read the whole auction house between full scans; off, it checks about 120 likely items each time instead). It can only scan with the auction house open: it pauses when you close it and picks up again when you come back (Settings, Auction house: Resume the flip watch). It also waits while you're on one item's buy or sell page, so it doesn't change what the page shows; the status line says so, and it carries on when you go back to the list."] = "拍卖行打开时持续扫描，发现新的卖店套利机会便提示。约每 15 分钟进行一次全量扫描，间隔中约每 20 秒读取全部拍卖物品，再详细查询刚达到买入价的物品。列表按最低价分批到达，每批发现的机会立即加入队列并提示。购买页会显示全部物品，手动搜索后等待半分钟再替换结果。可在拍卖行设置中关闭“全量扫描间隔中读取全部拍卖物品”，改为每轮检查约 120 种物品。关闭拍卖行后暂停，返回时可按“恢复套利监控”设置继续。在单件物品的购买或出售页面也会暂停，返回列表后继续。"
language.strings["Click Buy queue on the auction house: a panel beside it lines up vendor flips and your shopping lists. It finds the next one by itself, and a click on Buy (or, with Scroll to buy ticked, a tick of the mouse wheel, up or down, anywhere over Vendor flips or over a shopping list's top strip) buys it. A stack of materials is confirmed in the same tick once its final price comes back within your limit (to confirm it yourself, tick Confirm stacks with a second click in Settings, Auction house). Bottom right: what you bought this visit, what it cost and the profit if you vendored it (hover for the numbers). /fl queue."] = "点击拍卖行的“购买队列”，可查看卖店套利和购物清单。插件自动查找下一项，点击“购买”即可操作。开启滚轮购买后，在卖店套利区域内或购物清单顶部提示条上向任意方向滚动也可购买。堆叠物品的最终价格未超过上限后在同次操作中确认，也可在设置中开启“堆叠物品需再次点击确认”。右下角显示本次访问的购买数量、花费和预计卖店利润，悬停可查看明细。命令 /fl queue。"
language.strings["The panel's bottom row has Watch flips, Full scan and Pause (Stop watching and Resume while they're on), with the scan's progress just above. While the panel is open beside the auction house, the same buttons under the auction house window are hidden."] = "面板底部提供套利监控、全量扫描和暂停按钮，运行时显示“停止监控”或“继续”，上方显示扫描进度。面板打开时，拍卖行窗口下方的同类按钮会隐藏。"
language.strings["Vendor flips or Shopping lists, switched at the top of the panel, one at a time; the one you're on is the one that buys, so a list never buys a flip by accident. Each has its own buttons at the bottom. When there is something to buy, the strip at the top glows (gold for Vendor flips, purple for Shopping lists); with Scroll to buy ticked it also shows a mouse wheel: scroll anywhere over Vendor flips (drag the bar on the right to scroll its list), or over a shopping list's top strip. A new flip that chimes switches the panel to Vendor flips, unless you're using a shopping list (something on it being looked up or bought, or a click or scroll there in the last 30 seconds); then a gold count on the Vendor flips button (and on the Buy queue tab) says it's there."] = "面板顶部可切换卖店套利或购物清单，当前视图决定购买内容，各自有独立按钮。有可购买物品时，顶部提示条亮起，卖店套利为金色，购物清单为紫色。开启滚轮购买后，可在卖店套利区域内或购物清单顶部提示条上滚动购买，拖动右侧滚动条可浏览列表。新套利提示会切换到卖店套利视图，使用购物清单期间则显示新增数量。"
language.strings["It never pays more than the limit shown (checked again on the final price) or more than you have, and every purchase starts with your own tick or click, as Blizzard requires. Scroll to buy only works with the mouse over Vendor flips or a shopping list's top strip; untick it to buy by clicking only. Right-click an item to skip it. Items you can't afford yet stay at the bottom of the list, grayed and marked can't afford, and are skipped until you have the gold; scroll past the last one you can buy and you get the error sound and a red message, once."] = "每笔购买都会核对最终价格，不超过显示的上限或可用金币。每笔购买由你点击或滚动鼠标发起。滚轮购买仅在卖店套利区域或购物清单顶部提示条生效。右键可跳过物品，金币不足的物品置于列表底部并显示灰色，待金币足够后再处理。滚过最后一个可购买物品时，仅提示一次。"
language.strings["No. Every purchase and auction starts with your own click (or wheel tick), as Blizzard requires; a stack's confirm can follow in the same tick. Forever Ledger finds, suggests and queues."] = "不会。每笔购买和上架均由你点击或滚动鼠标发起，堆叠物品可在同次操作中确认。插件负责查找、建议和排列队列。"
language.strings["Either. The big button (or the wheel, with Scroll to buy ticked) buys the next one. Clicking a row buys that one next."] = "两种都可以。点击大按钮或开启滚轮购买后滚动鼠标，会购买下一项。点击物品行则优先购买该项。"
language.strings["Off: a stack of materials is bought in one tick or click, since the one that starts the purchase also confirms it once the final price comes back within the limit and what you can spend. On: a second tick or click confirms it, after the final price is shown."] = "关闭时，一次点击或滚轮操作发起购买，最终价格未超过上限和可用金额后自动确认。开启时，显示最终价格后需再次点击或滚动确认。"
language.strings["The flip watch reads the auction house's whole list about every 20 seconds (the same as a search with no name on the Buy page, whose list then shows every item, cheapest first) and looks closely at items that just got cheap enough. It waits while you're on an item's page and for half a minute after your own search. Off: it checks about 120 likely items each time instead."] = "套利监控约每 20 秒读取全部拍卖物品，再详细查询刚达到买入价的物品。购买页会显示全部物品并按最低价排序。打开单件物品页面时暂停，手动搜索后等待半分钟再继续。关闭后，每轮仅检查约 120 种可能有利润的物品。"
language.strings["Holds the flip watch and the Buy queue's own lookups, so your searches and the page you're on stay as you leave them. Click Resume to carry on; closing the auction house ends it too."] = "暂停套利监控和购买队列的自动查询，便于手动搜索和浏览。点击“继续”恢复，关闭拍卖行也会结束暂停。"
language.strings["Faster flips: a new flip chimes and goes to the Buy queue as soon as its part of the auction house list arrives, not once the whole list is read, and the list is read about every 20 seconds instead of every half minute."] = "套利提示更快：每批拍卖列表到达后立即提示新机会并加入购买队列，无需等待全部列表。列表读取间隔缩短至约 20 秒。"
language.strings["Gear flips: looked up straight from the stat version the list saw, so they're ready to buy a moment after they're found."] = "装备套利：直接查询列表中的具体属性版本，发现后可更快准备购买。"
language.strings["Buy queue: carries on the moment the auction house is free again, and takes a new flip at once."] = "购买队列：拍卖行恢复可用后立即继续，新套利机会及时加入处理。"
language.strings["Rogue poisons: no longer vendor flips. The game gives them a vendor price, but vendors won't buy them."] = "盗贼毒药：已排除卖店套利。游戏虽返回商店价，但商店实际不收购。"
language.strings["the whole auction house list read about every 20 seconds in between. "] = "间隔中约每 20 秒读取全部拍卖物品。"
language.strings["scroll anywhere here to buy"] = "在此区域内滚动即可购买"
language.strings["Flip watch on: a full scan every 15 minutes, and the whole auction house list read about every 20 seconds in between. A chime means a new flip. It pauses when you close the auction house and picks up when you come back."] = "套利监控已开启，每 15 分钟全量扫描一次，间隔中约每 20 秒读取全部拍卖物品。提示音表示发现新的套利机会。关闭拍卖行时暂停，返回后继续。"
function language.FormatElapsed(s)
  return s < 60 and ("%d秒"):format(s) or ("%d分%d秒"):format(math.floor(s / 60), s % 60)
end
language.strings["Watching %s, %s. Watch flips looks for it every time it reads the auction house."] = "已关注%s，%s。套利监控每次读取拍卖行时都会检查此物品。"
language.strings["Gear: any stat version at or under the price."] = "装备会购买价格达标的任意属性版本。"
language.strings["Full scan done: %d listings across %d items in %s."] = "全量扫描完成：%d 条挂单，%d 种物品，耗时 %s。"
language.strings["Full scan done: %d listings across %d items, about %d min after Forever Ledger asked for one."] = "全量扫描完成：%d 条挂单，%d 种物品，约在请求 %d 分钟后收到。"
language.strings["Another addon ran a full scan; Forever Ledger read it too: %d listings across %d items in %ds."] = "已读取其他插件发起的全量扫描：%d 条挂单，%d 种物品，耗时 %d 秒。"
language.strings["Watching flips: waiting for the item page"] = "套利监控：等待退出物品页面"
language.strings["Watching flips: your search, list in %ds"] = "套利监控：手动搜索中，%d 秒后读取列表"
language.strings["Watching flips: next check in %ds%s"] = "套利监控：%d 秒后再次检查%s"
language.strings[", full scan in %d min"] = "，%d 分钟后全量扫描"
language.strings["nothing in between: this client can't read the whole list. "] = "当前客户端无法读取全部列表，间隔中不进行检查。"
language.strings["Couldn't read the whole auction house list "] = "连续读取全部拍卖物品列表失败 "
language.strings[" times in a row, so the flip watch tries again every half minute; full scans carry on as usual."] = " 次，套利监控改为每半分钟重试，全量扫描照常进行。"
language.strings["That's everything you can buy: the %d left %s more than %s, or %s waiting for a lower price."] = "当前可购买物品已买完。剩余 %d 项%s超出%s，或%s等待降价。"
language.strings["is"] = "正在"
language.strings["are"] = "正在"
language.strings["On the auction house: keeps scanning while it stays open and chimes when a new vendor flip turns up. Between full scans (about every 15 minutes) it reads the auction house's whole list about every 20 seconds, as a search with no name on the Buy page does, and looks closely at anything that just got cheap enough. The list comes cheapest first, in parts: a new flip chimes and goes to the Buy queue as soon as its part arrives, without waiting for the rest. While it reads, the Buy page's list shows every item, cheapest first; after your own search it waits half a minute before replacing your results. It can only scan with the auction house open: it pauses when you close it and picks up again when you come back (Settings, Auction house: Resume the flip watch). It also waits while you're on one item's buy or sell page, so it doesn't change what the page shows; the status line says so, and it carries on when you go back to the list."] = "拍卖行打开时持续扫描，发现新的卖店套利机会便提示。约每 15 分钟进行一次全量扫描，间隔中约每 20 秒读取全部拍卖物品，再详细查询刚达到买入价的物品。列表按最低价分批到达，每批发现的机会立即加入队列并提示。读取期间购买页显示全部物品，手动搜索后等待半分钟再替换结果。关闭拍卖行后暂停，返回时按“恢复套利监控”设置继续。在单件物品的购买或出售页面也会暂停，返回列表后继续。"
language.strings["Items you always want checked, each with the most you'd pay (Silk Cloth up to 2s for bandages, say). Watch flips looks for them every time it reads the auction house (about every 20 seconds), and anything at or under your price joins Vendor flips, first in the list, and chimes. Leave the price at vendor to buy one only when a vendor pays more. Add one with Watch in its price window, or with the Watched button at the top of Vendor flips (shift-click, drag or type it); change Up to or remove it there. For gear, any stat version at or under your price is bought."] = "设置持续关注的物品及最高买入价，例如以不高于 2 银的价格买丝绸制作绷带。套利监控约每 20 秒读取拍卖行，价格达标的物品优先加入卖店套利队列并提示。最高价填 vendor 时，仅购买卖店有利润的挂单。可在价格窗口勾选“关注”，或点击卖店套利上方的“关注列表”，Shift 点击、拖入或输入物品，再修改最高价或移除。装备会购买价格达标的任意属性版本。"
language.strings["No more freezes after a scan: a full scan's prices are saved a little at a time instead of freezing the game for over a second, and the check for new deals no longer stutters."] = "扫描后更流畅：全量扫描结果分批保存，避免一次保存导致长时间卡顿。新套利机会的检查也减少了卡顿。"
language.strings["One tick buys a stack: the tick that starts buying a stack of materials also confirms it, within your limit. Settings can bring back the second click."] = "一次操作购买堆叠物品：发起购买后，最终价格未超过上限便自动确认。可在设置中恢复二次点击确认。"
language.strings["Faster flips: the chime comes as soon as a flip is found, the list is read again after half a second, the next flip is looked up straight after a purchase, and buying carries on during full scans."] = "套利处理更快：发现机会立即提示，半秒后重读列表，购买后立即查询下一项，全量扫描期间也可继续购买。"
language.strings["Scroll to buy: up or down, anywhere over Vendor flips."] = "滚轮购买：在卖店套利区域内向上或向下滚动均可购买。"
language.strings["\"Refused\" purchases that went through: the Buy queue moves straight on instead of pausing, and no longer gives up on a row it's buying."] = "被提示“拒绝”但实际成功的购买：队列会立即继续，也会继续购买当前挂单的剩余物品。"
language.strings["Clearer status line: on a line of its own, and it says when the flip watch waits for your search."] = "状态提示更清楚：独占一行，并显示套利监控何时在等待手动搜索结束。"
language.strings["Watch flips looks for these every time it reads the auction house, about every 20 seconds. Anything at or under Up to joins Vendor flips, first in the list, and chimes. Up to \"vendor\": only when a vendor pays more."] = "套利监控约每 20 秒读取拍卖行并检查关注物品。价格不超过最高买入价的物品优先加入卖店套利队列并提示。最高价填 vendor 时，仅购买卖店有利润的挂单。"
language.strings["Watch flips looks for it every time it reads the auction house (about every 20 seconds), and the Buy queue buys it, first under Vendor flips, at or under the price here. \"vendor\": only when a vendor pays more. All of them: the Watched button on the Buy queue."] = "套利监控约每 20 秒读取拍卖行并检查此物品，价格达标后在卖店套利队列中优先购买。vendor 表示仅购买卖店有利润的挂单。点击购买队列的“关注列表”可管理全部物品。"
language.strings["When a full scan finds vendor flips and the Buy queue beside the auction house is closed, open it. New flips found between full scans only chime."] = "全量扫描发现卖店套利机会且购买队列关闭时，自动打开队列。两次全量扫描之间发现的新机会仅播放提示音。"
language.strings["Items you always want checked, each with the most you'd pay. Watch flips looks for them about every 20 seconds, and they're bought here, first in the list. Add one here or with Watch in its price window."] = "设置持续关注的物品及最高买入价。套利监控约每 20 秒检查，价格达标后在此优先购买。可在此添加，或在物品价格窗口勾选“关注”。"
language.strings["Couldn't read the whole auction house list 3 times in a row, so the flip watch tries again every half minute; full scans carry on as usual."] = "连续 3 次读取全部拍卖物品列表失败，套利监控改为每半分钟重试，全量扫描照常进行。"
language.strings["Close call"] = "收益接近"
language.strings["can't be sold on the auction house"] = "无法在拍卖行出售"
language.strings["vendors don't buy it"] = "商店不收购"
language.strings["a vendor pays as much or more"] = "商店收购价不低于拍卖收益"
language.strings["auction house %d%% more"] = "拍卖收益高 %d%%"
language.strings["sells slowly, but it's worth the wait"] = "出售较慢，但收益值得等待"
language.strings[", but it sells slowly"] = "，但出售较慢"
language.strings[", and it sells slowly"] = "，且出售较慢"
language.strings["after the cut and the deposit"] = "已扣除手续费和保证金"
language.strings["a quest needs it (%s)"] = "任务需要（%s）"
language.strings["you watch it"] = "你已关注此物品"
language.strings["it's on your list %s"] = "已加入清单 %s"
language.strings["%s's %s uses it"] = "%s的%s需要此物品"
language.strings["Keep: "] = "保留："
language.strings["Sell: "] = "出售："
language.strings["  or disenchant"] = "  或分解"
language.strings["about "] = "约 "
language.strings["Sell suggestion"] = "出售建议"
language.strings["All professions"] = "全部专业"
language.strings["All professions: Classic's recipes where no character of yours has opened the profession; %d left out, a material with no price yet."] = "全部专业：尚未打开过的专业采用经典旧世配方，因材料缺少价格而排除 %d 项。"
language.strings["No craft in any profession sells to a vendor for more than its materials cost at today's prices."] = "按今日材料价格计算，所有专业均无制作后卖店盈利的配方。"
language.strings[", none of yours"] = "，你的角色均未学会"
language.strings[", Classic recipe"] = "，经典旧世配方"
language.strings["On items in your bags: keep it (a quest needs it, a recipe of yours uses it, you watch it, it's on your list), or sell it to a vendor, at the auction house, or Close call when the two are near, with the reason; disenchanting too when it brings more. Only a suggestion: nothing is sold."] = "在背包物品上显示保留或出售建议。任务、角色配方、关注列表或购物清单仍需使用的物品建议保留，其余比较卖店和拍卖收益，收益接近时另作提示，并说明原因。分解收益更高时也会显示。仅提供建议。"
language.strings["Every profession's crafts that sell to a vendor for more than their materials cost at today's prices, whether or not one of your characters knows them. Recipes come from your profession windows; for professions none of your characters has opened, from Classic (not yet seen in Forever). Each one's steps say the profession and who of yours knows it. Recipes from is set aside while this is ticked."] = "显示所有专业按今日材料价格制作后卖店可盈利的配方，包括你的角色尚未学会的配方。数据优先采用已打开过的专业窗口，其余专业采用经典旧世数据，尚未在无限服确认。步骤中会标明专业及已学会的角色。勾选期间暂停使用“配方来源”筛选。"
language.strings["On items in your bags, one line saying what to do with it. Keep, when a quest still needs it, a recipe of one of your characters uses it, you watch it, or it's on one of your lists. Otherwise Sell: Vendor, Sell: Auction house (it brings clearly more after the cut and a deposit: a quarter more, or twice as much when it sells slowly), or Sell: Close call when the two are near, with the reason in gray. Soulbound items say Vendor, unless it's gear you can wear (then it's your call). When disenchanting brings more, that shows too, with your enchanter's name. Only a suggestion: nothing is sold. Off in Settings, Tooltips."] = "在背包物品上显示处理建议。任务、角色配方、关注列表或购物清单仍需使用的物品建议保留。其他物品比较商店收购价与扣除手续费和保证金后的拍卖收益，拍卖收益至少高出四分之一才建议上架，出售缓慢时则需达到两倍；收益接近时显示“收益接近”，灰色文字说明原因。灵魂绑定物品建议卖店，但可穿戴装备由你判断。分解收益更高时显示分解建议及附魔角色名称。仅提供建议，可在鼠标提示设置中关闭。"
language.strings["Buy materials, craft, disenchant or convert, and sell, ranked by profit per hour. Click a row for every step. Blizzard nerfed most vendor shuffles, so Sells to a vendor may often be empty. Tick All professions there to see every professions crafts that sell to a vendor for more than their materials, whoever knows them (Classics recipes for professions none of your characters has opened)."] = "购买材料，制作、分解或转换后出售，按每小时利润排序。点击物品行查看步骤。多数卖店套利配方已被削弱，因此“卖给商店”页可能为空。勾选“全部专业”可查看各专业制作后卖店可盈利的配方，包括角色尚未学会的配方。未打开过的专业采用经典旧世配方数据。"
language.strings["Keep: %s"] = "保留：%s"
language.strings["Sell: %s"] = "出售：%s"
language.strings["%s, none of yours"] = "%s，你的角色均未学会"
language.strings["%s, Classic recipe"] = "%s，经典旧世配方"
language.strings["auction house %d%% more, but it sells slowly"] = "拍卖收益高 %d%%，但出售较慢"
language.strings["auction house %d%% more, and it sells slowly"] = "拍卖收益高 %d%%，且出售较慢"
for english, translated in pairs(language.strings) do language.upper[string.upper(english)] = translated end
ns.RegisterLocale("zhCN", language)
